insert into sources (id, title, author, year, url, licence, notes) values ('gretil-bhg-ce', 'Bhagavadgita, text of the Poona critical edition of the Mahabharata (GRETIL)', 'Input by M. Tokunaga et al., revised by John Smith', null, 'https://gretil.sub.uni-goettingen.de/gretil/1_sanskr/2_epic/mbh/ext/bhgce__u.htm', 'public-domain', 'The Sanskrit text itself is ancient and public domain. This digital input is distributed by GRETIL for reference and research; credit GRETIL and the inputters. Devanagari is generated from the IAST by scripts/import/gita.py. Chapter 13 has 34 verses (the critical edition omits the extra opening verse found in some printed editions).');
