insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-14', 'en', 'Contact of the senses with their objects brings cold and heat, pleasure and pain. These come and go; they do not last. Bear them patiently, O Arjuna.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-2-14', 'en', 'Every feeling, good or bad, is a visitor, not a resident. If you remember that it will pass, you stop being thrown around by it.', 'Krishna begins with something everyone knows from daily life: the senses meet the world and we feel heat or cold, comfort or pain. His point is that these experiences are always moving. They arrive, stay a while and leave. The Sanskrit word titikṣā means patient endurance, a calm strength that lets you feel fully without being overturned. This is not about suppressing feelings. It is about knowing that you are bigger than any single feeling, so you can wait for it to pass and then act wisely.', '[{"word":"mātrā-sparśa","meaning":"contact of the senses with objects"},{"word":"anitya","meaning":"not lasting, temporary"},{"word":"titikṣā","meaning":"patient endurance"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-2-14-story', 'Thirteen years in the forest', 'After losing everything in a game of dice, the Pandavas lived twelve years in the forest and a thirteenth in disguise. Heat, hunger and humiliation came and went. They endured, and when the years ended they were still themselves.', 'Five brothers and Draupadi walking through a monsoon forest, calm faces under heavy rain.');
insert into verse_stories (verse_id, story_id) values ('gita-2-14', 'gita-2-14-story');
insert into teachings (verse_id, language, title, practice) values ('gita-2-14', 'en', 'Name the weather', 'When a strong feeling arrives today, say to yourself: this is weather, and weather passes. Wait ten breaths before reacting.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-14', 'According to this verse, pleasure and pain are...', array['Permanent', 'Temporary, they come and go', 'Only imagined', 'A punishment']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-14', 'What does Krishna ask Arjuna to do with them?', array['Avoid them', 'Fight them', 'Bear them patiently', 'Ignore all feelings forever']::text[], 2);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-2-20', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 20, 'Chapter 2, Verse 20', 'न जायते म्रियते वा कदाचिन्नायं भूत्वा भविता वा न भूयः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-20', 'en', 'The Self is never born and never dies. It did not come into being and will not cease to be. Unborn, eternal, everlasting and ancient, it is not killed when the body is killed.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-2-20', 'en', 'What you truly are is deeper than your body and your life story. That core cannot be harmed, which is a source of courage.', 'This is one of the most quoted verses of the Gita. Arjuna fears killing his elders, so Krishna lifts the conversation to a deeper level. The Self, called ātman, is not the body. It was not born when the body was born and does not end when the body ends. The verse piles up words for this: unborn, eternal, everlasting, ancient. For a reader today, it offers a steady place inside that loss and failure cannot touch, which gives the courage to face hard things.', '[{"word":"ātman","meaning":"the Self, your deepest being"},{"word":"aja","meaning":"unborn"},{"word":"nitya","meaning":"eternal"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-2-20-story', 'Nachiketa asks Death', 'In the Katha Upanishad, the boy Nachiketa is sent to Yama, the lord of death. Offered wealth and long life instead, he refuses and asks only one thing: what remains when a person dies? Yama, impressed, teaches him that the Self is never born and never dies.', 'A young boy sitting fearlessly before a calm, regal Yama at the gate of a quiet palace.');
insert into verse_stories (verse_id, story_id) values ('gita-2-20', 'gita-2-20-story');
insert into teachings (verse_id, language, title, practice) values ('gita-2-20', 'en', 'Find the still centre', 'Sit for two minutes and notice that thoughts and sensations change, but the one who notices them stays the same. Rest there.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-20', 'What does this verse say about the Self?', array['It dies with the body', 'It is never born and never dies', 'It is born every morning', 'It belongs to the gods']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-20', 'When the body is killed, the Self is...', array['Destroyed', 'Weakened', 'Not killed', 'Punished']::text[], 2);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-2-22', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 22, 'Chapter 2, Verse 22', 'वासांसि जीर्णानि यथा विहाय नवानि गृह्णाति नरोऽपराणि।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-22', 'en', 'Just as a person throws away worn-out clothes and puts on new ones, so the embodied Self casts off worn-out bodies and enters new ones.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-2-22', 'en', 'Change, even the biggest change, is like changing clothes. The wearer stays. This softens our fear of endings.', 'Krishna gives Arjuna a simple picture he can hold on to. We do not mourn an old shirt when we put on a new one. In the same way, the dehī, the one who lives in the body, moves from body to body. Indian tradition reads this as rebirth, but the verse also speaks to everyday change: jobs, homes and stages of life are outer clothing. Who you are underneath continues, and that makes letting go less frightening.', '[{"word":"vāsāṁsi","meaning":"clothes, garments"},{"word":"jīrṇa","meaning":"worn out, old"},{"word":"dehī","meaning":"the one who dwells in the body"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-2-22-story', 'Arjuna lays down his bow', 'On the field of Kurukshetra, Arjuna sees his teachers, grandfather and cousins on the other side. Overcome with grief, he drops his bow and refuses to fight. Krishna begins his teaching by reminding him that bodies change, but the Self does not.', 'Arjuna seated in his chariot with his bow on the floor, Krishna turning toward him with a gentle smile.');
insert into verse_stories (verse_id, story_id) values ('gita-2-22', 'gita-2-22-story');
insert into teachings (verse_id, language, title, practice) values ('gita-2-22', 'en', 'Let one old thing go', 'Pick one old habit, belief or grudge that no longer fits you. Write it down, and decide to set it aside like a worn-out shirt.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-22', 'What image does Krishna use in this verse?', array['A river', 'Changing old clothes for new', 'A burning lamp', 'A chariot wheel']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-22', 'Who ''changes clothes'' in this teaching?', array['The embodied Self', 'The king', 'The gods', 'The body']::text[], 0);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-2-47', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 47, 'Chapter 2, Verse 47', 'कर्मण्येवाधिकारस्ते मा फलेषु कदाचन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-47', 'en', 'You have a right to your actions alone, never to their results. Do not let the fruit of action be your motive, and do not be attached to doing nothing.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-2-47', 'en', 'Put your whole heart into the work and let go of the outcome. Results depend on many things; your effort depends on you.', 'Perhaps the most famous line of the Gita. It has four parts: you have a right to act; you have no claim over the results; do not let results be your only motive; and do not use this as an excuse to do nothing. Krishna is not saying results do not matter. He is saying they are shaped by many forces beyond you, so tying your peace to them makes you anxious. Do your best, offer it, and let the outcome come. This is the seed of karma yoga, the path of selfless action.', '[{"word":"karma","meaning":"action, work"},{"word":"adhikāra","meaning":"right, rightful claim"},{"word":"phala","meaning":"fruit, result"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-2-47-story', 'The heart of Krishna''s advice', 'Arjuna is frozen, afraid of what victory or defeat will cost. Krishna tells him that worrying about results is what paralyses him. His duty is to act well; the outcome is not his to own.', 'Krishna pointing forward from the chariot at sunrise, Arjuna lifting his bow again.');
insert into verse_stories (verse_id, story_id) values ('gita-2-47', 'gita-2-47-story');
insert into teachings (verse_id, language, title, practice) values ('gita-2-47', 'en', 'Effort, not outcome', 'Choose one task today and do it as well as you can without checking how it will be judged. Notice how much lighter it feels.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-47', 'According to this verse, you have a right to...', array['The results of your work', 'Your actions only', 'Other people''s actions', 'Rest only']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-47', 'Should you stop acting because results are uncertain?', array['Yes, avoid action', 'No, do not be attached to inaction', 'Only on holy days', 'Only if others agree']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-2-48', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 48, 'Chapter 2, Verse 48', 'योगस्थः कुरु कर्माणि सङ्गं त्यक्त्वा धनञ्जय।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-48', 'en', 'Established in yoga, perform your actions, giving up attachment, O Arjuna. Stay the same in success and failure. This evenness of mind is called yoga.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-2-48', 'en', 'Yoga is not only a posture. It is a balanced mind that does not swing wildly between winning and losing.', 'Here the Gita gives one of its clearest definitions: yoga is samatvam, evenness. Krishna calls Arjuna Dhanañjaya, winner of wealth, a reminder of his past successes, and then asks him to hold success and failure with the same steady mind. This is not indifference. You still care and still try hard, but your balance does not depend on how things turn out. Many teachers see this verse as the bridge between action and meditation.', '[{"word":"yoga-stha","meaning":"established in yoga"},{"word":"samatva","meaning":"evenness, equanimity"},{"word":"siddhi / asiddhi","meaning":"success / failure"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-2-48-story', 'Yudhishthira''s even mind', 'Yudhishthira, the eldest Pandava, was known for staying steady whether he was crowned king or sent into exile. Even after great losses, he answered questions of dharma calmly, which is why he was called Dharmaraja.', 'A calm king in simple forest clothes, seated beneath a banyan tree, half his face lit by sunset.');
insert into verse_stories (verse_id, story_id) values ('gita-2-48', 'gita-2-48-story');
insert into teachings (verse_id, language, title, practice) values ('gita-2-48', 'en', 'Same face for praise and blame', 'The next time you get praise or criticism today, pause and respond with the same calm tone either way.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-48', 'What does this verse call ''yoga''?', array['Physical strength', 'Evenness of mind', 'Fasting', 'Winning battles']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-48', 'How should one be in success and failure?', array['Proud in success', 'The same in both', 'Sad in both', 'Angry in failure']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-2-56', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 56, 'Chapter 2, Verse 56', 'दुःखेष्वनुद्विग्नमनाः सुखेषु विगतस्पृहः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-56', 'en', 'One whose mind is not shaken by sorrow, who does not crave pleasure, and who is free from attachment, fear and anger, is called a sage of steady wisdom.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-2-56', 'en', 'Wisdom shows in how we handle hard times and good times. A steady mind is free of craving, fear and anger.', 'Arjuna asks what a truly wise person looks like, and Krishna paints the sthita-dhī, the one of steady mind. In sorrow they are not shaken; in pleasure they do not grasp for more. Three forces that usually drive us, attachment (rāga), fear (bhaya) and anger (krodha), have lost their hold. The word muni means a sage, often one who is quiet. The verse gives us a practical mirror: when these three rise in us, we know where our work lies.', '[{"word":"sthita-dhī","meaning":"one of steady mind"},{"word":"rāga","meaning":"attachment, clinging"},{"word":"muni","meaning":"sage, quiet one"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-2-56-story', 'Rama hears of his exile', 'In the Ramayana, on the morning Rama was to be crowned, he was told he must instead leave for the forest for fourteen years. The poet Valmiki says his face did not change. He accepted it with the same calm he would have shown on his coronation.', 'Prince Rama bowing to his father in a palace hall, serene, while courtiers look on in shock.');
insert into verse_stories (verse_id, story_id) values ('gita-2-56', 'gita-2-56-story');
insert into teachings (verse_id, language, title, practice) values ('gita-2-56', 'en', 'Spot the three thieves', 'Notice today when craving, fear or anger tries to take over a decision. Just naming which one it is weakens its grip.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-56', 'A person of steady wisdom is free from...', array['Work and family', 'Attachment, fear and anger', 'All thinking', 'Food and sleep']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-56', 'In the story, how did Rama react to his exile?', array['He refused to go', 'He became angry', 'He accepted it calmly', 'He hid in the palace']::text[], 2);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-2-62', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 62, 'Chapter 2, Verse 62', 'ध्यायतो विषयान्पुंसः सङ्गस्तेषूपजायते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-62', 'en', 'When a person dwells on sense objects, attachment to them arises. From attachment comes desire, and from desire comes anger.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-2-62', 'en', 'Trouble starts small, with what we keep thinking about. Watch your thoughts early and you stop the chain before it reaches anger.', 'This verse and the next describe a chain reaction in the mind. It begins innocently: we keep thinking about something we like. Thinking becomes attachment (saṅga). Attachment becomes desire (kāma). When desire is blocked, it turns into anger (krodha). The next verse continues: anger brings confusion, confusion destroys memory and judgement, and then a person falls. The teaching is hopeful, because the earliest link, where our attention goes, is the easiest place to step in.', '[{"word":"dhyāyataḥ","meaning":"dwelling on, brooding over"},{"word":"saṅga","meaning":"attachment"},{"word":"kāma","meaning":"desire, craving"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-2-62-story', 'Ravana''s desire', 'In the Ramayana, Ravana hears of Sita''s beauty and cannot stop thinking of her. That thought grows into obsession, then into the abduction of Sita, and finally into the war that destroys his kingdom.', 'A brooding ten-headed king on a golden throne in Lanka, one hand clenched, dark clouds gathering behind.');
insert into verse_stories (verse_id, story_id) values ('gita-2-62', 'gita-2-62-story');
insert into teachings (verse_id, language, title, practice) values ('gita-2-62', 'en', 'Catch the first link', 'When you notice yourself replaying something you want, gently switch your attention to something else before it turns into craving.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-62', 'What does dwelling on sense objects lead to first?', array['Anger', 'Attachment', 'Peace', 'Wisdom']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-2-62', 'According to this verse, anger comes from...', array['Desire', 'Hunger', 'Sleep', 'Silence']::text[], 0);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-3-19', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 19, 'Chapter 3, Verse 19', 'तस्मादसक्तः सततं कार्यं कर्म समाचर।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-19', 'en', 'Therefore, always do the work that must be done, without attachment. By working without attachment, a person reaches the highest.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-3-19', 'en', 'You do not need to run away from the world to grow spiritually. Doing your duties with a free heart is itself the path.', 'In chapter three Arjuna asks why he should act at all if knowledge is higher than action. Krishna answers that action is unavoidable, so the question is how to act. The key word is asakta, unattached. Do the work that is yours to do, kārya, steadily and without clinging to rewards. Such work purifies the mind and leads to the highest good. This makes spiritual life possible for ordinary people with jobs and families, not only for monks.', '[{"word":"asakta","meaning":"unattached"},{"word":"kārya","meaning":"what ought to be done, duty"},{"word":"param","meaning":"the highest"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-3-19-story', 'King Janaka', 'In the very next verse, Krishna names King Janaka as an example. Janaka ruled a kingdom, managed courts and armies, and yet was known as a sage, because he did his work without clinging to it.', 'A king on a simple throne listening to petitioners, with a meditative stillness about him.');
insert into verse_stories (verse_id, story_id) values ('gita-3-19', 'gita-3-19-story');
insert into teachings (verse_id, language, title, practice) values ('gita-3-19', 'en', 'Do the next right thing', 'Pick one duty you have been avoiding and do it today, simply because it needs doing.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-3-19', 'How should necessary work be done?', array['With attachment', 'Without attachment', 'Only by priests', 'Only when rewarded']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-3-19', 'Which king is given as an example of this teaching?', array['Ravana', 'Janaka', 'Kamsa', 'Duryodhana']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-3-21', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 21, 'Chapter 3, Verse 21', 'यद्यदाचरति श्रेष्ठस्तत्तदेवेतरो जनः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-21', 'en', 'Whatever a great person does, others follow. Whatever standard they set, the world follows it.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-3-21', 'en', 'People learn more from what we do than from what we say. Anyone with influence, at home or at work, is setting an example.', 'Krishna explains why even a wise person who needs nothing should keep working: others are watching. The word śreṣṭha means the best or most respected person in a group. Whatever standard (pramāṇa) they set becomes the norm. Parents, teachers, managers and public figures all carry this responsibility. In the following verses Krishna says that he himself keeps acting, though he has nothing to gain, so that the world is not led astray.', '[{"word":"śreṣṭha","meaning":"the best, a leader"},{"word":"pramāṇa","meaning":"standard, example"},{"word":"anuvartate","meaning":"follows after"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-3-21-story', 'Rama, the model king', 'In the Ramayana, Rama is remembered as maryada purushottama, the ideal person who keeps to right conduct. He kept his promises even when it cost him, and the people of Ayodhya modelled their lives on his example.', 'Rama walking among ordinary townspeople in Ayodhya, children imitating his gentle posture.');
insert into verse_stories (verse_id, story_id) values ('gita-3-21', 'gita-3-21-story');
insert into teachings (verse_id, language, title, practice) values ('gita-3-21', 'en', 'Be the example', 'Think of one person who looks up to you. Do one thing today that you would be happy for them to copy.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-3-21', 'What do ordinary people do, according to this verse?', array['Ignore leaders', 'Follow the example of great people', 'Make their own rules', 'Avoid work']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-3-21', 'What is the main lesson?', array['Leaders can do as they like', 'Our actions set standards for others', 'Only words matter', 'Follow no one']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-3-35', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 35, 'Chapter 3, Verse 35', 'श्रेयान्स्वधर्मो विगुणः परधर्मात्स्वनुष्ठितात्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-35', 'en', 'It is better to follow your own duty imperfectly than to follow another''s duty perfectly. It is better even to die in your own duty; another''s duty is full of danger.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-3-35', 'en', 'Live your own life, not a copy of someone else''s. Your own path, done imperfectly, is worth more than borrowed success.', 'Svadharma means your own dharma, the duty and path that fits your nature, abilities and situation. Paradharma is someone else''s. Krishna says even an imperfect effort on your own path is better than a perfect copy of another''s. Arjuna, a protector by role, wanted to escape into the life of a renunciate; Krishna warns that this would be living against his grain. Today it reminds us that comparison is costly and that authenticity is a form of courage.', '[{"word":"svadharma","meaning":"one''s own duty or path"},{"word":"paradharma","meaning":"another''s duty"},{"word":"viguṇa","meaning":"imperfect, lacking merit"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-3-35-story', 'The warrior who wanted to be a monk', 'Arjuna, a warrior by nature and duty, told Krishna he would rather live as a beggar than fight. Krishna reminds him that running from his own role into someone else''s would not bring him peace.', 'Arjuna imagining himself as a wandering monk in a thought bubble, while Krishna gently points to the bow beside him.');
insert into verse_stories (verse_id, story_id) values ('gita-3-35', 'gita-3-35-story');
insert into teachings (verse_id, language, title, practice) values ('gita-3-35', 'en', 'Stop comparing', 'When you catch yourself envying someone''s path today, ask: what is my own next step? Then take it.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-3-35', 'Which is better, according to this verse?', array['Another''s duty done perfectly', 'Your own duty, even done imperfectly', 'No duty at all', 'Whatever pays most']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-3-35', 'What is ''svadharma''?', array['Your own duty or path', 'A type of prayer', 'A festival', 'A weapon']::text[], 0);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-4-7', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 7, 'Chapter 4, Verse 7', 'यदा यदा हि धर्मस्य ग्लानिर्भवति भारत।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-7', 'en', 'Whenever righteousness declines and unrighteousness rises, O Arjuna, then I manifest myself.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-4-7', 'en', 'However dark things get, goodness is never abandoned. The divine steps in when the world needs it most.', 'In chapter four Krishna reveals that he has taken birth many times. This verse gives the reason. Dharma is the order that holds life together: truth, fairness, duty and care. When it weakens (glāni) and adharma rises, the divine takes form to restore balance. This verse, with the next, is the basis of the teaching of avatāras, divine descents. It also carries a promise of hope: no age is so dark that goodness is abandoned.', '[{"word":"dharma","meaning":"righteousness, the order that sustains life"},{"word":"glāni","meaning":"decline, weakening"},{"word":"sṛjāmi","meaning":"I manifest, I send forth"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-4-7-story', 'The promise of the avatars', 'Indian tradition tells of Vishnu taking many forms, the avatars, to restore balance: Rama in the Treta age and Krishna in the Dvapara age among them. Here Krishna himself explains why he comes.', 'A luminous blue figure appearing above a darkened world, light spreading outward like dawn.');
insert into verse_stories (verse_id, story_id) values ('gita-4-7', 'gita-4-7-story');
insert into teachings (verse_id, language, title, practice) values ('gita-4-7', 'en', 'Be part of the answer', 'Notice one small wrong around you today, an unkind word or some litter, and quietly set it right.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-4-7', 'When does Krishna say he manifests?', array['Every new year', 'When righteousness declines', 'Only in temples', 'Never']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-4-7', 'What is ''dharma'' closest to in this verse?', array['Wealth', 'Righteousness', 'Power', 'Luck']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-4-8', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 8, 'Chapter 4, Verse 8', 'परित्राणाय साधूनां विनाशाय च दुष्कृताम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-8', 'en', 'To protect the good, to destroy evil, and to firmly establish righteousness, I come into being age after age.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-4-8', 'en', 'Protecting the good and standing against harm is a sacred act. In every age, goodness is renewed.', 'This verse completes the previous one by naming the purpose of each divine descent: to protect the good (sādhu), to remove those who do harm, and to firmly re-establish dharma. The phrase yuge yuge, age after age, tells us this is not a single event but a recurring pattern. Many readers also take it inwardly: whenever our own inner goodness is threatened, a higher strength can rise within us to protect it.', '[{"word":"paritrāṇa","meaning":"protection, rescue"},{"word":"sādhu","meaning":"good, virtuous person"},{"word":"yuge yuge","meaning":"in every age"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-4-8-story', 'Born in a prison', 'Krishna was born at midnight in the prison of the tyrant Kamsa, who feared him. The guards fell asleep, the doors opened, and his father Vasudeva carried the baby across the flooded Yamuna to safety in Gokul.', 'A father wading through a stormy river at night, holding a baby in a basket above his head, a great serpent sheltering them.');
insert into verse_stories (verse_id, story_id) values ('gita-4-8', 'gita-4-8-story');
insert into teachings (verse_id, language, title, practice) values ('gita-4-8', 'en', 'Protect someone', 'Stand up today for someone who is being treated unfairly, even in a small way.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-4-8', 'Why does Krishna come ''age after age''?', array['To collect offerings', 'To protect the good and establish righteousness', 'To rule the earth', 'To test people']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-4-8', 'Where was Krishna born, according to tradition?', array['In a palace', 'In Kamsa''s prison', 'In a forest', 'In Lanka']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-5-18', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 18, 'Chapter 5, Verse 18', 'विद्याविनयसम्पन्ने ब्राह्मणे गवि हस्तिनि।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-18', 'en', 'The wise see with an equal eye a learned and humble scholar, a cow, an elephant, a dog and an outcaste.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-5-18', 'en', 'True wisdom sees the same divine spark in every being, regardless of status, species or background.', 'This verse lists beings that society ranked very differently: a learned and humble scholar, a cow, an elephant, a dog, and an outcaste. The wise, paṇḍitāḥ, look at all of them with sama-darśana, an equal eye. This does not deny that people are different. It says the same divine reality is present in each, so dignity and respect are owed to all. It is one of the Gita''s strongest statements against prejudice.', '[{"word":"sama-darśin","meaning":"one who sees equally"},{"word":"paṇḍita","meaning":"a wise person"},{"word":"vinaya","meaning":"humility"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-5-18-story', 'Shankara meets an outcaste', 'A traditional story tells that the philosopher Adi Shankara, walking in Kashi, asked an outcaste to move out of his way. The man asked whether he meant his body or his Self, since the Self is the same in all. Shankara bowed to him as his teacher.', 'A young monk bowing before a humble man with four dogs on the ghats of a riverside city at dawn.');
insert into verse_stories (verse_id, story_id) values ('gita-5-18', 'gita-5-18-story');
insert into teachings (verse_id, language, title, practice) values ('gita-5-18', 'en', 'Equal eyes', 'Greet everyone you meet today, the cleaner, the shopkeeper, the stranger, with the same warmth you would give an honoured guest.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-5-18', 'How do the wise see all beings?', array['By rank', 'With an equal eye', 'By wealth', 'By caste']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-5-18', 'In the story, what did Shankara do after the conversation?', array['Walked away angry', 'Bowed to the man as his teacher', 'Called the guards', 'Left the city']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-6-5', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 5, 'Chapter 6, Verse 5', 'उद्धरेदात्मनात्मानं नात्मानमवसादयेत्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-5', 'en', 'Lift yourself up by your own self; do not let yourself sink down. For the self alone is your friend, and the self alone is your enemy.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-6-5', 'en', 'You can be your own best friend or your own worst enemy. Growth starts when you decide to lift yourself.', 'Krishna uses one word, ātman, in two senses here: the higher self and the everyday self. Lift the everyday self up with the higher self; do not drag yourself down. You can be your own best friend (bandhu) or your own worst enemy (ripu). The following verse explains that the self is a friend to one who has mastered it, and an enemy to one who has not. It is an early, powerful call to self-responsibility: no one else can do your inner work for you.', '[{"word":"uddharet","meaning":"one should lift up"},{"word":"bandhu","meaning":"friend, kin"},{"word":"ripu","meaning":"enemy"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-6-5-story', 'From robber to poet', 'Tradition tells that Valmiki was once a highway robber named Ratnakara. When the sage Narada asked whether his family would share the burden of his sins, and they said no, he turned inward, meditated for years, and became the poet who wrote the Ramayana.', 'A man in deep meditation as an anthill rises around him, the forest glowing softly.');
insert into verse_stories (verse_id, story_id) values ('gita-6-5', 'gita-6-5-story');
insert into teachings (verse_id, language, title, practice) values ('gita-6-5', 'en', 'Talk to yourself like a friend', 'When you notice harsh self-talk today, rephrase it the way a good friend would say it to you.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-6-5', 'Who can lift you up, according to this verse?', array['Only others', 'Your own self', 'Only luck', 'No one']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-6-5', 'The self can be your...', array['Friend only', 'Enemy only', 'Friend or enemy', 'Neither']::text[], 2);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-6-17', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 17, 'Chapter 6, Verse 17', 'युक्ताहारविहारस्य युक्तचेष्टस्य कर्मसु।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-17', 'en', 'For one who is moderate in eating and recreation, balanced in work, and regular in sleep and waking, yoga becomes the destroyer of sorrow.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-6-17', 'en', 'Spiritual life is built on simple, balanced daily habits. Not too much, not too little.', 'In chapter six Krishna teaches meditation, and he is practical. Yoga does not succeed for someone who overeats or starves, or who sleeps too much or too little. The word yukta means fitting or balanced. Balanced food (āhāra), balanced recreation (vihāra), balanced effort in work, and regular sleep and waking create the conditions where yoga becomes duḥkha-hā, the destroyer of sorrow. The spiritual path is built on simple daily habits.', '[{"word":"yukta","meaning":"balanced, moderate"},{"word":"āhāra","meaning":"food, eating"},{"word":"duḥkha-hā","meaning":"destroyer of sorrow"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-6-17-story', 'Not too much, not too little', 'Just before this verse, Krishna warns that yoga is not for one who eats too much or starves, or who sleeps too much or too little. The path he teaches is one of balance, not extremes.', 'A simple meal, a lamp and a bedroll arranged neatly in a sunlit hut, suggesting a balanced day.');
insert into verse_stories (verse_id, story_id) values ('gita-6-17', 'gita-6-17-story');
insert into teachings (verse_id, language, title, practice) values ('gita-6-17', 'en', 'One balanced habit', 'Pick one area, food, screens or sleep, and bring it back to moderation today.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-6-17', 'What does this verse recommend?', array['Extreme fasting', 'Moderation in food, work and sleep', 'Sleeping as much as possible', 'Constant work']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-6-17', 'For the balanced person, yoga becomes...', array['A burden', 'The destroyer of sorrow', 'Impossible', 'A competition']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-6-26', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 26, 'Chapter 6, Verse 26', 'यतो यतो निश्चरति मनश्चञ्चलमस्थिरम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-26', 'en', 'Wherever the restless, unsteady mind wanders, from there one should draw it back and bring it under the control of the Self.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-6-26', 'en', 'The mind will wander; that is its nature. The practice is simply to bring it back, again and again, without frustration.', 'Krishna knows the mind well. He calls it cañcala, restless, and asthira, unsteady. It will wander. The instruction is not to be harsh with it but to bring it back, every time, from wherever it has gone. A few verses later Arjuna admits the mind is as hard to hold as the wind, and Krishna agrees, adding that practice (abhyāsa) and letting go (vairāgya) make it possible. Every return is a small success.', '[{"word":"cañcala","meaning":"restless, flickering"},{"word":"niyamya","meaning":"having restrained, drawing back"},{"word":"vaśa","meaning":"control"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-6-26-story', 'The eye of the bird', 'In the Mahabharata, the teacher Drona placed a wooden bird in a tree and asked his students what they saw. Some saw the tree, the branches, their brothers. Arjuna said he saw only the bird''s eye, and only he was allowed to shoot.', 'A young archer drawing his bow, everything blurred except a small wooden bird''s eye in sharp focus.');
insert into verse_stories (verse_id, story_id) values ('gita-6-26', 'gita-6-26-story');
insert into teachings (verse_id, language, title, practice) values ('gita-6-26', 'en', 'Bring it back', 'Do one task today with full attention. Each time your mind wanders, gently bring it back without scolding yourself.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-6-26', 'What should you do when the mind wanders?', array['Give up', 'Draw it back gently', 'Follow it', 'Get angry at it']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-6-26', 'In the story, what did Arjuna see?', array['The whole tree', 'His brothers', 'Only the bird''s eye', 'The sky']::text[], 2);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-9-22', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 22, 'Chapter 9, Verse 22', 'अनन्याश्चिन्तयन्तो मां ये जनाः पर्युपासते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-22', 'en', 'To those who worship me with single-minded devotion, always united with me, I bring what they lack and preserve what they have.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-9-22', 'en', 'Wholehearted trust brings a deep sense of being looked after. You are not carrying your life alone.', 'Chapter nine is called the royal secret. Here Krishna speaks to those who are ananya, whose devotion is not divided, who think of him and stay connected. To them he promises yoga-kṣema. Yoga here means gaining what you lack and kṣema means keeping what you have. In other words, he carries their welfare. This verse is beloved in India and is often seen on homes and offices as a reminder that sincere trust is answered.', '[{"word":"ananya","meaning":"undivided, with no other"},{"word":"yoga-kṣema","meaning":"gaining what is needed and keeping what is gained"},{"word":"vahāmi","meaning":"I carry"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-9-22-story', 'Draupadi''s call', 'When Draupadi was dragged into the royal court and humiliated, no elder came to her help. She raised her hands and called on Krishna with complete trust, and the cloth kept growing endlessly so she could not be shamed.', 'A woman with hands raised in prayer as an endless stream of bright cloth flows around her in a royal hall.');
insert into verse_stories (verse_id, story_id) values ('gita-9-22', 'gita-9-22-story');
insert into teachings (verse_id, language, title, practice) values ('gita-9-22', 'en', 'Hand over one worry', 'Write down one worry you cannot control. Offer it up in your own words, then turn your attention to what you can do.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-9-22', 'What does Krishna promise single-minded devotees?', array['Fame', 'To bring what they lack and keep what they have', 'A long life', 'Victory in war']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-9-22', 'In the story, who called on Krishna for help?', array['Sita', 'Draupadi', 'Kunti', 'Radha']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-9-26', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 26, 'Chapter 9, Verse 26', 'पत्रं पुष्पं फलं तोयं यो मे भक्त्या प्रयच्छति।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-26', 'en', 'Whoever offers me with love a leaf, a flower, a fruit or a little water, that offering of love from a pure heart I accept.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-9-26', 'en', 'It is the love behind a gift that matters, not its size or cost.', 'After describing his vast cosmic forms, Krishna becomes tender. He asks for nothing grand: a leaf (patra), a flower (puṣpa), a fruit (phala) or water (toya). What matters is bhakti, love, and a sincere heart. This verse is the foundation of the simple offerings made in Indian homes every day. It also teaches a wider truth: the value of any gift lies in the love and attention behind it, not in its price.', '[{"word":"bhakti","meaning":"loving devotion"},{"word":"patraṁ puṣpaṁ phalaṁ toyam","meaning":"a leaf, a flower, a fruit, water"},{"word":"prayatātman","meaning":"one with a pure heart"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-9-26-story', 'Sudama''s rice', 'Sudama, Krishna''s poor childhood friend, visited him in Dwaraka with only a handful of flattened rice wrapped in cloth. Embarrassed, he tried to hide it, but Krishna took it and ate it with joy, treasuring it above any royal gift.', 'A king in fine robes joyfully eating rice from a worn cloth bundle, a thin poor man watching with tears.');
insert into verse_stories (verse_id, story_id) values ('gita-9-26', 'gita-9-26-story');
insert into teachings (verse_id, language, title, practice) values ('gita-9-26', 'en', 'Give small, give with love', 'Offer something small today, a kind note, a cup of tea, a flower, with full attention and love.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-9-26', 'What matters most in an offering, according to this verse?', array['Its price', 'The love behind it', 'Its size', 'Who sees it']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-9-26', 'What did Sudama bring to Krishna?', array['Gold coins', 'A handful of flattened rice', 'A horse', 'Silk clothes']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-12-13', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 12), 13, 'Chapter 12, Verse 13', 'अद्वेष्टा सर्वभूतानां मैत्रः करुण एव च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-12-13', 'en', 'One who hates no being, who is friendly and compassionate, free from possessiveness and ego, even-minded in pain and pleasure, and forgiving, is dear to me.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-12-13', 'en', 'This is a portrait of a good heart: no hatred, plenty of kindness, little ego, and an easy willingness to forgive.', 'Chapter twelve is about bhakti, and verses 13 to 20 describe the qualities of a person dear to God. This first verse lists several: free of hatred toward any being, friendly (maitra), compassionate (karuṇa), without possessiveness or ego, steady in pain and pleasure, and forgiving (kṣamī). Notice that these are not rituals but qualities of character. Many people read these verses slowly as a checklist for who they want to become.', '[{"word":"adveṣṭā","meaning":"one without hatred"},{"word":"karuṇa","meaning":"compassionate"},{"word":"kṣamī","meaning":"forgiving"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-12-13-story', 'Yudhishthira and the dog', 'At the end of the Mahabharata, Yudhishthira climbs toward heaven followed by a faithful dog. When told he may enter but the dog may not, he refuses to abandon it. The dog reveals itself as Dharma, his father, testing his compassion.', 'A king standing at a radiant gate, refusing to step through, a small dog at his feet on a snowy mountain.');
insert into verse_stories (verse_id, story_id) values ('gita-12-13', 'gita-12-13-story');
insert into teachings (verse_id, language, title, practice) values ('gita-12-13', 'en', 'Forgive one thing', 'Choose one small hurt you are holding on to and decide to let it go today.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-12-13', 'Which quality is listed in this verse?', array['Pride', 'Compassion', 'Ambition', 'Fear']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-12-13', 'In the story, why did Yudhishthira refuse to enter heaven?', array['He was afraid', 'He would not abandon the dog', 'He was tired', 'He wanted more gold']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('gita-18-66', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 66, 'Chapter 18, Verse 66', 'सर्वधर्मान्परित्यज्य मामेकं शरणं व्रज।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-66', 'en', 'Setting aside all other duties, take refuge in me alone. I will free you from all wrongs. Do not grieve.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('gita-18-66', 'en', 'After all the teachings, the final word is trust. Let go of anxiety and rest in the divine.', 'This is often called the carama śloka, the final and crowning verse of the Gita''s teaching. After eighteen chapters on action, knowledge, meditation and devotion, Krishna says: set aside every other support and take refuge (śaraṇa) in me alone. I will free you from all wrongs. Do not grieve. Teachers explain it in different ways, but all agree it is about complete trust. The Gita began with Arjuna''s grief, and it ends with mā śucaḥ, do not grieve.', '[{"word":"śaraṇa","meaning":"refuge, shelter"},{"word":"mokṣayiṣyāmi","meaning":"I will set you free"},{"word":"mā śucaḥ","meaning":"do not grieve"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('gita-18-66-story', 'Arjuna''s doubt is gone', 'After hearing this final teaching, Arjuna tells Krishna that his confusion is destroyed and his memory restored. He picks up his bow, ready to act. The conversation that began with grief ends with clarity.', 'Arjuna standing tall in the chariot with his bow raised, Krishna holding the reins, light breaking over the battlefield.');
insert into verse_stories (verse_id, story_id) values ('gita-18-66', 'gita-18-66-story');
insert into teachings (verse_id, language, title, practice) values ('gita-18-66', 'en', 'Rest in trust', 'Before sleeping tonight, let go of the day''s worries one by one and say: I have done my part.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-18-66', 'What does Krishna tell Arjuna not to do?', array['Fight', 'Grieve', 'Pray', 'Think']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('gita-18-66', 'Where does this verse appear in the Gita?', array['At the very beginning', 'Near the end, in the last chapter', 'In the middle', 'It is not in the Gita']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('rv-3-62-10', 'rig-veda', (select id from sections where scripture_id = 'rig-veda' and level = 1 and number = 3), 10, 'Mandala 3, Hymn 62, Verse 10 (Gayatri Mantra)', 'तत्सवितुर्वरेण्यं भर्गो देवस्य धीमहि।
insert into translations (verse_id, language, text, source_id, is_primary) values ('rv-3-62-10', 'en', 'We meditate on the glorious radiance of the divine Savitr, the source of all light. May it inspire and awaken our minds.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('rv-3-62-10', 'en', 'This is a prayer not for wealth but for a clear, awakened mind. It asks the light that lights the sun to light our thinking too.', 'The Gayatri is named after its metre, gāyatrī, three lines of eight syllables. It is addressed to Savitṛ, the divine power behind the sun that stirs all life into action. The prayer does not ask for health or wealth. It asks that this radiant light, bharga, would inspire our minds, dhī. For thousands of years it has been chanted at dawn and dusk. The opening words om bhūr bhuvaḥ svaḥ, often added before it, come from a separate tradition.', '[{"word":"savitṛ","meaning":"the divine sun, the inspirer"},{"word":"bharga","meaning":"radiance, light"},{"word":"dhī","meaning":"mind, understanding"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('rv-3-62-10-story', 'The seer Vishvamitra', 'This hymn is credited to the seer Vishvamitra, a king who gave up his throne to seek wisdom. Through long discipline he became a great rishi, and the Gayatri he received became one of the most chanted verses in India.', 'A sage standing waist-deep in a river at sunrise, palms joined, facing a golden sun.');
insert into verse_stories (verse_id, story_id) values ('rv-3-62-10', 'rv-3-62-10-story');
insert into teachings (verse_id, language, title, practice) values ('rv-3-62-10', 'en', 'Ask for clarity', 'At sunrise or when you start your day, take a moment to ask for a clear mind rather than a particular result.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('rv-3-62-10', 'What does the Gayatri Mantra ask for?', array['Wealth', 'An awakened, inspired mind', 'Victory', 'Rain']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('rv-3-62-10', 'Which Veda contains this verse?', array['Sama Veda', 'Rig Veda', 'Atharva Veda', 'None']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('rv-1-164-46', 'rig-veda', (select id from sections where scripture_id = 'rig-veda' and level = 1 and number = 1), 46, 'Mandala 1, Hymn 164, Verse 46', 'इन्द्रं मित्रं वरुणमग्निमाहुरथो दिव्यः स सुपर्णो गरुत्मान्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('rv-1-164-46', 'en', 'They call it Indra, Mitra, Varuna, Agni, and the heavenly bird Garutman. Truth is one; the wise call it by many names: Agni, Yama, Matarishvan.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('rv-1-164-46', 'en', 'Different people use different names and paths for the same ultimate truth. This verse is a root of respect for many views.', 'This line is one of the most famous statements of the Rig Veda. It lists many names of gods, including Indra, Mitra, Varuna, Agni, the heavenly bird and Yama, and then says ekaṁ sad viprā bahudhā vadanti: truth is one, the wise speak of it in many ways. It is the root of a long Indian tradition of respecting many paths. People do not have to use the same words to point at the same reality.', '[{"word":"ekam","meaning":"one"},{"word":"sat","meaning":"truth, being, reality"},{"word":"bahudhā","meaning":"in many ways"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('rv-1-164-46-story', 'The riddle hymn of Dirghatamas', 'This verse comes from a long hymn of riddles credited to the seer Dirghatamas, who tradition says was born blind. Though he could not see the world, he saw a deep truth: behind the many gods, there is one reality.', 'An elderly seer with closed eyes, surrounded by faint symbols of fire, wind, sky and water merging into one light.');
insert into verse_stories (verse_id, story_id) values ('rv-1-164-46', 'rv-1-164-46-story');
insert into teachings (verse_id, language, title, practice) values ('rv-1-164-46', 'en', 'Listen for the one', 'When you hear someone describe a belief different from yours today, look for the shared truth beneath the different words.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('rv-1-164-46', '''Ekam sat'' means...', array['Many truths', 'Truth is one', 'No truth', 'Truth is hidden']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('rv-1-164-46', 'How do the wise speak of the one truth?', array['By one name only', 'By many names', 'They never speak of it', 'Only in secret']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('rv-10-129-1', 'rig-veda', (select id from sections where scripture_id = 'rig-veda' and level = 1 and number = 10), 1, 'Mandala 10, Hymn 129, Verse 1 (Nasadiya Sukta)', 'नासदासीन्नो सदासीत्तदानीं नासीद्रजो नो व्योमा परो यत्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('rv-10-129-1', 'en', 'Then there was neither non-existence nor existence. There was no air, nor sky beyond it. What covered it, and where? Who protected it? Was there water, deep and unfathomable?', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('rv-10-129-1', 'en', 'One of the oldest scriptures in the world begins its story of creation with honest questions. Wonder, not certainty, is the starting point.', 'The Nasadiya Sukta, the Hymn of Creation, is one of the most philosophical poems in the Rig Veda. It imagines the state before anything existed, when there was neither being (sat) nor non-being (asat), no air and no sky. It does not give a neat answer. It asks questions, and later verses suggest that even the highest overseer may not know how it all began. Scientists and poets around the world admire it for its honest wonder.', '[{"word":"asat / sat","meaning":"non-being / being"},{"word":"vyoman","meaning":"sky, space"},{"word":"gabhīra","meaning":"deep, profound"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('rv-10-129-1-story', 'The hymn of creation', 'The Nasadiya Sukta asks how everything began. It ends by saying that perhaps even the one who watches over creation from the highest heaven knows, or perhaps does not know. It is an ancient invitation to keep asking.', 'A vast dark cosmos with the first faint swirl of light, a tiny seated figure gazing up in wonder.');
insert into verse_stories (verse_id, story_id) values ('rv-10-129-1', 'rv-10-129-1-story');
insert into teachings (verse_id, language, title, practice) values ('rv-10-129-1', 'en', 'Stay curious', 'Ask one big question today that you do not know the answer to, and enjoy not knowing for a while.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('rv-10-129-1', 'What is the Nasadiya Sukta about?', array['A war', 'The origin of the universe', 'A king''s wedding', 'Farming']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('rv-10-129-1', 'How does this hymn approach creation?', array['With firm answers', 'With deep questions', 'With fear', 'With jokes']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('rv-10-191-2', 'rig-veda', (select id from sections where scripture_id = 'rig-veda' and level = 1 and number = 10), 2, 'Mandala 10, Hymn 191, Verse 2', 'सं गच्छध्वं सं वदध्वं सं वो मनांसि जानताम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('rv-10-191-2', 'en', 'Walk together, speak together, let your minds be in harmony, just as the gods of old sat together in agreement to share their portion.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('rv-10-191-2', 'en', 'Communities thrive when people move, talk and think together. Harmony is something we practise, not just hope for.', 'This is part of the samjñāna sūkta, the hymn of togetherness, which closes the entire Rig Veda. Its verbs all begin with saṁ, meaning together: go together, speak together, let your minds know together. It points to the old gods, who shared their portions in harmony, as an example. The hymn is still recited at gatherings, schools and the start of meetings across India as a call for unity of purpose.', '[{"word":"saṁ gacchadhvam","meaning":"walk together"},{"word":"saṁ vadadhvam","meaning":"speak together"},{"word":"manāṁsi","meaning":"minds"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('rv-10-191-2-story', 'The last hymn of the Rig Veda', 'This is part of the very last hymn of the Rig Veda. After more than a thousand hymns, the collection closes with a call for people to gather, speak and decide together in unity.', 'A circle of villagers of all ages seated around a fire under the stars, talking and listening.');
insert into verse_stories (verse_id, story_id) values ('rv-10-191-2', 'rv-10-191-2-story');
insert into teachings (verse_id, language, title, practice) values ('rv-10-191-2', 'en', 'Listen to agree', 'In one conversation today, listen fully before replying, and look for the point where you agree.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('rv-10-191-2', 'What does this verse ask people to do?', array['Compete', 'Walk and speak together in harmony', 'Stay silent', 'Live alone']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('rv-10-191-2', 'Where in the Rig Veda is this hymn found?', array['At the very beginning', 'At the very end', 'In the middle', 'It is not in the Rig Veda']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('rv-1-89-1', 'rig-veda', (select id from sections where scripture_id = 'rig-veda' and level = 1 and number = 1), 1, 'Mandala 1, Hymn 89, Verse 1', 'आ नो भद्राः क्रतवो यन्तु विश्वतोऽदब्धासो अपरीतास उद्भिदः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('rv-1-89-1', 'en', 'Let noble thoughts come to us from every side, undeceived, unhindered and fresh. May the gods always be with us for our growth, ever watchful, protecting us day after day.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('rv-1-89-1', 'en', 'Keep your mind open. Good ideas can come from anywhere and anyone, and welcoming them is how we grow.', 'The first line, ā no bhadrāḥ kratavo yantu viśvataḥ, is one of the most quoted lines of the Vedas. Bhadra means good or auspicious, and kratu means thought, will or purpose. The prayer asks that good thoughts come to us from every direction, undeceived and unblocked. The rest of the verse asks the gods to protect and help us grow day after day. It is a beautiful motto for an open, lifelong learner.', '[{"word":"bhadra","meaning":"good, auspicious"},{"word":"kratu","meaning":"thought, intention"},{"word":"viśvataḥ","meaning":"from all sides"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('rv-1-89-1-story', 'An open door for wisdom', 'This verse is credited to the seer Gotama Rahugana. Its opening line is often quoted as a motto for learning: let good thoughts come to us from all directions, not just from people we already agree with.', 'A house with all its doors and windows open, beams of light entering from every direction.');
insert into verse_stories (verse_id, story_id) values ('rv-1-89-1', 'rv-1-89-1-story');
insert into teachings (verse_id, language, title, practice) values ('rv-1-89-1', 'en', 'Learn from someone unexpected', 'Learn one good idea today from a person or place you would not usually turn to.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('rv-1-89-1', 'From where should noble thoughts come, according to this verse?', array['Only from teachers', 'From every side', 'Only from books', 'Only from family']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('rv-1-89-1', 'What is the main lesson of this verse?', array['Keep an open mind', 'Avoid new ideas', 'Trust no one', 'Stay at home']::text[], 0);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('rv-7-59-12', 'rig-veda', (select id from sections where scripture_id = 'rig-veda' and level = 1 and number = 7), 12, 'Mandala 7, Hymn 59, Verse 12 (Mahamrityunjaya Mantra)', 'त्र्यम्बकं यजामहे सुगन्धिं पुष्टिवर्धनम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('rv-7-59-12', 'en', 'We worship the three-eyed one, fragrant, who nourishes all life. As a ripe cucumber is freed from its vine, may we be freed from death, and not from immortality.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('rv-7-59-12', 'en', 'When the time comes, may we let go as naturally as ripe fruit falls from the vine, free and complete, not torn away.', 'Known as the Mahamrityunjaya, the great death-conquering mantra, this verse is addressed to Tryambaka, the three-eyed one, identified with Shiva. The image at its heart is gentle: a ripe cucumber (urvāruka) separates from its vine on its own, without force. The prayer asks to be released from death in the same natural way, and not from amṛta, immortality. It is chanted for healing, protection and peace, especially in times of illness.', '[{"word":"tryambaka","meaning":"the three-eyed one, Shiva"},{"word":"urvāruka","meaning":"cucumber or melon"},{"word":"amṛta","meaning":"immortality, nectar"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('rv-7-59-12-story', 'Markandeya and Yama', 'In the Puranas, the boy Markandeya was destined to die at sixteen. When Yama came for him, he clung to a Shiva linga and chanted this mantra. Shiva appeared, stopped Yama, and blessed the boy with endless life.', 'A boy embracing a stone linga in a temple while a radiant figure of Shiva rises from it to face a startled Yama.');
insert into verse_stories (verse_id, story_id) values ('rv-7-59-12', 'rv-7-59-12-story');
insert into teachings (verse_id, language, title, practice) values ('rv-7-59-12', 'en', 'Ripen, then release', 'Think of something you are ready to let go of. Instead of tearing it away, let it fall away gently today.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('rv-7-59-12', 'What image does this mantra use for liberation?', array['A bird leaving its nest', 'A ripe cucumber freed from its vine', 'A river reaching the sea', 'A lamp going out']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('rv-7-59-12', 'In the story, who saved Markandeya?', array['Vishnu', 'Shiva', 'Indra', 'Brahma']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('av-12-1-12', 'atharva-veda', (select id from sections where scripture_id = 'atharva-veda' and level = 1 and number = 12), 12, 'Book 12, Hymn 1, Verse 12 (Bhumi Sukta, excerpt)', 'माता भूमिः पुत्रो अहं पृथिव्याः।', 'mātā bhūmiḥ putro ahaṁ pṛthivyāḥ', 12001012, true, 'public-domain-sanskrit', 'published');
insert into translations (verse_id, language, text, source_id, is_primary) values ('av-12-1-12', 'en', 'The Earth is my mother, and I am her child.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('av-12-1-12', 'en', 'We belong to the Earth; it does not belong to us. Caring for nature is caring for family.', 'The Bhumi Sukta in the Atharva Veda is a long hymn to the Earth, Prithvi. This short line from it, the Earth is my mother and I am her child, sums up its spirit. The hymn praises her hills, rivers and forests and the many peoples with different languages who live on her. It even asks that whatever we dig from her grow back quickly. Today many see it as one of the world''s earliest environmental poems.', '[{"word":"mātā","meaning":"mother"},{"word":"bhūmi / pṛthivī","meaning":"the Earth"},{"word":"putra","meaning":"child, son"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('av-12-1-12-story', 'The hymn to Mother Earth', 'The Bhumi Sukta is a long hymn of over sixty verses praising the Earth for her mountains, rivers, forests and the many peoples who live on her. It asks her forgiveness for the harm we do when we dig into her.', 'A child resting in the lap of a vast green landscape shaped like a mother, rivers flowing through her hair.');
insert into verse_stories (verse_id, story_id) values ('av-12-1-12', 'av-12-1-12-story');
insert into teachings (verse_id, language, title, practice) values ('av-12-1-12', 'en', 'Care for your mother', 'Do one thing for the Earth today: plant something, pick up litter, or use less plastic.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('av-12-1-12', 'How does this verse describe the Earth?', array['As a servant', 'As a mother', 'As an enemy', 'As a possession']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('av-12-1-12', 'Which Veda contains the Bhumi Sukta?', array['Rig Veda', 'Atharva Veda', 'Yajur Veda', 'Sama Veda']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('isha-1', 'isha-upanishad', null, 1, 'Verse 1', 'ईशा वास्यमिदं सर्वं यत्किञ्च जगत्यां जगत्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('isha-1', 'en', 'All this, whatever moves in this moving world, is pervaded by the Lord. Enjoy it through renunciation. Do not covet anyone''s wealth.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('isha-1', 'en', 'Everything is sacred and nothing is truly ours. Enjoy life by holding it lightly, without greed.', 'The Isha Upanishad opens with a vision: everything that moves in this moving world is clothed in, or dwelt in by, the Lord (īśā). Since all is the divine''s, the verse advises tena tyaktena bhuñjīthāḥ, enjoy through letting go. It ends with mā gṛdhaḥ, do not covet. Mahatma Gandhi admired this verse deeply. It teaches that contentment comes not from owning more but from holding everything lightly and with reverence.', '[{"word":"īśā","meaning":"by the Lord"},{"word":"tyakta","meaning":"given up, let go"},{"word":"mā gṛdhaḥ","meaning":"do not covet"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('isha-1-story', 'The Upanishad inside a Veda', 'The Isha Upanishad is unusual: it is the final chapter of the Shukla Yajur Veda itself. In just eighteen verses, it brings the Vedic rituals to their inner meaning, beginning with this verse.', 'A person holding a flower in an open palm, light passing through everything around them.');
insert into verse_stories (verse_id, story_id) values ('isha-1', 'isha-1-story');
insert into teachings (verse_id, language, title, practice) values ('isha-1', 'en', 'Hold it lightly', 'Enjoy one thing you own today with gratitude, while remembering it is on loan to you.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('isha-1', 'According to this verse, the world is...', array['Meaningless', 'Pervaded by the divine', 'Owned by kings', 'An illusion to escape']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('isha-1', 'How should we enjoy the world?', array['Through greed', 'Through renunciation, holding it lightly', 'By taking what others have', 'We should not enjoy it']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('brihadaranyaka-1-3-28', 'brihadaranyaka-upanishad', (select id from sections where scripture_id = 'brihadaranyaka-upanishad' and level = 1 and number = 1), 28, 'Chapter 1, Section 3, Verse 28', 'असतो मा सद्गमय।
insert into translations (verse_id, language, text, source_id, is_primary) values ('brihadaranyaka-1-3-28', 'en', 'Lead me from the unreal to the real. Lead me from darkness to light. Lead me from death to immortality.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('brihadaranyaka-1-3-28', 'en', 'Three short lines that sum up the whole spiritual journey: toward truth, toward understanding, toward what never dies.', 'These three lines are called the pavamāna mantras. Each line is a step: from asat (the unreal) to sat (the real), from tamas (darkness) to jyotis (light), and from mṛtyu (death) to amṛta (immortality). The Upanishad itself explains that all three mean the same thing: lead me from the passing to the lasting. Short enough for a child to learn, they hold the whole aim of the spiritual journey.', '[{"word":"asat / sat","meaning":"unreal / real"},{"word":"tamas / jyotis","meaning":"darkness / light"},{"word":"gamaya","meaning":"lead, cause to go"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('brihadaranyaka-1-3-28-story', 'A prayer for every journey', 'These lines come from one of the oldest Upanishads, where they are chanted as part of a Vedic ritual. Today they are sung in schools, homes and temples across India as a prayer for growth.', 'A path leading from a dark forest toward a glowing dawn horizon, a single lamp-bearer walking along it.');
insert into verse_stories (verse_id, story_id) values ('brihadaranyaka-1-3-28', 'brihadaranyaka-1-3-28-story');
insert into teachings (verse_id, language, title, practice) values ('brihadaranyaka-1-3-28', 'en', 'One step toward light', 'Replace one thing today that keeps you in ''darkness'', a rumour, a doom-scroll, a grudge, with something that brings light.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('brihadaranyaka-1-3-28', '''Tamaso ma jyotir gamaya'' means...', array['Lead me from darkness to light', 'Lead me to wealth', 'Lead me home', 'Lead me to victory']::text[], 0);
insert into quiz_questions (verse_id, question, options, answer_index) values ('brihadaranyaka-1-3-28', 'How many requests are in this prayer?', array['One', 'Two', 'Three', 'Ten']::text[], 2);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, sort_key, is_featured, source_id, status) values ('taittiriya-shanti', 'taittiriya-upanishad', null, 0, 'Invocation (Shanti Mantra)', 'ॐ सह नाववतु। सह नौ भुनक्तु।
insert into translations (verse_id, language, text, source_id, is_primary) values ('taittiriya-shanti', 'en', 'May we both be protected together. May we both be nourished together. May we work together with energy. May our study be full of light, and may we never resent each other.', 'veda-app-original', true);
insert into explanations (verse_id, language, meaning, explanation, keywords, source_id, status) values ('taittiriya-shanti', 'en', 'Learning is a partnership. Teacher and student grow together when they share effort and respect.', 'A śānti mantra, or peace invocation, is recited before studying the Upanishads. This one is spoken by teacher and student together, which is why it uses the dual form nau, the two of us. It asks for protection, nourishment, shared energy and bright learning. The last line, mā vidviṣāvahai, asks that the two never resent each other. It closes with om śāntiḥ śāntiḥ śāntiḥ, peace three times.', '[{"word":"saha","meaning":"together"},{"word":"tejasvi","meaning":"radiant, full of light"},{"word":"mā vidviṣāvahai","meaning":"may we not resent each other"}]'::jsonb, 'veda-app-original', 'published');
insert into stories (id, title, text, illustration_idea) values ('taittiriya-shanti-story', 'The gurukul prayer', 'In the ancient gurukuls, forest schools, teacher and students chanted this prayer together before lessons. It asks for success not for the student alone but for both of them, and for harmony between them.', 'A teacher and a few students seated under a tree in a forest school, hands joined, morning light filtering through leaves.');
insert into verse_stories (verse_id, story_id) values ('taittiriya-shanti', 'taittiriya-shanti-story');
insert into teachings (verse_id, language, title, practice) values ('taittiriya-shanti', 'en', 'Learn together', 'Teach someone one thing you know today, and ask them to teach you one thing back.');
insert into quiz_questions (verse_id, question, options, answer_index) values ('taittiriya-shanti', 'Who chants this prayer together?', array['King and soldier', 'Teacher and student', 'Husband and wife', 'Priest and god']::text[], 1);
insert into quiz_questions (verse_id, question, options, answer_index) values ('taittiriya-shanti', 'What does the last line ask for?', array['Wealth', 'That we never resent each other', 'Victory over enemies', 'Long life']::text[], 1);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-1', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 1, 'Chapter 1, Verse 1', 'धर्मक्षेत्रे कुरुक्षेत्रे समवेता युयुत्सवः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-1', 'en', 'On the holy plain, on the field of Kuru, gathered together, eager for battle, what did they, O Sanjaya, my people and the Pândavas?', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-2', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 2, 'Chapter 1, Verse 2', 'दृष्ट्वा तु पाण्डवानीकं व्यूढं दुर्योधनस्तदा।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-2', 'en', 'Having seen arrayed the army of the Pândavas, the Prince Duryodhana approached his teacher, and spake these words:', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-3', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 3, 'Chapter 1, Verse 3', 'पश्यैतां पाण्डुपुत्राणामाचार्य महतीं चमूम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-3', 'en', '"Behold this mighty host of the sons of Pându, O teacher, arrayed by the son of Drupada, thy wise disciple.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-4', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 4, 'Chapter 1, Verse 4', 'अत्र शूरा महेष्वासा भीमार्जुनसमा युधि।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-4', 'en', 'Heroes are these, mighty bowmen, to Bhîma and Arjuna equal in battle: Yuyudhâna, Virâta, and Drupada of the great car.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-5', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 5, 'Chapter 1, Verse 5', 'धृष्टकेतुश्चेकितानः काशिराजश्च वीर्यवान्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-5', 'en', 'Drishtaketu, Chekitâna and the valiant King of Kâshi, Purujit and Kuntibhoja, and Shaivya, bull among men;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-6', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 6, 'Chapter 1, Verse 6', 'युधामन्युश्च विक्रान्त उत्तमौजाश्च वीर्यवान्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-6', 'en', 'Yudhâmanyu the strong, and Uttamaujas the brave; Saubhadra and the Draupadeyas, all of great cars.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-7', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 7, 'Chapter 1, Verse 7', 'अस्माकं तु विशिष्टा ये तान्निबोध द्विजोत्तम।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-7', 'en', 'Know further all those who are our chiefs, O best of the twice-born, the leaders of my army; these I name to thee for thy information:', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-8', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 8, 'Chapter 1, Verse 8', 'भवान्भीष्मश्च कर्णश्च कृपश्च समितिंजयः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-8', 'en', 'Thou, Lord, and Bhîshma, and Karna and Kripa, conquering in battle; Ashvatthâmâ, Vikarna, and Saumadatti also;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-9', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 9, 'Chapter 1, Verse 9', 'अन्ये च बहवः शूरा मदर्थे त्यक्तजीविताः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-9', 'en', 'And many others, heroes, for my sake renouncing their lives, with diverse weapons and missiles, and all well-skilled in war.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-10', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 10, 'Chapter 1, Verse 10', 'अपर्याप्तं तदस्माकं बलं भीष्माभिरक्षितम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-10', 'en', 'Yet insufficient seems this army of ours, though marshalled by Bhîshma, while that army of theirs seems sufficient, though marshalled by Bhîma;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-11', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 11, 'Chapter 1, Verse 11', 'अयनेषु च सर्वेषु यथाभागमवस्थिताः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-11', 'en', 'Therefore in the rank and file let all, standing firmly in their respective divisions, guard Bhîshma, even all ye generals.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-12', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 12, 'Chapter 1, Verse 12', 'तस्य संजनयन्हर्षं कुरुवृद्धः पितामहः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-12', 'en', 'To enhearten him, the Ancient of the Kurus, the Grandsire, the glorious, blew his conch, sounding on high a lion''s roar.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-13', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 13, 'Chapter 1, Verse 13', 'ततः शङ्खाश्च भेर्यश्च पणवानकगोमुखाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-13', 'en', 'Then conches and kettledrums, tabors and drums and cowhorns, suddenly blared forth, and the sound was tumultuous.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-14', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 14, 'Chapter 1, Verse 14', 'ततः श्वेतैर्हयैर्युक्ते महति स्यन्दने स्थितौ।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-14', 'en', 'Then, stationed in their great war-chariot, yoked to white horses, Mâdhava and the son of Pându blew their divine conches.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-15', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 15, 'Chapter 1, Verse 15', 'पाञ्चजन्यं हृषीकेशो देवदत्तं धनंजयः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-15', 'en', 'Pânchajanya by Hrishîkesha, and Devadatta by Dhananjaya. Vrikodara of terrible deeds blew his mighty conch, Paundra;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-16', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 16, 'Chapter 1, Verse 16', 'अनन्तविजयं राजा कुन्तीपुत्रो युधिष्ठिरः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-16', 'en', 'The King Yudhishthira, the son of Kuntî, blew Anantavijaya; Nakula and Sahadeva, Sughosha and Manipushpaka.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-17', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 17, 'Chapter 1, Verse 17', 'काश्यश्च परमेष्वासः शिखण्डी च महारथः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-17', 'en', 'And Kâshya, of the great bow and Shikhandî, the mighty car-warrior, Dhrishtadyumna and Virâta and Sâtyaki, the unconquered.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-18', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 18, 'Chapter 1, Verse 18', 'द्रुपदो द्रौपदेयाश्च सर्वशः पृथिवीपते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-18', 'en', 'Drupada and the Draupadeyas, O Lord of earth, and Saubhadra, the mighty-armed, on all sides their several conches blew.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-19', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 19, 'Chapter 1, Verse 19', 'स घोषो धार्तराष्ट्राणां हृदयानि व्यदारयत्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-19', 'en', 'That tumultuous uproar rent the hearts of the sons of Dhritarâshtra, filling the earth and sky with sound.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-20', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 20, 'Chapter 1, Verse 20', 'अथ व्यवस्थितान्दृष्ट्वा धार्तराष्ट्रान्कपिध्वजः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-20', 'en', 'Then, beholding the sons of Dhritarâshtra standing arrayed, and flight of missiles about to begin, he whose crest is an ape, the son of Pându, took up his bow,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-21', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 21, 'Chapter 1, Verse 21', 'हृषीकेशं तदा वाक्यमिदमाह महीपते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-21', 'en', 'And spake this word to Hrishîkesha, O Lord of Earth: In the midst, between the two armies, stay my chariot, O Achyuta,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-22', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 22, 'Chapter 1, Verse 22', 'यावदेतान्निरीक्षेऽहं योद्धुकामानवस्थितान्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-22', 'en', 'That I may behold these standing, longing for battle, with whom I must strive in this outbreaking war,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-23', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 23, 'Chapter 1, Verse 23', 'योत्स्यमानानवेक्षेऽहं य एतेऽत्र समागताः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-23', 'en', 'And gaze on those here gathered together ready to fight, desirous of pleasing in battle the evil-minded son of Dhritarâshtra.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-24', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 24, 'Chapter 1, Verse 24', 'एवमुक्तो हृषीकेशो गुडाकेशेन भारत।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-24', 'en', 'Thus addressed by Gudâkesha, Hrishîkesha, O Bhârata, having stayed that best of chariots in the midst, between the two armies,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-25', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 25, 'Chapter 1, Verse 25', 'भीष्मद्रोणप्रमुखतः सर्वेषां च महीक्षिताम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-25', 'en', 'Over against Bhîshma, Drona and all the rulers of the world, said: "O Pârtha, behold these Kurus gathered together."', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-26', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 26, 'Chapter 1, Verse 26', 'तत्रापश्यत्स्थितान्पार्थः पितॄनथ पितामहान्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-26', 'en', 'Then saw Pârtha standing there, uncles and grandfathers, teachers, mother''s brothers, cousins, sons and grandsons, comrades,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-27', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 27, 'Chapter 1, Verse 27', 'श्वशुरान्सुहृदश्चैव सेनयोरुभयोरपि।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-27', 'en', 'Fathers-in-law and benefactors also in both armies; seeing all these kinsmen thus standing arrayed, Kaunteya,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-28', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 28, 'Chapter 1, Verse 28', 'कृपया परयाविष्टो विषीदन्निदमब्रवीत्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-28', 'en', 'Deeply moved to pity, thus uttered in sadness: Seeing these my kinsmen, O Krishna, arrayed, eager to fight,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-29', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 29, 'Chapter 1, Verse 29', 'सीदन्ति मम गात्राणि मुखं च परिशुष्यति।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-29', 'en', 'My limbs fail and my mouth is parched, my body quivers, and my hair stands on end,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-30', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 30, 'Chapter 1, Verse 30', 'गाण्डीवं स्रंसते हस्तात्त्वक्चैव परिदह्यते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-30', 'en', 'Gândîva slips from my hand, and my skin burns all over, I am not able to stand, my mind is whirling,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-31', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 31, 'Chapter 1, Verse 31', 'निमित्तानि च पश्यामि विपरीतानि केशव।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-31', 'en', 'And I see adverse omens, O Keshava. Nor do I foresee any advantage from slaying kinsmen in battle.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-32', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 32, 'Chapter 1, Verse 32', 'न काङ्क्षे विजयं कृष्ण न च राज्यं सुखानि च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-32', 'en', 'For I desire not victory, O Krishna, nor kingdom, nor pleasures; what is kingdom to us, O Govinda, what enjoyment or even life?', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-33', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 33, 'Chapter 1, Verse 33', 'येषामर्थे काङ्क्षितं नो राज्यं भोगाः सुखानि च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-33', 'en', 'Those for whose sake we desire kingdom, enjoyments and pleasures, they stand here in battle, abandoning life and riches—', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-34', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 34, 'Chapter 1, Verse 34', 'आचार्याः पितरः पुत्रास्तथैव च पितामहाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-34', 'en', 'Teachers, fathers, sons, as well as grandfathers, mother''s brothers, fathers-in-law, grandsons, brothers-in-law, and other relatives.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-35', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 35, 'Chapter 1, Verse 35', 'एतान्न हन्तुमिच्छामि घ्नतोऽपि मधुसूदन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-35', 'en', 'These I do not wish to kill, though myself slain, O Madhusûdana, even for the sake of the kingship of the three worlds; how then for earth?', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-36', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 36, 'Chapter 1, Verse 36', 'निहत्य धार्तराष्ट्रान्नः का प्रीतिः स्याज्जनार्दन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-36', 'en', 'Slaying these sons of Dhritarâshtra, what pleasure can be ours, O Janârdana? Killing these desperadoes, sin will but take hold of us.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-37', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 37, 'Chapter 1, Verse 37', 'तस्मान्नार्हा वयं हन्तुं धार्तराष्ट्रान्सबान्धवान्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-37', 'en', 'Therefore we should not kill the sons of Dhritarâshtra, our relatives; for how, killing our kinsmen, may we be happy, O Mâdhava?', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-38', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 38, 'Chapter 1, Verse 38', 'यद्यप्येते न पश्यन्ति लोभोपहतचेतसः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-38', 'en', 'Although these, with intelligence overpowered by greed, see no guilt in the destruction of a family, no crime in hostility to friends,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-39', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 39, 'Chapter 1, Verse 39', 'कथं न ज्ञेयमस्माभिः पापादस्मान्निवर्तितुम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-39', 'en', 'Why should not we learn to turn away from such a sin, O Janârdana, who see the evils in the destruction of a family?', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-40', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 40, 'Chapter 1, Verse 40', 'कुलक्षये प्रणश्यन्ति कुलधर्माः सनातनाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-40', 'en', 'In the destruction of a family the immemorial family traditions perish; in the perishing of tradition, lawlessness overcomes the whole family;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-41', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 41, 'Chapter 1, Verse 41', 'अधर्माभिभवात्कृष्ण प्रदुष्यन्ति कुलस्त्रियः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-41', 'en', 'Owing to predominance of lawlessness, O Krishna, the women of the family become corrupt; women corrupted, O Vârshneya, there ariseth caste confusion;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-42', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 42, 'Chapter 1, Verse 42', 'संकरो नरकायैव कुलघ्नानां कुलस्य च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-42', 'en', 'This confusion draggeth to hell the slayers of the family, and the family; for their ancestors fall, deprived of rice-balls and libations.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-43', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 43, 'Chapter 1, Verse 43', 'दोषैरेतैः कुलघ्नानां वर्णसंकरकारकैः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-43', 'en', 'By these caste-confusing misdeeds of the slayers of the family, the everlasting caste customs and family customs are abolished.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-44', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 44, 'Chapter 1, Verse 44', 'उत्सन्नकुलधर्माणां मनुष्याणां जनार्दन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-44', 'en', 'The abode of the men whose family customs are extinguished, O Janârdana, is everlastingly in hell. Thus have we heard.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-45', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 45, 'Chapter 1, Verse 45', 'अहो बत महत्पापं कर्तुं व्यवसिता वयम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-45', 'en', 'Alas! in committing a great sin are we engaged, we who are endeavouring to kill our kindred from greed of the pleasures of kingship.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-46', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 46, 'Chapter 1, Verse 46', 'यदि मामप्रतीकारमशस्त्रं शस्त्रपाणयः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-46', 'en', 'If the sons of Dhritarâshtra, weapon in hand, should slay me, unresisting, unarmed, in the battle, that would for me be the better.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-1-47', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 1), 47, 'Chapter 1, Verse 47', 'एवमुक्त्वार्जुनः संख्ये रथोपस्थ उपाविशत्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-1-47', 'en', 'Having thus spoken on the battle-field, Arjuna sank down on the seat of the chariot, casting away his bow and arrow, his mind overborne by grief.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-1', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 1, 'Chapter 2, Verse 1', 'तं तथा कृपयाविष्टमश्रुपूर्णाकुलेक्षणम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-1', 'en', 'To him thus with pity overcome, with smarting brimming eyes, despondent, Madhusûdana spake these words:', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-2', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 2, 'Chapter 2, Verse 2', 'कुतस्त्वा कश्मलमिदं विषमे समुपस्थितम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-2', 'en', 'Whence hath this dejection befallen thee in this perilous strait, ignoble, heaven-closing, infamous, O Arjuna?', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-3', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 3, 'Chapter 2, Verse 3', 'क्लैब्यं मा स्म गमः पार्थ नैतत्त्वय्युपपद्यते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-3', 'en', 'Yield not to impotence, O Partha! it doth not befit thee. Shake off this paltry faint-heartedness! Stand up, Parantapa!', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-4', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 4, 'Chapter 2, Verse 4', 'कथं भीष्ममहं संख्ये द्रोणं च मधुसूदन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-4', 'en', 'How, O Madhusûdana, shall I attack Bhîshma and Drona with arrows in battle, they who are worthy of reverence, O slayer of foes?', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-5', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 5, 'Chapter 2, Verse 5', 'गुरूनहत्वा हि महानुभावाञ्श्रेयो भोक्तुं भैक्षमपीह लोके।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-5', 'en', 'Better in this world to eat even the beggar''s crust than to slay these most noble Gurus. Slaying these Gurus, our well-wishers, I should taste of blood-besprinkled feasts.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-6', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 6, 'Chapter 2, Verse 6', 'न चैतद्विद्मः कतरन्नो गरीयो यद्वा जयेम यदि वा नो जयेयुः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-6', 'en', 'Nor know I which for us be the better, that we conquer them or they conquer us—these, whom having slain we should not care to live, even these arrayed against us, the sons of Dhritarâshtra.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-7', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 7, 'Chapter 2, Verse 7', 'कार्पण्यदोषोपहतस्वभावः पृच्छामि त्वां धर्मसंमूढचेताः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-7', 'en', 'My heart is weighed down with the vice of faintness; my mind is confused as to duty. I ask thee which may be the better—that tell me decisively. I am thy disciple, suppliant to Thee; teach me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-8', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 8, 'Chapter 2, Verse 8', 'न हि प्रपश्यामि ममापनुद्याद्यच्छोकमुच्छोषणमिन्द्रियाणाम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-8', 'en', 'For I see not that it would drive away this anguish that withers up my senses, if I should attain unrivalled monarchy on earth, or even the sovereignty of the Shining Ones.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-9', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 9, 'Chapter 2, Verse 9', 'एवमुक्त्वा हृषीकेशं गुडाकेशः परंतप।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-9', 'en', 'Gudâkesha, conqueror of his foes, having thus addressed Hrishîkesha and said to Govinda, "I will not fight!", became silent.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-10', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 10, 'Chapter 2, Verse 10', 'तमुवाच हृषीकेशः प्रहसन्निव भारत।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-10', 'en', 'Then Hrishîkesha, smiling, as it were, O Bhârata, spake these words to him, despondent, in the midst of the two armies:', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-11', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 11, 'Chapter 2, Verse 11', 'अशोच्यानन्वशोचस्त्वं प्रज्ञावादांश्च भाषसे।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-11', 'en', 'Thou grievest for those that should not be griev- ed for, yet speakest words of wisdom. The wise grieve neither for the living nor for the dead.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-12', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 12, 'Chapter 2, Verse 12', 'न त्वेवाहं जातु नासं न त्वं नेमे जनाधिपाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-12', 'en', 'Nor at any time verily was I not, nor thou, nor these princes of men, nor verily shall we ever cease to be, hereafter.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-13', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 13, 'Chapter 2, Verse 13', 'देहिनोऽस्मिन्यथा देहे कौमारं यौवनं जरा।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-13', 'en', 'As the dweller in the body experienceth in the body childhood, youth, old age, so passeth he on to another body; the steadfast one grieveth not thereat.', 'besant-1922', true);
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-14', 'en', 'The contacts of matter, O son of Kuntî, giving cold and heat, pleasure and pain, they come and go, impermanent; endure them bravely, O Bhârata.', 'besant-1922', false);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-15', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 15, 'Chapter 2, Verse 15', 'यं हि न व्यथयन्त्येते पुरुषं पुरुषर्षभ।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-15', 'en', 'The man whom these torment not, O chief of men, balanced in pain and pleasure, steadfast, he is fitted for immortality.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-16', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 16, 'Chapter 2, Verse 16', 'नासतो विद्यते भावो नाभावो विद्यते सतः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-16', 'en', 'The unreal hath no being; the real never ceaseth to be; the truth about both hath been perceived by the seers of the essence of things.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-17', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 17, 'Chapter 2, Verse 17', 'अविनाशि तु तद्विद्धि येन सर्वमिदं ततम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-17', 'en', 'Know That to be indestructible by whom all this is pervaded. Nor can any work the destruction of that imperishable One.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-18', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 18, 'Chapter 2, Verse 18', 'अन्तवन्त इमे देहा नित्यस्योक्ताः शरीरिणः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-18', 'en', 'These bodies of the embodied One, who is eternal, indestructible and immeasurable, are known as finite. Therefore fight, O Bhârata.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-19', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 19, 'Chapter 2, Verse 19', 'य एनं वेत्ति हन्तारं यश्चैनं मन्यते हतम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-19', 'en', 'He who regardeth this as a slayer, and he who thinketh he is slain, both of them are ignorant. He slayeth not, nor is he slain.', 'besant-1922', true);
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-20', 'en', 'He is not born, nor doth he die; nor having been, ceaseth he any more to be; unborn, perpetual, eternal and ancient, he is not slain when the body is slaughtered.', 'besant-1922', false);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-21', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 21, 'Chapter 2, Verse 21', 'वेदाविनाशिनं नित्यं य एनमजमव्ययम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-21', 'en', 'Who knoweth him indestructible, perpetual, unborn, undiminishing, how can that man slay, O Pârtha, or cause to be slain?', 'besant-1922', true);
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-22', 'en', 'As a man, casting off worn-out garments, taketh new ones, so the dweller in the body, casting off worn-out bodies, entereth into others that are new.', 'besant-1922', false);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-23', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 23, 'Chapter 2, Verse 23', 'नैनं छिन्दन्ति शस्त्राणि नैनं दहति पावकः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-23', 'en', 'Weapons cleave him not, nor fire burneth him, nor waters wet him, nor wind drieth him away.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-24', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 24, 'Chapter 2, Verse 24', 'अच्छेद्योऽयमदाह्योऽयमक्लेद्योऽशोष्य एव च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-24', 'en', 'Uncleavable he, incombustible he, and indeed neither to be wetted nor dried away; perpetual, all-pervasive, stable, immovable, ancient.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-25', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 25, 'Chapter 2, Verse 25', 'अव्यक्तोऽयमचिन्त्योऽयमविकार्योऽयमुच्यते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-25', 'en', 'Unmanifest, unthinkable, immutable, he is called; therefore knowing him as such, thou shouldst not grieve.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-26', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 26, 'Chapter 2, Verse 26', 'अथ चैनं नित्यजातं नित्यं वा मन्यसे मृतम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-26', 'en', 'Or if thou thinkest of him as being constantly born and constantly dying, even then, O mighty-armed, thou shouldst not grieve.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-27', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 27, 'Chapter 2, Verse 27', 'जातस्य हि ध्रुवो मृत्युर्ध्रुवं जन्म मृतस्य च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-27', 'en', 'For certain is death for the born, and certain is birth for the dead; therefore over the inevitable thou shouldst not grieve.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-28', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 28, 'Chapter 2, Verse 28', 'अव्यक्तादीनि भूतानि व्यक्तमध्यानि भारत।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-28', 'en', 'Beings are unmanifest in their origin, manifest in their midmost state, O Bhârata, unmanifest likewise are they in dissolution. What room then for lamentation?', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-29', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 29, 'Chapter 2, Verse 29', 'आश्चर्यवत्पश्यति कश्चिदेनमाश्चर्यवद्वदति तथैव चान्यः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-29', 'en', 'As marvellous one regardeth him; as marvellous another speaketh thereof; as marvellous another heareth thereof; yet having heard none indeed understandeth.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-30', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 30, 'Chapter 2, Verse 30', 'देही नित्यमवध्योऽयं देहे सर्वस्य भारत।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-30', 'en', 'This dweller in the body of everyone is ever invulnerable, O Bhârata; therefore thou shouldst not grieve for any creature.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-31', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 31, 'Chapter 2, Verse 31', 'स्वधर्ममपि चावेक्ष्य न विकम्पितुमर्हसि।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-31', 'en', 'Further, looking to thine own duty thou shouldst not tremble; for there is nothing more welcome to a Kshattriya than righteous war.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-32', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 32, 'Chapter 2, Verse 32', 'यदृच्छया चोपपन्नं स्वर्गद्वारमपावृतम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-32', 'en', 'Happy the Kshattriyas, O Pârtha, who obtain such a fight, offered unsought as an open door to heaven.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-33', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 33, 'Chapter 2, Verse 33', 'अथ चेत्त्वमिमं धर्म्यं संग्रामं न करिष्यसि।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-33', 'en', 'But if thou wilt not carry on this righteous warfare, then casting away thine own duty and thine honour, thou wilt incur sin.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-34', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 34, 'Chapter 2, Verse 34', 'अकीर्तिं चापि भूतानि कथयिष्यन्ति तेऽव्ययाम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-34', 'en', 'Men will recount thy perpetual dishonour, and, to one highly esteemed, dishonour exceedeth death.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-35', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 35, 'Chapter 2, Verse 35', 'भयाद्रणादुपरतं मंस्यन्ते त्वां महारथाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-35', 'en', 'The great car-warriors will think thee fled from the battle from fear, and thou, that wast highly thought of by them, wilt be lightly held.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-36', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 36, 'Chapter 2, Verse 36', 'अवाच्यवादांश्च बहून्वदिष्यन्ति तवाहिताः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-36', 'en', 'Many unseemly words will be spoken by thine enemies, slandering thy strength; what more painful than that?', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-37', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 37, 'Chapter 2, Verse 37', 'हतो वा प्राप्स्यसि स्वर्गं जित्वा वा भोक्ष्यसे महीम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-37', 'en', 'Slain, thou wilt obtain heaven; victorious, thou wilt enjoy the earth; therefore stand up, O son of Kuntî, resolute to fight.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-38', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 38, 'Chapter 2, Verse 38', 'सुखदुःखे समे कृत्वा लाभालाभौ जयाजयौ।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-38', 'en', 'Taking as equal pleasure and pain, gain and loss, victory and defeat, gird thee for the battle; thus thou shalt not incur sin.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-39', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 39, 'Chapter 2, Verse 39', 'एषा तेऽभिहिता सांख्ये बुद्धिर्योगे त्विमां शृणु।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-39', 'en', 'This teaching set forth to thee is in accordance with the Sâñkhya; hear it now according to the Yoga, imbued with which teaching, O Pârtha, thou shalt cast away the bonds of action.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-40', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 40, 'Chapter 2, Verse 40', 'नेहाभिक्रमनाशोऽस्ति प्रत्यवायो न विद्यते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-40', 'en', 'In this there is no loss of effort, nor is there transgression. Even a little of this knowledge protects from great fear.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-41', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 41, 'Chapter 2, Verse 41', 'व्यवसायात्मिका बुद्धिरेकेह कुरुनन्दन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-41', 'en', 'The determinate Reason is but one-pointed, O joy of the Kurus; many-branched and endless are the thoughts of the irresolute.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-42', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 42, 'Chapter 2, Verse 42', 'यामिमां पुष्पितां वाचं प्रवदन्त्यविपश्चितः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-42', 'en', 'Flowery speech is uttered by the foolish, rejoicing in the letter of the Vedas, O Pârtha, saying: "There is naught but this";', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-43', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 43, 'Chapter 2, Verse 43', 'कामात्मानः स्वर्गपरा जन्मकर्मफलप्रदाम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-43', 'en', 'With desire for self, with heaven for goal, they offer birth as the fruit of action, and prescribe many and various ceremonies for the attainment of pleasure and lordship.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-44', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 44, 'Chapter 2, Verse 44', 'भोगैश्वर्यप्रसक्तानां तयापहृतचेतसाम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-44', 'en', 'For them who cling to pleasure and lordship, whose minds are captivated by such teaching, is not designed this determinate Reason, on contemplation steadily bent.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-45', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 45, 'Chapter 2, Verse 45', 'त्रैगुण्यविषया वेदा निस्त्रैगुण्यो भवार्जुन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-45', 'en', 'The Vedas deal with the three attributes; be thou above these three attributes, O Arjuna; beyond the pairs of opposites, ever steadfast in purity, careless of possessions, full of the Self.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-46', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 46, 'Chapter 2, Verse 46', 'यावानर्थ उदपाने सर्वतः संप्लुतोदके।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-46', 'en', 'All the Vedas are as useful to an enlightened Brâhmana as is a tank in a place covered all over with water.', 'besant-1922', true);
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-47', 'en', 'Thy business is with the action only, never with its fruits; so let not the fruit of action be thy motive, nor be thou to inaction attached.', 'besant-1922', false);
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-48', 'en', 'Perform action, O Dhananjaya, dwelling in union with the divine, renouncing attachments and balanced evenly in success and failure: equilibrium is called yoga.', 'besant-1922', false);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-49', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 49, 'Chapter 2, Verse 49', 'दूरेण ह्यवरं कर्म बुद्धियोगाद्धनंजय।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-49', 'en', 'Far lower than the Yoga of Discrimination is action, O Dhananjaya. Take thou refuge in the Pure Reason; pitiable are they who work for fruit.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-50', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 50, 'Chapter 2, Verse 50', 'बुद्धियुक्तो जहातीह उभे सुकृतदुष्कृते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-50', 'en', 'United to the Pure Reason one abandoneth here both good and evil deeds; therefore cleave thou to yoga; yoga is skill in action.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-51', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 51, 'Chapter 2, Verse 51', 'कर्मजं बुद्धियुक्ता हि फलं त्यक्त्वा मनीषिणः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-51', 'en', 'The Sages, united to the Pure Reason, renounce the fruit which action yieldeth, and, liberated from the bonds of birth, they go to the blissful seat.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-52', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 52, 'Chapter 2, Verse 52', 'यदा ते मोहकलिलं बुद्धिर्व्यतितरिष्यति।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-52', 'en', 'When thy mind shall escape from this tangle of delusion, then thou shalt rise to indifference as to what has been heard and shall be heard.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-53', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 53, 'Chapter 2, Verse 53', 'श्रुतिविप्रतिपन्ना ते यदा स्थास्यति निश्चला।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-53', 'en', 'When thy mind, bewildered by the Scriptures, shall stand immovable, fixed in contemplation, then shalt thou attain unto yoga.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-54', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 54, 'Chapter 2, Verse 54', 'स्थितप्रज्ञस्य का भाषा समाधिस्थस्य केशव।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-54', 'en', 'What the mark, of him who is stable of mind, steadfast in contemplation, O Keshava? How doth the stable-minded talk, how doth he sit, how walk?', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-55', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 55, 'Chapter 2, Verse 55', 'प्रजहाति यदा कामान्सर्वान्पार्थ मनोगतान्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-55', 'en', 'When a man abandoneth, O Pârtha, all the desires of the heart, and is satisfied in the Self by the Self, then is he called stable in mind.', 'besant-1922', true);
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-56', 'en', 'He whose mind is free from anxiety amid pains, indifferent amid pleasures, loosed from passion, fear and anger, is called a sage of stable mind.', 'besant-1922', false);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-57', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 57, 'Chapter 2, Verse 57', 'यः सर्वत्रानभिस्नेहस्तत्तत्प्राप्य शुभाशुभम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-57', 'en', 'He who on every side is without attachments, whatever hap of fair and foul, who neither likes nor dislikes, of such a one the understanding is well poised.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-58', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 58, 'Chapter 2, Verse 58', 'यदा संहरते चायं कूर्मोऽङ्गानीव सर्वशः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-58', 'en', 'When, again, as a tortoise draws in on all sides its limbs, he withdraws his senses from the objects of sense, then is his understanding well poised.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-59', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 59, 'Chapter 2, Verse 59', 'विषया विनिवर्तन्ते निराहारस्य देहिनः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-59', 'en', 'The objects of sense, but not the relish for them, turn away from an abstemious dweller in the body; and even relish turneth away from him after the Supreme is seen.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-60', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 60, 'Chapter 2, Verse 60', 'यततो ह्यपि कौन्तेय पुरुषस्य विपश्चितः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-60', 'en', 'O son of Kuntî, the excited senses of even a wise man, though he be striving, impetuously carry away his mind.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-61', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 61, 'Chapter 2, Verse 61', 'तानि सर्वाणि संयम्य युक्त आसीत मत्परः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-61', 'en', 'Having restrained them all, he should sit harmonised, I his supreme goal; for, whose senses are mastered, of him the understanding is well poised.', 'besant-1922', true);
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-62', 'en', 'Man, musing on the objects of sense, conceiveth an attachment to these; from attachment ariseth desire; from desire anger cometh forth;', 'besant-1922', false);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-63', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 63, 'Chapter 2, Verse 63', 'क्रोधाद्भवति संमोहः संमोहात्स्मृतिविभ्रमः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-63', 'en', 'From anger proceedeth delusion; from delusion confused memory; from confused memory the destruction of Reason; from destruction of Reason he perishes.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-64', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 64, 'Chapter 2, Verse 64', 'रागद्वेषवियुक्तैस्तु विषयानिन्द्रियैश्चरन्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-64', 'en', 'But the disciplined self, moving among sense-objects with senses free from attraction and repulsion, mastered by the Self, goeth to peace.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-65', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 65, 'Chapter 2, Verse 65', 'प्रसादे सर्वदुःखानां हानिरस्योपजायते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-65', 'en', 'In that Peace the extinction of all pains ariseth for him, for of him whose heart is peaceful the Reason soon attaineth equilibrium.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-66', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 66, 'Chapter 2, Verse 66', 'नास्ति बुद्धिरयुक्तस्य न चायुक्तस्य भावना।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-66', 'en', 'There is no Pure Reason for the non-harmonised, nor for the non-harmonised is there concentration; for him without concentration there is no peace, and for the unpeaceful how can there be happiness?', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-67', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 67, 'Chapter 2, Verse 67', 'इन्द्रियाणां हि चरतां यन्मनोऽनुविधीयते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-67', 'en', 'Such of the roving senses as the mind yieldeth to, that hurries away the understanding, just as the gale hurries away a ship upon the waters.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-68', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 68, 'Chapter 2, Verse 68', 'तस्माद्यस्य महाबाहो निगृहीतानि सर्वशः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-68', 'en', 'Therefore, O mighty-armed, whose senses are all completely restrained from the objects of sense, of him the understanding is well poised.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-69', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 69, 'Chapter 2, Verse 69', 'या निशा सर्वभूतानां तस्यां जागर्ति संयमी।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-69', 'en', 'That which is the night of all beings, for the disciplined man is the time of waking; when other beings are waking, then is it night for the sage who seeth.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-70', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 70, 'Chapter 2, Verse 70', 'आपूर्यमाणमचलप्रतिष्ठं समुद्रमापः प्रविशन्ति यद्वत्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-70', 'en', 'He attaineth Peace, into whom all desires flow as rivers flow into the ocean, which is filled with water, but remaineth unmoved—not he who desireth desires.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-71', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 71, 'Chapter 2, Verse 71', 'विहाय कामान्यः सर्वान्पुमांश्चरति निःस्पृहः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-71', 'en', 'Whoso forsaketh all desires and goeth onwards free from yearnings, selfless and without egoism—he goeth to Peace.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-2-72', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 2), 72, 'Chapter 2, Verse 72', 'एषा ब्राह्मी स्थितिः पार्थ नैनां प्राप्य विमुह्यति।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-2-72', 'en', 'This is the Eternal state, O son of Prithâ. Having attained thereto, none is bewildered. Who, even at the death-hour, is established therein, he goeth to the Nirvâna of the Eternal.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-1', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 1, 'Chapter 3, Verse 1', 'ज्यायसी चेत्कर्मणस्ते मता बुद्धिर्जनार्दन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-1', 'en', 'If it be thought by Thee that knowledge is superior to action, O Janârdana, why dost Thou, O Keshava, enjoin on me this terrible action?', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-2', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 2, 'Chapter 3, Verse 2', 'व्यामिश्रेणैव वाक्येन बुद्धिं मोहयसीव मे।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-2', 'en', 'With these perplexing words Thou only confusest my understanding; therefore tell me with certainty the one way by which I may reach bliss.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-3', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 3, 'Chapter 3, Verse 3', 'लोकेऽस्मिन्द्विविधा निष्ठा पुरा प्रोक्ता मयानघ।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-3', 'en', 'In this world there is a twofold path, as I before said, O sinless one: that of yoga by knowledge, of the Sâñkhyas; and that of yoga by action, of the Yogis.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-4', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 4, 'Chapter 3, Verse 4', 'न कर्मणामनारम्भान्नैष्कर्म्यं पुरुषोऽश्नुते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-4', 'en', 'Man winneth not freedom from action by abstaining from activity, nor by mere renunciation doth he rise to perfection.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-5', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 5, 'Chapter 3, Verse 5', 'न हि कश्चित्क्षणमपि जातु तिष्ठत्यकर्मकृत्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-5', 'en', 'Nor can anyone, even for an instant, remain really actionless; for helplessly is everyone driven to action by the qualities born of nature.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-6', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 6, 'Chapter 3, Verse 6', 'कर्मेन्द्रियाणि संयम्य य आस्ते मनसा स्मरन्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-6', 'en', 'Who sitteth, controlling the organs of action, but dwelling in his mind on the objects of the senses, that bewildered man is called a hypocrite.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-7', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 7, 'Chapter 3, Verse 7', 'यस्त्विन्द्रियाणि मनसा नियम्यारभतेऽर्जुन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-7', 'en', 'But who, controlling the senses by the mind, O Arjuna, with the organs of action without attachment, performeth yoga by action, he is worthy.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-8', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 8, 'Chapter 3, Verse 8', 'नियतं कुरु कर्म त्वं कर्म ज्यायो ह्यकर्मणः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-8', 'en', 'Perform thou right action, for, action is superior to inaction, and, inactive, even the maintenance of thy body would not be possible.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-9', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 9, 'Chapter 3, Verse 9', 'यज्ञार्थात्कर्मणोऽन्यत्र लोकोऽयं कर्मबन्धनः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-9', 'en', 'The world is bound by action, unless performed for the sake of sacrifice; for that sake, free from attachment, O son of Kuntî, perform thou action.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-10', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 10, 'Chapter 3, Verse 10', 'सहयज्ञाः प्रजाः सृष्ट्वा पुरोवाच प्रजापतिः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-10', 'en', 'Having in ancient times emanated mankind together with sacrifice, the Lord of emanation said: "By this shall ye propagate; be this to you the giver of desire;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-11', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 11, 'Chapter 3, Verse 11', 'देवान्भावयतानेन ते देवा भावयन्तु वः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-11', 'en', '"With this nourish ye the Shining Ones, and may the Shining Ones nourish you; thus nourishing one another ye shall reap the supremest good.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-12', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 12, 'Chapter 3, Verse 12', 'इष्टान्भोगान्हि वो देवा दास्यन्ते यज्ञभाविताः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-12', 'en', '"For, nourished by sacrifice, the Shining Ones shall bestow on you the enjoyments you desire." A thief verily is he who enjoyeth what is given by Them without returning Them aught.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-13', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 13, 'Chapter 3, Verse 13', 'यज्ञशिष्टाशिनः सन्तो मुच्यन्ते सर्वकिल्बिषैः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-13', 'en', 'The righteous, who eat the remains of the sacrifice, are freed from all sins; but the impious, who dress food for their own sakes, they verily eat sin.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-14', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 14, 'Chapter 3, Verse 14', 'अन्नाद्भवन्ति भूतानि पर्जन्यादन्नसंभवः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-14', 'en', 'From food creatures become; from rain is the production of food; rain proceedeth from sacrifice; sacrifice ariseth out of action.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-15', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 15, 'Chapter 3, Verse 15', 'कर्म ब्रह्मोद्भवं विद्धि ब्रह्माक्षरसमुद्भवम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-15', 'en', 'Know thou that from Brahma action groweth, and Brahma from the Imperishable cometh. Therefore the Eternal, the all-permeating, is ever present in sacrifice.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-16', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 16, 'Chapter 3, Verse 16', 'एवं प्रवर्तितं चक्रं नानुवर्तयतीह यः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-16', 'en', 'He who on earth doth not follow the wheel thus revolving, sinful of life and rejoicing in the senses, he, O son of Pritha, liveth in vain.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-17', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 17, 'Chapter 3, Verse 17', 'यस्त्वात्मरतिरेव स्यादात्मतृप्तश्च मानवः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-17', 'en', 'But the man who rejoiceth in the Self, with the Self is satisfied, and is content in the Self, for him verily there is nothing to do;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-18', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 18, 'Chapter 3, Verse 18', 'नैव तस्य कृतेनार्थो नाकृतेनेह कश्चन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-18', 'en', 'For him there is no interest in things done, in this world, nor any in things not done, nor doth any object of his depend on any being.', 'besant-1922', true);
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-19', 'en', 'Therefore, without attachment, constantly perform action which is duty, for, by performing action without attachment, man verily reacheth the Supreme.', 'besant-1922', false);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-20', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 20, 'Chapter 3, Verse 20', 'कर्मणैव हि संसिद्धिमास्थिता जनकादयः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-20', 'en', 'Janaka and others indeed attained to perfection by action: then having an eye to the welfare of the world also, thou shouldst perform action.', 'besant-1922', true);
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-21', 'en', 'Whatsoever a great man doeth, that other men also do; the standard he setteth up, by that the people go.', 'besant-1922', false);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-22', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 22, 'Chapter 3, Verse 22', 'न मे पार्थास्ति कर्तव्यं त्रिषु लोकेषु किं चन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-22', 'en', 'There is nothing in the three worlds, O Pârtha, that should be done by Me, nor anything unattained that might be attained; yet I mingle in action.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-23', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 23, 'Chapter 3, Verse 23', 'यदि ह्यहं न वर्तेयं जातु कर्मण्यतन्द्रितः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-23', 'en', 'For if I mingled not ever in action unwearied, men all around would follow My path, O son of Prithâ.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-24', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 24, 'Chapter 3, Verse 24', 'उत्सीदेयुरिमे लोका न कुर्यां कर्म चेदहम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-24', 'en', 'These worlds would fall into ruin, if I did not perform action; I should be the author of confusion of castes, and should destroy these creatures.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-25', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 25, 'Chapter 3, Verse 25', 'सक्ताः कर्मण्यविद्वांसो यथा कुर्वन्ति भारत।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-25', 'en', 'As the ignorant act from attachment to action, O Bhârata, so should the wise act without attachment, desiring the welfare of the world.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-26', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 26, 'Chapter 3, Verse 26', 'न बुद्धिभेदं जनयेदज्ञानां कर्मसङ्गिनाम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-26', 'en', 'Let no wise man unsettle the mind of ignorant people attached to action; but acting in harmony with Me let him render all action attractive.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-27', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 27, 'Chapter 3, Verse 27', 'प्रकृतेः क्रियमाणानि गुणैः कर्माणि सर्वशः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-27', 'en', 'All actions are wrought by the quali- ties of nature only. The self, deluded by egoism, thinketh: "I am the doer."', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-28', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 28, 'Chapter 3, Verse 28', 'तत्त्ववित्तु महाबाहो गुणकर्मविभागयोः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-28', 'en', 'But he, O mighty-armed, who knoweth the essence of the divisions of the qualities and functions, holding that "the qualities move amid the qualities," is not attached.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-29', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 29, 'Chapter 3, Verse 29', 'प्रकृतेर्गुणसंमूढाः सज्जन्ते गुणकर्मसु।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-29', 'en', 'Those deluded by the qualities of nature are attached to the functions of the qualities. The man of perfect knowledge should not unsettle the foolish whose knowledge is imperfect.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-30', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 30, 'Chapter 3, Verse 30', 'मयि सर्वाणि कर्माणि संन्यस्याध्यात्मचेतसा।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-30', 'en', 'Surrendering all actions to Me, with thy thoughts resting on the supreme Self, from hope and egoism freed, and of mental fever cured, engage in battle.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-31', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 31, 'Chapter 3, Verse 31', 'ये मे मतमिदं नित्यमनुतिष्ठन्ति मानवाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-31', 'en', 'Who abide ever in this teaching of Mine full of faith and free from caviling, they too are released from actions.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-32', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 32, 'Chapter 3, Verse 32', 'ये त्वेतदभ्यसूयन्तो नानुतिष्ठन्ति मे मतम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-32', 'en', 'Who carp at My teaching and act not thereon, senseless, deluded in all knowledge, know thou these mindless ones as fated to be destroyed.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-33', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 33, 'Chapter 3, Verse 33', 'सदृशं चेष्टते स्वस्याः प्रकृतेर्ज्ञानवानपि।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-33', 'en', 'Even the man of knowledge behaves in conformity with his own nature; beings follow nature; what shall restraint avail?', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-34', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 34, 'Chapter 3, Verse 34', 'इन्द्रियस्येन्द्रियस्यार्थे रागद्वेषौ व्यवस्थितौ।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-34', 'en', 'Affection and aversion for the objects of sense abide in the senses; let none come under the dominion of these two; they are obstructors of the path.', 'besant-1922', true);
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-35', 'en', 'Better one''s own duty, though destitute of merit, than the duty of another, well discharged. Better death in the discharge of one''s own duty; the duty of another is full of danger.', 'besant-1922', false);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-36', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 36, 'Chapter 3, Verse 36', 'अथ केन प्रयुक्तोऽयं पापं चरति पूरुषः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-36', 'en', 'But dragged on by what does a man commit sin, reluctantly indeed, O Varshneya, as it were by force constrained?', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-37', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 37, 'Chapter 3, Verse 37', 'काम एष क्रोध एष रजोगुणसमुद्भवः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-37', 'en', 'It is desire, it is wrath, begotten by the quality of motion; all-consuming, all-polluting, know thou this as our foe here on earth.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-38', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 38, 'Chapter 3, Verse 38', 'धूमेनाव्रियते वह्निर्यथादर्शो मलेन च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-38', 'en', 'As a flame is enveloped by smoke, as a mirror by dust, as an embryo is wrapped by the amnion, so This is enveloped by it.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-39', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 39, 'Chapter 3, Verse 39', 'आवृतं ज्ञानमेतेन ज्ञानिनो नित्यवैरिणा।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-39', 'en', 'Enveloped is wisdom by this constant enemy of the wise in the form of desire, which is insatiable as a flame.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-40', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 40, 'Chapter 3, Verse 40', 'इन्द्रियाणि मनो बुद्धिरस्याधिष्ठानमुच्यते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-40', 'en', 'The senses, the mind and the Reason are said to be its seat; by these enveloping wisdom, it bewilders the dweller in the body.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-41', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 41, 'Chapter 3, Verse 41', 'तस्मात्त्वमिन्द्रियाण्यादौ नियम्य भरतर्षभ।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-41', 'en', 'Therefore, O best of the Bhâratas, mastering first the senses, do thou slay this thing of sin, destructive of wisdom and knowledge.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-42', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 42, 'Chapter 3, Verse 42', 'इन्द्रियाणि पराण्याहुरिन्द्रियेभ्यः परं मनः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-42', 'en', 'It is said that the senses are great; greater than the senses is the mind: greater than the mind is the Reason; but what is greater than the Reason, is He.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-3-43', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 3), 43, 'Chapter 3, Verse 43', 'एवं बुद्धेः परं बुद्ध्वा संस्तभ्यात्मानमात्मना।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-3-43', 'en', 'Thus understanding Him as greater than the Reason, restraining the self by the Self, slay thou, O mighty-armed, the enemy in the form of desire, difficult to overcome.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-1', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 1, 'Chapter 4, Verse 1', 'इमं विवस्वते योगं प्रोक्तवानहमव्ययम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-1', 'en', 'This imperishable yoga I declared to Vivasvân; Vivasvân taught it to Manu; Manu to Ikshvâku told it.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-2', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 2, 'Chapter 4, Verse 2', 'एवं परंपराप्राप्तमिमं राजर्षयो विदुः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-2', 'en', 'This, handed on down the line, the King-Sages knew. This yoga by great efflux of time decayed in the world, O Parantapa.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-3', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 3, 'Chapter 4, Verse 3', 'स एवायं मया तेऽद्य योगः प्रोक्तः पुरातनः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-3', 'en', 'This same ancient yoga hath been to-day declared to thee by Me, for thou art My devotee and My friend; it is the supreme Secret.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-4', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 4, 'Chapter 4, Verse 4', 'अपरं भवतो जन्म परं जन्म विवस्वतः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-4', 'en', 'Later was Thy birth, earlier the birth of Vivasvân; how then am I to understand that Thou declaredst it in the beginning?', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-5', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 5, 'Chapter 4, Verse 5', 'बहूनि मे व्यतीतानि जन्मानि तव चार्जुन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-5', 'en', 'Many births have been left behind by Me and by thee, O Arjuna. I know them all, but thou knowest not thine, O Parantapa.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-6', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 6, 'Chapter 4, Verse 6', 'अजोऽपि सन्नव्ययात्मा भूतानामीश्वरोऽपि सन्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-6', 'en', 'Though unborn, the imperishable Self, and also the Lord of all beings, brooding over nature which is Mine own, yet I am born through My own Power.', 'besant-1922', true);
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-7', 'en', 'Whenever there is decay of righteousness, O Bhârata, and there is exaltation of unrighteousness, then I Myself come forth;', 'besant-1922', false);
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-8', 'en', 'For the protection of the good, for the destruction of evil-doers, for the sake of firmly establishing righteousness, I am born from age to age.', 'besant-1922', false);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-9', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 9, 'Chapter 4, Verse 9', 'जन्म कर्म च मे दिव्यमेवं यो वेत्ति तत्त्वतः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-9', 'en', 'He who thus knoweth My divine birth and action, in its essence, having abandoned the body, cometh not to birth again, but cometh unto Me, O Arjuna.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-10', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 10, 'Chapter 4, Verse 10', 'वीतरागभयक्रोधा मन्मया मामुपाश्रिताः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-10', 'en', 'Freed from passion, fear and anger, filled with Me, taking refuge in Me, purified in the fire of wisdom, many have entered into My Being.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-11', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 11, 'Chapter 4, Verse 11', 'ये यथा मां प्रपद्यन्ते तांस्तथैव भजाम्यहम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-11', 'en', 'However men approach Me, even so do I welcome them, for the path men take from every side is Mine, O Pârtha.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-12', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 12, 'Chapter 4, Verse 12', 'काङ्क्षन्तः कर्मणां सिद्धिं यजन्त इह देवताः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-12', 'en', 'They who long after success in action on earth worship the Shining Ones; for in brief space verily, in this world of men, success is born of action.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-13', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 13, 'Chapter 4, Verse 13', 'चातुर्वर्ण्यं मया सृष्टं गुणकर्मविभागशः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-13', 'en', 'The four castes were emanated by Me, by the different distribution of qualities and actions; know Me to be the author of them, though the actionless and inexhaustible.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-14', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 14, 'Chapter 4, Verse 14', 'न मां कर्माणि लिम्पन्ति न मे कर्मफले स्पृहा।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-14', 'en', 'Nor do actions affect Me, nor is the fruit of action desired by Me. He who thus knoweth Me is not bound by actions.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-15', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 15, 'Chapter 4, Verse 15', 'एवं ज्ञात्वा कृतं कर्म पूर्वैरपि मुमुक्षुभिः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-15', 'en', 'Having thus known, our forefathers, ever seeking liberation, performed action; therefore do thou also perform action, as did our forefathers in the olden time.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-16', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 16, 'Chapter 4, Verse 16', 'किं कर्म किमकर्मेति कवयोऽप्यत्र मोहिताः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-16', 'en', '"What is action, what inaction"? Even the wise are herein perplexed. Therefore I will declare to thee the action by knowing which thou shalt be loosed from evil.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-17', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 17, 'Chapter 4, Verse 17', 'कर्मणो ह्यपि बोद्धव्यं बोद्धव्यं च विकर्मणः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-17', 'en', 'It is needful to discriminate action, to discriminate unlawful action, and to discriminate inaction; mysterious is the path of action.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-18', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 18, 'Chapter 4, Verse 18', 'कर्मण्यकर्म यः पश्येदकर्मणि च कर्म यः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-18', 'en', 'He who seeth inaction in action, and action in inaction, he is wise among men, he is harmonious, even while performing all action.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-19', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 19, 'Chapter 4, Verse 19', 'यस्य सर्वे समारम्भाः कामसंकल्पवर्जिताः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-19', 'en', 'Whose works are all free from the moulding of desire, whose actions are burned up by the fire of wisdom, him the wise have called a Sage.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-20', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 20, 'Chapter 4, Verse 20', 'त्यक्त्वा कर्मफलासङ्गं नित्यतृप्तो निराश्रयः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-20', 'en', 'Having abandoned attachment to the fruit of action, always content, nowhere seeking refuge, he is not doing anything, although doing actions.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-21', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 21, 'Chapter 4, Verse 21', 'निराशीर्यतचित्तात्मा त्यक्तसर्वपरिग्रहः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-21', 'en', 'Hoping for naught, his mind and self controlled, having abandoned all greed, performing action by the body alone, he doth not commit sin.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-22', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 22, 'Chapter 4, Verse 22', 'यदृच्छालाभसंतुष्टो द्वंद्वातीतो विमत्सरः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-22', 'en', 'Content with whatsoever he obtaineth without effort, free from the pairs of opposites, without envy, balanced in success and failure, though acting he is not bound.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-23', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 23, 'Chapter 4, Verse 23', 'गतसङ्गस्य मुक्तस्य ज्ञानावस्थितचेतसः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-23', 'en', 'Of one with attachment dead, harmonious, with his thoughts established in wisdom, his works sacrifices, all action melts away.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-24', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 24, 'Chapter 4, Verse 24', 'ब्रह्मार्पणं ब्रह्महविर्ब्रह्माग्नौ ब्रह्मणा हुतम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-24', 'en', 'The Eternal the oblation, the Eternal the clarified butter, are offered in the Eternal the fire by the Eternal; unto the Eternal verily shall he go who in his action meditateth wholly upon the Eternal.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-25', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 25, 'Chapter 4, Verse 25', 'दैवमेवापरे यज्ञं योगिनः पर्युपासते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-25', 'en', 'Some Yogis offer up sacrifice to the Shining Ones; others sacrifice only by pouring sacrifice into the fire of the Eternal;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-26', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 26, 'Chapter 4, Verse 26', 'श्रोत्रादीनीन्द्रियाण्यन्ये संयमाग्निषु जुह्वति।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-26', 'en', 'Some pour as sacrifice hearing and the other senses into the fires of restraint; some pour sound and the other objects of sense into the fires of the senses as sacrifice;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-27', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 27, 'Chapter 4, Verse 27', 'सर्वाणीन्द्रियकर्माणि प्राणकर्माणि चापरे।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-27', 'en', 'Others again into the wisdom-kindled fire of union attained by self-control, pour as sacrifice all the functions of the senses and the functions of life;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-28', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 28, 'Chapter 4, Verse 28', 'द्रव्ययज्ञास्तपोयज्ञा योगयज्ञास्तथापरे।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-28', 'en', 'Yet others the sacrifice of wealth, the sacrifice of austerity, the sacrifice of yoga, the sacrifice of silent reading and wisdom, men concentrated and of effectual vows;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-29', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 29, 'Chapter 4, Verse 29', 'अपाने जुह्वति प्राणं प्राणेऽपानं तथापरे।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-29', 'en', 'Yet others pour as sacrifice the outgoing breath in the incoming, and the incoming in the outgoing, restraining the flow of the outgoing and incoming breaths, solely absorbed in the control of breathing.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-30', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 30, 'Chapter 4, Verse 30', 'अपरे नियताहाराः प्राणान्प्राणेषु जुह्वति।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-30', 'en', 'Others regular in food, pour as sacrifice their life-breaths in life-breaths. All these are knowers of sacrifice, and by sacrifice have destroyed their sins.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-31', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 31, 'Chapter 4, Verse 31', 'यज्ञशिष्टामृतभुजो यान्ति ब्रह्म सनातनम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-31', 'en', 'The eaters of the life-giving remains of sacrifice go to the changeless Eternal. This world is not for the non-sacrificer, much less the other, O best of the Kurus.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-32', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 32, 'Chapter 4, Verse 32', 'एवं बहुविधा यज्ञा वितता ब्रह्मणो मुखे।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-32', 'en', 'Many and various sacrifices are thus spread out before the Eternal. Know thou that all these are born of action, and thus knowing thou shalt be free.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-33', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 33, 'Chapter 4, Verse 33', 'श्रेयान्द्रव्यमयाद्यज्ञाज्ज्ञानयज्ञः परंतप।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-33', 'en', 'Better than the sacrifice of any objects is the sacrifice of wisdom, O Parantapa. All actions in their entirety, O Pârtha, culminate in wisdom.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-34', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 34, 'Chapter 4, Verse 34', 'तद्विद्धि प्रणिपातेन परिप्रश्नेन सेवया।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-34', 'en', 'Learn thou this by discipleship, by investiga- tion, and by service. The wise, the seers of the essence of things, will instruct thee in wisdom.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-35', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 35, 'Chapter 4, Verse 35', 'यज्ज्ञात्वा न पुनर्मोहमेवं यास्यसि पाण्डव।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-35', 'en', 'And having known this, thou shalt not again fall into this confusion, O Pândava; for by this thou wilt see all beings without exception in the Self, and thus in Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-36', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 36, 'Chapter 4, Verse 36', 'अपि चेदसि पापेभ्यः सर्वेभ्यः पापकृत्तमः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-36', 'en', 'Even if thou art the most sinful of all sinners, yet shalt thou cross over all sin by the raft of wisdom.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-37', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 37, 'Chapter 4, Verse 37', 'यथैधांसि समिद्धोऽग्निर्भस्मसात्कुरुतेऽर्जुन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-37', 'en', 'As the burning fire reduces fuel to ashes, O Arjuna, so doth the fire of wisdom reduce all actions to ashes.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-38', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 38, 'Chapter 4, Verse 38', 'न हि ज्ञानेन सदृशं पवित्रमिह विद्यते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-38', 'en', 'Verily there is no purifier in this world like wisdom; he that is perfected in yoga finds it in the Self in due season.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-39', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 39, 'Chapter 4, Verse 39', 'श्रद्धावांल्लभते ज्ञानं तत्परः संयतेन्द्रियः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-39', 'en', 'The man who is full of faith obtaineth wisdom, and he also who hath mastery over his senses; and, having obtained wisdom, he goeth swiftly to the supreme Peace.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-40', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 40, 'Chapter 4, Verse 40', 'अज्ञश्चाश्रद्दधानश्च संशयात्मा विनश्यति।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-40', 'en', 'But the ignorant, faithless, doubting self goeth to destruction; nor this world, nor that beyond, nor happiness, is there for the doubting self.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-41', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 41, 'Chapter 4, Verse 41', 'योगसंन्यस्तकर्माणं ज्ञानसंछिन्नसंशयम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-41', 'en', 'He who hath renounced actions by yoga, who hath cloven asunder doubt by wisdom, who is ruled by the Self, actions do not bind him, O Dhananjaya.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-4-42', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 4), 42, 'Chapter 4, Verse 42', 'तस्मादज्ञानसंभूतं हृत्स्थं ज्ञानासिनात्मनः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-4-42', 'en', 'Therefore, with the sword of the wisdom of the Self cleaving asunder this ignorance-born doubt dwelling in thy heart, be established in yoga. Stand up, O Bhârata.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-1', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 1, 'Chapter 5, Verse 1', 'संन्यासं कर्मणां कृष्ण पुनर्योगं च शंससि।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-1', 'en', 'Renunciation of actions Thou praisest, O Krishna, and then also yoga. Of the two which one is the better? That tell me conclusively.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-2', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 2, 'Chapter 5, Verse 2', 'संन्यासः कर्मयोगश्च निःश्रेयसकरावुभौ।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-2', 'en', 'Renunciation and yoga by action both lead to the highest bliss; of the two, yoga by action is verily better than renunciation of action.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-3', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 3, 'Chapter 5, Verse 3', 'ज्ञेयः स नित्यसंन्यासी यो न द्वेष्टि न काङ्क्षति।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-3', 'en', 'He should be known as a perpetual ascetic, who neither hateth nor desireth; free from the pairs of opposites, O mighty-armed, he is easily set free from bondage.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-4', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 4, 'Chapter 5, Verse 4', 'सांख्ययोगौ पृथग्बालाः प्रवदन्ति न पण्डिताः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-4', 'en', 'Children, not sages, speak of the Sânkhya and the Yoga as different; he who is duly established in one obtaineth the fruits of both.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-5', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 5, 'Chapter 5, Verse 5', 'यत्सांख्यैः प्राप्यते स्थानं तद्योगैरपि गम्यते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-5', 'en', 'That place which is gained by the Sânkhyas is reached by the Yogîs also. He seeth, who seeth that the Sânkhya and the Yoga are one.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-6', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 6, 'Chapter 5, Verse 6', 'संन्यासस्तु महाबाहो दुःखमाप्तुमयोगतः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-6', 'en', 'But without yoga, O mighty-armed, renunciation is hard to attain to; the yoga-harmonised Muni swiftly goeth to the Eternal.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-7', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 7, 'Chapter 5, Verse 7', 'योगयुक्तो विशुद्धात्मा विजितात्मा जितेन्द्रियः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-7', 'en', 'He who is harmonised by yoga, the self purified, Self-ruled, the senses subdued, whose Self is the Self of all beings, although acting he is not affected.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-8', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 8, 'Chapter 5, Verse 8', 'नैव किं चित्करोमीति युक्तो मन्येत तत्त्ववित्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-8', 'en', '"I do not anything," should think the harmonised one, who knoweth the essence of things; seeing, hearing, touching, smelling, eating, moving, sleeping, breathing.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-9', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 9, 'Chapter 5, Verse 9', 'प्रलपन्विसृजन्गृह्णन्नुन्मिषन्निमिषन्नपि।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-9', 'en', 'Speaking, giving, grasping, opening and closing the eyes, he holdeth: "The senses move among the objects of the senses."', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-10', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 10, 'Chapter 5, Verse 10', 'ब्रह्मण्याधाय कर्माणि सङ्गं त्यक्त्वा करोति यः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-10', 'en', 'He who acteth, placing all actions in the Eternal, abandoning attachment, is unaffected by sin as a lotus leaf by the waters.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-11', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 11, 'Chapter 5, Verse 11', 'कायेन मनसा बुद्ध्या केवलैरिन्द्रियैरपि।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-11', 'en', 'Yogis, having abandoned attachment, perform action only by the body, by the mind, by the Reason, and even by the senses, for the purification of the self.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-12', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 12, 'Chapter 5, Verse 12', 'युक्तः कर्मफलं त्यक्त्वा शान्तिमाप्नोति नैष्ठिकीम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-12', 'en', 'The harmonised man, having abandoned the fruit of action, attaineth to the eternal Peace; the non-harmonised, impelled by desire, attached to fruit, are bound.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-13', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 13, 'Chapter 5, Verse 13', 'सर्वकर्माणि मनसा संन्यस्यास्ते सुखं वशी।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-13', 'en', 'Mentally renouncing all actions, the sovereign dweller in the body resteth serenely in the nine-gated city, neither acting nor causing to act.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-14', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 14, 'Chapter 5, Verse 14', 'न कर्तृत्वं न कर्माणि लोकस्य सृजति प्रभुः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-14', 'en', 'The Lord of the world produceth not the idea of agency, nor actions, nor the union together of action and its fruit; nature, however, manifesteth.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-15', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 15, 'Chapter 5, Verse 15', 'नादत्ते कस्य चित्पापं न चैव सुकृतं विभुः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-15', 'en', 'The Lord accepteth neither the evil-doing nor yet the well-doing of any. Wisdom is enveloped by unwisdom; therewith mortals are deluded.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-16', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 16, 'Chapter 5, Verse 16', 'ज्ञानेन तु तदज्ञानं येषां नाशितमात्मनः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-16', 'en', 'Verily, in whom unwisdom is destroyed by the wisdom of the Self, in them wisdom, shining as the sun, reveals the Supreme.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-17', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 17, 'Chapter 5, Verse 17', 'तद्बुद्धयस्तदात्मानस्तन्निष्ठास्तत्परायणाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-17', 'en', 'Thinking on That, merged in That, established in That, solely devoted to That, they go whence there is no return, their sins dispelled by wisdom.', 'besant-1922', true);
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-18', 'en', 'Sages look equally on a Brâhmana adorned with learning and humility, a cow, an elephant, and even a dog and an outcaste.', 'besant-1922', false);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-19', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 19, 'Chapter 5, Verse 19', 'इहैव तैर्जितः सर्गो येषां साम्ये स्थितं मनः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-19', 'en', 'Even here on earth everything is overcome by those whose mind remains balanced; the Eternal is incorruptible and balanced; therefore they are established in the Eternal.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-20', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 20, 'Chapter 5, Verse 20', 'न प्रहृष्येत्प्रियं प्राप्य नोद्विजेत्प्राप्य चाप्रियम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-20', 'en', 'With Reason firm, unperplexed, the knower of the Eternal established in the Eternal, neither rejoiceth on obtaining what is pleasant, nor sorroweth on obtaining what is unpleasant.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-21', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 21, 'Chapter 5, Verse 21', 'बाह्यस्पर्शेष्वसक्तात्मा विन्दत्यात्मनि यत्सुखम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-21', 'en', 'He, whose self is unattached to external contacts and findeth joy in the Self, having the self harmonised with the Eternal by yoga, enjoys imperishable bliss.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-22', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 22, 'Chapter 5, Verse 22', 'ये हि संस्पर्शजा भोगा दुःखयोनय एव ते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-22', 'en', 'The delights that are contact-born, they are verily wombs of pain, for they have beginning and ending, O Kaunteya; not in them may rejoice the wise.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-23', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 23, 'Chapter 5, Verse 23', 'शक्नोतीहैव यः सोढुं प्राक्शरीरविमोक्षणात्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-23', 'en', 'He who is able to endure here on earth, ere he be liberated from the body, the force born from desire and passion, he is harmonised, he is a happy man.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-24', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 24, 'Chapter 5, Verse 24', 'योऽन्तःसुखोऽन्तरारामस्तथान्तर्ज्योतिरेव यः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-24', 'en', 'He who is happy within, who rejoiceth within, who is illuminated within, that Yogî, becoming the Eternal, goeth to the Peace of the Eternal.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-25', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 25, 'Chapter 5, Verse 25', 'लभन्ते ब्रह्मनिर्वाणमृषयः क्षीणकल्मषाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-25', 'en', 'Rishis, their sins destroyed, their duality removed, their selves controlled, intent upon the welfare of all beings, obtain the Peace of the Eternal.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-26', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 26, 'Chapter 5, Verse 26', 'कामक्रोधवियुक्तानां यतीनां यतचेतसाम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-26', 'en', 'The Peace of the Eternal lies near to those who know themselves, who are disjoined from desire and passion, subdued in nature, of subdued thoughts.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-27', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 27, 'Chapter 5, Verse 27', 'स्पर्शान्कृत्वा बहिर्बाह्यांश्चक्षुश्चैवान्तरे भ्रुवोः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-27', 'en', 'Having external contacts excluded, and with gaze fixed between the eyebrows; having made equal the outgoing and ingoing breaths moving within the nostrils;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-28', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 28, 'Chapter 5, Verse 28', 'यतेन्द्रियमनोबुद्धिर्मुनिर्मोक्षपरायणः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-28', 'en', 'With senses, mind, and Reason ever controlled, solely pursuing liberation, the Sage, having for ever cast away desire, fear and passion, verily is liberated.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-5-29', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 5), 29, 'Chapter 5, Verse 29', 'भोक्तारं यज्ञतपसां सर्वलोकमहेश्वरम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-5-29', 'en', 'Having known Me, as the Enjoyer of sacrifice and of austerity, the mighty Ruler of all the worlds, and the Lover of all beings, he goeth to Peace.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-1', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 1, 'Chapter 6, Verse 1', 'अनाश्रितः कर्मफलं कार्यं कर्म करोति यः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-1', 'en', 'He that performeth such action as his duty, independently of the fruit of action, he is an ascetic, he is a Yogî, not he that is without fire, and without rites.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-2', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 2, 'Chapter 6, Verse 2', 'यं संन्यासमिति प्राहुर्योगं तं विद्धि पाण्डव।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-2', 'en', 'That which is called renunciation, know thou that as yoga, O Pândava; nor doth any one become a Yogî with the formative will unrenounced.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-3', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 3, 'Chapter 6, Verse 3', 'आरुरुक्षोर्मुनेर्योगं कर्म कारणमुच्यते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-3', 'en', 'For a Sage who is seeking Yoga, action is called the means; for the same Sage, when he is enthroned in yoga, serenity is called the means.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-4', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 4, 'Chapter 6, Verse 4', 'यदा हि नेन्द्रियार्थेषु न कर्मस्वनुषज्जते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-4', 'en', 'When a man feeleth no attachment either for the objects of sense or for actions, renouncing the formative will, then, he is said to be enthroned in yoga.', 'besant-1922', true);
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-5', 'en', 'Let him raise the self by the Self and not let the self become depressed; for verily is the Self the friend of the self, and also the Self the self''s enemy;', 'besant-1922', false);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-6', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 6, 'Chapter 6, Verse 6', 'बन्धुरात्मात्मनस्तस्य येनात्मैवात्मना जितः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-6', 'en', 'The Self is the friend of the self of him in whom the self by the Self is vanquished; but to the unsubdued self the Self verily becometh hostile as an enemy.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-7', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 7, 'Chapter 6, Verse 7', 'जितात्मनः प्रशान्तस्य परमात्मा समाहितः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-7', 'en', 'The higher Self of him who is Self-controlled and peaceful is uniform in cold and heat, pleasure and pain, as well as in honour and dishonour.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-8', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 8, 'Chapter 6, Verse 8', 'ज्ञानविज्ञानतृप्तात्मा कूटस्थो विजितेन्द्रियः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-8', 'en', 'The Yogî who is satisfied with wisdom and knowledge, unwavering, whose senses are sub- dued, to whom a lump of earth, a stone and gold are the same, is said to be harmonised.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-9', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 9, 'Chapter 6, Verse 9', 'सुहृन्मित्रार्युदासीनमध्यस्थद्वेष्यबन्धुषु।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-9', 'en', 'He who regards impartially lovers, friends, and foes, strangers, neutrals, foreigners and relatives, also the righteous and unrighteous, he excelleth.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-10', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 10, 'Chapter 6, Verse 10', 'योगी युञ्जीत सततमात्मानं रहसि स्थितः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-10', 'en', 'Let the Yogî constantly engage himself in yoga, remaining in a secret place by himself, with thought and self subdued, free from hope and greed.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-11', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 11, 'Chapter 6, Verse 11', 'शुचौ देशे प्रतिष्ठाप्य स्थिरमासनमात्मनः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-11', 'en', 'In a pure place, established on a fixed seat of his own, neither very much raised nor very low, made of a cloth, a black antelope skin, and kusha grass, one over the other;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-12', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 12, 'Chapter 6, Verse 12', 'तत्रैकाग्रं मनः कृत्वा यतचित्तेन्द्रियक्रियः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-12', 'en', 'There, having made the mind one-pointed, with thought and the functions of the senses subdued, steady on his seat, he should practise yoga for the purification of the self.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-13', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 13, 'Chapter 6, Verse 13', 'समं कायशिरोग्रीवं धारयन्नचलं स्थिरः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-13', 'en', 'Holding the body, head and neck erect, immovably steady, looking fixedly at the point of the nose, with unseeing gaze,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-14', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 14, 'Chapter 6, Verse 14', 'प्रशान्तात्मा विगतभीर्ब्रह्मचारिव्रते स्थितः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-14', 'en', 'The self serene, fearless, firm in the vow of the Brahmachâri, the mind controlled, thinking on Me, harmonised, let him sit aspiring after Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-15', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 15, 'Chapter 6, Verse 15', 'युञ्जन्नेवं सदात्मानं योगी नियतमानसः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-15', 'en', 'The Yogî ever united thus with the Self, with the mind controlled, goeth to Peace, to the supreme Bliss that abideth in Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-16', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 16, 'Chapter 6, Verse 16', 'नात्यश्नतस्तु योगोऽस्ति न चैकान्तमनश्नतः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-16', 'en', 'Verily yoga is not for him who eateth too much, nor who abstaineth to excess, nor who is too much addicted to sleep, nor even to wakefulness, O Arjuna.', 'besant-1922', true);
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-17', 'en', 'Yoga killeth out all pain for him who is regulated in eating and amusement, regulated in performing actions, regulated in sleeping and waking.', 'besant-1922', false);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-18', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 18, 'Chapter 6, Verse 18', 'यदा विनियतं चित्तमात्मन्येवावतिष्ठते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-18', 'en', 'When his subdued thought is fixed on the Self, free from longing after all desirable things, then it is said, "he is harmonised."', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-19', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 19, 'Chapter 6, Verse 19', 'यथा दीपो निवातस्थो नेङ्गते सोपमा स्मृता।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-19', 'en', 'As a lamp in a windless place flickereth not, to such is likened the Yogî of subdued thought, absorbed in the yoga of the Self.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-20', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 20, 'Chapter 6, Verse 20', 'यत्रोपरमते चित्तं निरुद्धं योगसेवया।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-20', 'en', 'That in which the mind finds rest, quieted by the practice of yoga: that in which he, seeing the Self by the Self, in the Self is satisfied;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-21', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 21, 'Chapter 6, Verse 21', 'सुखमात्यन्तिकं यत्तद्बुद्धिग्राह्यमतीन्द्रियम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-21', 'en', 'That in which he findeth the supreme delight which the Reason can grasp beyond the senses, wherein established he moveth not from the Reality;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-22', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 22, 'Chapter 6, Verse 22', 'यं लब्ध्वा चापरं लाभं मन्यते नाधिकं ततः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-22', 'en', 'Which, having obtained, he thinketh there is no greater gain beyond it; wherein, established, he is not shaken even by heavy sorrow;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-23', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 23, 'Chapter 6, Verse 23', 'तं विद्याद्दुःखसंयोगवियोगं योगसंज्ञितम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-23', 'en', 'That should be known by the name of yoga, this disconnection from the union with pain. This yoga must be clung to with a firm conviction and with undesponding mind.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-24', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 24, 'Chapter 6, Verse 24', 'संकल्पप्रभवान्कामांस्त्यक्त्वा सर्वानशेषतः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-24', 'en', 'Abandoning without reserve all desires born of the imagination, by the mind curbing in the aggregate of the senses on every side,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-25', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 25, 'Chapter 6, Verse 25', 'शनैः शनैरुपरमेद्बुद्ध्या धृतिगृहीतया।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-25', 'en', 'Little by little let him gain tranquillity, by means of Reason controlled by steadiness; having made the mind abide in the Self, let him not think of anything.', 'besant-1922', true);
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-26', 'en', 'As often as the wavering and unsteady mind goeth forth, so often reining it in, let him bring it under the control of the Self.', 'besant-1922', false);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-27', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 27, 'Chapter 6, Verse 27', 'प्रशान्तमनसं ह्येनं योगिनं सुखमुत्तमम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-27', 'en', 'Supreme joy is for this Yogi whose mind is peaceful, whose passion-nature is calmed, who is sinless and of the nature of the Eternal.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-28', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 28, 'Chapter 6, Verse 28', 'युञ्जन्नेवं सदात्मानं योगी विगतकल्मषः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-28', 'en', 'The Yogî who thus, ever harmonising the self, hath put away sin, he easily enjoyeth the infinite bliss of contact with the Eternal.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-29', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 29, 'Chapter 6, Verse 29', 'सर्वभूतस्थमात्मानं सर्वभूतानि चात्मनि।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-29', 'en', 'The self, harmonised by yoga, seeth the Self abiding in all beings, all beings in the Self; everywhere he seeth the same.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-30', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 30, 'Chapter 6, Verse 30', 'यो मां पश्यति सर्वत्र सर्वं च मयि पश्यति।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-30', 'en', 'He who seeth Me everywhere, and seeth everything in Me, of him will I never lose hold, and he shall never lose hold of Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-31', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 31, 'Chapter 6, Verse 31', 'सर्वभूतस्थितं यो मां भजत्येकत्वमास्थितः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-31', 'en', 'He who, established in unity, worshippeth Me abiding in all beings, that Yogi liveth in Me, whatever his mode of living.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-32', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 32, 'Chapter 6, Verse 32', 'आत्मौपम्येन सर्वत्र समं पश्यति योऽर्जुन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-32', 'en', 'He who, through the likeness of the Self, O Arjuna, seeth equality in everything, whether pleasant or painful, he is considered a perfect Yogî.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-33', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 33, 'Chapter 6, Verse 33', 'योऽयं योगस्त्वया प्रोक्तः साम्येन मधुसूदन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-33', 'en', 'This yoga which Thou hast declared to be by equanimity, O Madhusûdana, I see not a stable foundation for it, owing to restlessness;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-34', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 34, 'Chapter 6, Verse 34', 'चञ्चलं हि मनः कृष्ण प्रमाथि बलवद्दृढम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-34', 'en', 'For the mind is verily restless, O Krishna; it is impetuous, strong and difficult to bend. I deem it as hard to curb as the wind.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-35', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 35, 'Chapter 6, Verse 35', 'असंशयं महाबाहो मनो दुर्निग्रहं चलम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-35', 'en', 'Without doubt, O mighty-armed, the mind is hard to curb and restless; but it may be curbed by constant practice and by dispassion.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-36', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 36, 'Chapter 6, Verse 36', 'असंयतात्मना योगो दुष्प्राप इति मे मतिः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-36', 'en', 'Yoga is hard to attain, methinks, by a self that is uncontrolled; but by the Self-controlled it is attainable by properly directed energy.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-37', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 37, 'Chapter 6, Verse 37', 'अयतिः श्रद्धयोपेतो योगाच्चलितमानसः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-37', 'en', 'He who is unsubdued but who possesseth faith, with the mind wandering away from yoga, failing to attain perfection in yoga, what path doth he tread, O Krishna?', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-38', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 38, 'Chapter 6, Verse 38', 'कच्चिन्नोभयविभ्रष्टश्छिन्नाभ्रमिव नश्यति।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-38', 'en', 'Fallen from both, is he destroyed like a rent cloud, unsteadfast, O mighty-armed, deluded in the path of the Eternal?', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-39', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 39, 'Chapter 6, Verse 39', 'एतन्मे संशयं कृष्ण छेत्तुमर्हस्यशेषतः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-39', 'en', 'Deign, O Krishna, to completely dispel this doubt of mine; for there is none to be found save Thyself able to destroy this doubt.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-40', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 40, 'Chapter 6, Verse 40', 'पार्थ नैवेह नामुत्र विनाशस्तस्य विद्यते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-40', 'en', 'O son of Prithâ, neither in this world nor in the life to come is there destruction for him; never doth any who worketh righteousness, O beloved, tread the path of woe.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-41', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 41, 'Chapter 6, Verse 41', 'प्राप्य पुण्यकृतांल्लोकानुषित्वा शाश्वतीः समाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-41', 'en', 'Having attained to the worlds of the pure-doing, and having dwelt there for immemorial years, he who fell from yoga is reborn in a pure and blessed house;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-42', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 42, 'Chapter 6, Verse 42', 'अथ वा योगिनामेव कुले भवति धीमताम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-42', 'en', 'Or he may even be born into a family of wise Yogîs; but such a birth as that is most difficult to obtain in this world.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-43', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 43, 'Chapter 6, Verse 43', 'तत्र तं बुद्धिसंयोगं लभते पौर्वदेहिकम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-43', 'en', 'There he recovereth the characteristics belonging to this former body, and with these he again laboureth for perfection, O joy of the Kurus.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-44', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 44, 'Chapter 6, Verse 44', 'पूर्वाभ्यासेन तेनैव ह्रियते ह्यवशोऽपि सः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-44', 'en', 'By that former practice he is irresistibly swept away. Only wishing to know yoga, even the seeker after yoga goeth beyond the Brâhmic world;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-45', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 45, 'Chapter 6, Verse 45', 'प्रयत्नाद्यतमानस्तु योगी संशुद्धकिल्बिषः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-45', 'en', 'But the Yogî, labouring with assiduity, purified from sin, fully perfected through manifold births, he reacheth the supreme goal.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-46', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 46, 'Chapter 6, Verse 46', 'तपस्विभ्योऽधिको योगी ज्ञानिभ्योऽपि मतोऽधिकः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-46', 'en', 'The Yogî is greater than the ascetics; he is thought to be greater than even the wise; the Yogî is greater than the men of action; therefore become thou a Yogî, O Arjuna!', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-6-47', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 6), 47, 'Chapter 6, Verse 47', 'योगिनामपि सर्वेषां मद्गतेनान्तरात्मना।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-6-47', 'en', 'And among all Yogîs, he who, full of faith, with the inner Self abiding in Me, adoreth Me, he is considered by Me to be the most completely harmonised.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-1', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 1, 'Chapter 7, Verse 1', 'मय्यासक्तमनाः पार्थ योगं युञ्जन्मदाश्रयः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-1', 'en', 'With the mind clinging to me, O Pârtha, performing yoga, refuged in Me, how thou shalt without doubt know Me to the uttermost, that hear thou.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-2', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 2, 'Chapter 7, Verse 2', 'ज्ञानं तेऽहं सविज्ञानमिदं वक्ष्याम्यशेषतः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-2', 'en', 'I will declare to thee this knowledge and wisdom in its completeness, which, having known, there is nothing more here needeth to be known.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-3', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 3, 'Chapter 7, Verse 3', 'मनुष्याणां सहस्रेषु कश्चिद्यतति सिद्धये।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-3', 'en', 'Among thousands of men scarce one striveth for perfection; of the successful strivers scarce one knoweth Me in essence.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-4', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 4, 'Chapter 7, Verse 4', 'भूमिरापोऽनलो वायुः खं मनो बुद्धिरेव च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-4', 'en', 'Earth, water, fire, air, ether, Mind, and Reason also and Egoism—these are the eightfold division of My nature.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-5', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 5, 'Chapter 7, Verse 5', 'अपरेयमितस्त्वन्यां प्रकृतिं विद्धि मे पराम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-5', 'en', 'This the inferior. Know My other nature, the higher, the life-element, O mighty-armed, by which the universe is upheld.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-6', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 6, 'Chapter 7, Verse 6', 'एतद्योनीनि भूतानि सर्वाणीत्युपधारय।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-6', 'en', 'Know this to be the womb of all beings. I am the source of the forthgoing of the whole universe and likewise the place of its dissolving.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-7', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 7, 'Chapter 7, Verse 7', 'मत्तः परतरं नान्यत्किं चिदस्ति धनंजय।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-7', 'en', 'There is naught whatsoever higher than I, O Dhananjaya. All this is threaded on Me, as rows of pearls on a string.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-8', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 8, 'Chapter 7, Verse 8', 'रसोऽहमप्सु कौन्तेय प्रभास्मि शशिसूर्ययोः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-8', 'en', 'I the sapidity in waters, O son of Kuntî, I the radiance in moon and sun; the Word of Power in all the Vedas, sound in ether, and virility in men;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-9', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 9, 'Chapter 7, Verse 9', 'पुण्यो गन्धः पृथिव्यां च तेजश्चास्मि विभावसौ।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-9', 'en', 'The pure fragrance of earths and the bril- liance in fire am I; the life in all beings am I, and the austerity in ascetics.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-10', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 10, 'Chapter 7, Verse 10', 'बीजं मां सर्वभूतानां विद्धि पार्थ सनातनम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-10', 'en', 'Know Me, O Pârtha! as the eternal seed of all beings. I am the Reason of the Reason-endowed, the splendour of splendid things am I.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-11', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 11, 'Chapter 7, Verse 11', 'बलं बलवतां चाहं कामरागविवर्जितम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-11', 'en', 'And I the strength of the strong, devoid of desire and passion. In beings I am desire not contrary to duty, O Lord of the Bharatas.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-12', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 12, 'Chapter 7, Verse 12', 'ये चैव सात्त्विका भावा राजसास्तामसाश्च ये।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-12', 'en', 'The natures that are harmonious, active, slothful, these know as from Me; not I in them, but they in me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-13', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 13, 'Chapter 7, Verse 13', 'त्रिभिर्गुणमयैर्भावैरेभिः सर्वमिदं जगत्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-13', 'en', 'All this world, deluded by these natures made by the three qualities, knoweth not Me, above these, imperishable.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-14', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 14, 'Chapter 7, Verse 14', 'दैवी ह्येषा गुणमयी मम माया दुरत्यया।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-14', 'en', 'This divine illusion of Mine, caused by the qualities, is hard to pierce; they who come to Me, they cross over this illusion.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-15', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 15, 'Chapter 7, Verse 15', 'न मां दुष्कृतिनो मूढाः प्रपद्यन्ते नराधमाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-15', 'en', 'The evil-doing, the deluded, the vilest men, they come not to Me, they whose wisdom is destroyed by illusion, who have embraced the nature of demons.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-16', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 16, 'Chapter 7, Verse 16', 'चतुर्विधा भजन्ते मां जनाः सुकृतिनोऽर्जुन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-16', 'en', 'Fourfold in division are the righteous ones who worship me, O Arjuna; the suffering, the seeker for knowledge, the self-interested and the wise, O Lord of the Bhâratas.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-17', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 17, 'Chapter 7, Verse 17', 'तेषां ज्ञानी नित्ययुक्त एकभक्तिर्विशिष्यते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-17', 'en', 'Of these the wise, constantly harmonised, worshipping the One, is the best; I am supremely dear to the wise, and he is dear to Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-18', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 18, 'Chapter 7, Verse 18', 'उदाराः सर्व एवैते ज्ञानी त्वात्मैव मे मतम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-18', 'en', 'Noble are all these, but I hold the wise as verily Myself; he, Self united, is fixed on Me, the highest Path.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-19', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 19, 'Chapter 7, Verse 19', 'बहूनां जन्मनामन्ते ज्ञानवान्मां प्रपद्यते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-19', 'en', 'At the close of many births the man full of wisdom cometh unto Me; "Vâsudeva is all." saith he, the Mahâtmâ, very difficult to find.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-20', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 20, 'Chapter 7, Verse 20', 'कामैस्तैस्तैर्हृतज्ञानाः प्रपद्यन्तेऽन्यदेवताः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-20', 'en', 'They whose wisdom hath been rent away by desires go forth to other Shining Ones, resorting to various external observances, according to their own natures.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-21', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 21, 'Chapter 7, Verse 21', 'यो यो यां यां तनुं भक्तः श्रद्धयार्चितुमिच्छति।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-21', 'en', 'Any devotee who seeketh to worship with faith any such aspect, I verily bestow the unswerving faith of that man.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-22', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 22, 'Chapter 7, Verse 22', 'स तया श्रद्धया युक्तस्तस्या राधनमीहते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-22', 'en', 'He endowed with that faith, seeketh the worship of such a one, and from him he obtaineth his desires, I verily decreeing the benefits;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-23', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 23, 'Chapter 7, Verse 23', 'अन्तवत्तु फलं तेषां तद्भवत्यल्पमेधसाम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-23', 'en', 'Finite indeed the fruit that belongeth to those who are of small intelligence. To the Shining Ones go the worshippers of the Shining Ones, but my devotees come unto Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-24', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 24, 'Chapter 7, Verse 24', 'अव्यक्तं व्यक्तिमापन्नं मन्यन्ते मामबुद्धयः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-24', 'en', 'Those devoid of Reason think of Me, the unmanifest, as having manifestation, knowing not My supreme nature, imperishable, most excellent.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-25', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 25, 'Chapter 7, Verse 25', 'नाहं प्रकाशः सर्वस्य योगमायासमावृतः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-25', 'en', 'Nor am I of all discovered, enveloped in My creation-illusion. This deluded world knoweth Me not, the unborn, the imperishable.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-26', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 26, 'Chapter 7, Verse 26', 'वेदाहं समतीतानि वर्तमानानि चार्जुन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-26', 'en', 'I know the beings that are past, that are present, that are to come, O Arjuna, but no one knoweth Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-27', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 27, 'Chapter 7, Verse 27', 'इच्छाद्वेषसमुत्थेन द्वंद्वमोहेन भारत।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-27', 'en', 'By the delusion of the pairs of opposites, sprung from attraction and repulsion, O Bhârata, all beings walk this universe wholly deluded, O Parantapa.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-28', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 28, 'Chapter 7, Verse 28', 'येषां त्वन्तगतं पापं जनानां पुण्यकर्मणाम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-28', 'en', 'But those men of pure deeds, in whom sin is come to an end, they, freed from the delusive pairs of opposites, worship Me, steadfast in vows.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-29', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 29, 'Chapter 7, Verse 29', 'जरामरणमोक्षाय मामाश्रित्य यतन्ति ये।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-29', 'en', 'They who, refuged in Me, strive for liberation from birth and death, they know the Eternal, the whole Self-knowledge, and all action.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-7-30', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 7), 30, 'Chapter 7, Verse 30', 'साधिभूताधिदैवं मां साधियज्ञं च ये विदुः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-7-30', 'en', 'They who know Me as the knowledge of the elements, as that of the Shining Ones, and as that of the Sacrifice, they harmonised in mind, know Me verily even in the time of forthgoing.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-1', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 1, 'Chapter 8, Verse 1', 'किं तद्ब्रह्म किमध्यात्मं किं कर्म पुरुषोत्तम।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-1', 'en', 'What is that Eternal, what Self-knowledge, what Action, O Purushottama? And what is declared to be the knowledge of the Elements, what is called the knowledge of the Shining Ones?', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-2', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 2, 'Chapter 8, Verse 2', 'अधियज्ञः कथं कोऽत्र देहेऽस्मिन्मधुसूदन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-2', 'en', 'What is the knowledge of Sacrifice in this body, and how, O, Madhusûdana? And how, at the time of forthgoing art Thou known by the Self-controlled?', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-3', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 3, 'Chapter 8, Verse 3', 'अक्षरं ब्रह्म परमं स्वभावोऽध्यात्ममुच्यते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-3', 'en', 'The indestructible, the supreme is the Eternal; His essential nature is called Self-knowledge; the emanation that causes the birth of beings is named Action;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-4', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 4, 'Chapter 8, Verse 4', 'अधिभूतं क्षरो भावः पुरुषश्चाधिदैवतम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-4', 'en', 'Knowledge of the Elements concerns My perishable nature, and knowledge of the Shining Ones concerns the life-giving energy; the knowledge of Sacrifice tells of Me, as wearing the body, O best of living beings.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-5', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 5, 'Chapter 8, Verse 5', 'अन्तकाले च मामेव स्मरन्मुक्त्वा कलेवरम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-5', 'en', 'And he who, casting off the body, goeth forth thinking upon Me only at the time of the end, he entereth into My being: there is no doubt of that.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-6', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 6, 'Chapter 8, Verse 6', 'यं यं वापि स्मरन्भावं त्यजत्यन्ते कलेवरम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-6', 'en', 'Whosoever at the end abandoneth the body, thinking upon any being, to that being only he goeth, O Kaunteya, ever to that conformed in nature.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-7', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 7, 'Chapter 8, Verse 7', 'तस्मात्सर्वेषु कालेषु मामनुस्मर युध्य च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-7', 'en', 'Therefore at all times think upon Me only and fight. With mind and Reason set on Me, without doubt thou shalt come to Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-8', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 8, 'Chapter 8, Verse 8', 'अभ्यासयोगयुक्तेन चेतसा नान्यगामिना।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-8', 'en', 'With the mind not wandering after aught else, harmonised by continual practice, constantly meditating, O Pârtha, one goeth to the Spirit supreme, divine.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-9', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 9, 'Chapter 8, Verse 9', 'कविं पुराणमनुशासितारमणोरणीयांसमनुस्मरेद्यः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-9', 'en', 'He who thinketh upon the Ancient, the Omniscient, the All-Ruler, minuter than the minute, the supporter of all, of form unimaginable, refulgent as the sun beyond the darkness,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-10', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 10, 'Chapter 8, Verse 10', 'प्रयाणकाले मनसाचलेन भक्त्या युक्तो योगबलेन चैव।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-10', 'en', 'In the time of forthgoing, with unshaken mind, fixed in devotion, by the power of yoga drawing together his life-breath in the centre of the two eyebrows, he goeth to this Spirit, supreme, divine.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-11', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 11, 'Chapter 8, Verse 11', 'यदक्षरं वेदविदो वदन्ति विशन्ति यद्यतयो वीतरागाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-11', 'en', 'That which is declared indestructible by the Veda-knowers, that which the controlled and passion-free enter, that desiring which Brahmacharya is performed, that path I will declare to thee with brevity.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-12', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 12, 'Chapter 8, Verse 12', 'सर्वद्वाराणि संयम्य मनो हृदि निरुध्य च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-12', 'en', 'All the gates closed, the mind confined in the heart, the life-breath fixed in his own head, concentrated by yoga,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-13', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 13, 'Chapter 8, Verse 13', 'ओमित्येकाक्षरं ब्रह्म व्याहरन्मामनुस्मरन्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-13', 'en', '"Aum!" the one syllabled Eternal, reciting, thinking upon Me, he who goeth forth, abandoning the body, he goeth on the highest path.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-14', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 14, 'Chapter 8, Verse 14', 'अनन्यचेताः सततं यो मां स्मरति नित्यशः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-14', 'en', 'He who constantly thinketh upon Me, not thinking ever of another, of him I am easily reached, O Pârtha, of this ever-harmonised Yogî.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-15', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 15, 'Chapter 8, Verse 15', 'मामुपेत्य पुनर्जन्म दुःखालयमशाश्वतम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-15', 'en', 'Having come to Me, these Mahâtmâs come not again to birth, the place of pain, non-eternal; they have gone to the highest bliss.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-16', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 16, 'Chapter 8, Verse 16', 'आ ब्रह्मभुवनाल्लोकाः पुनरावर्तिनोऽर्जुन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-16', 'en', 'The worlds, beginning with the world of Brahmâ, they come and go, O Arjuna; but he who cometh unto Me, O Kaunteya, he knoweth birth no more.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-17', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 17, 'Chapter 8, Verse 17', 'सहस्रयुगपर्यन्तमहर्यद्ब्रह्मणो विदुः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-17', 'en', 'The people who know the day of Brahmâ, a thousand ages in duration, and the night a thousand ages in ending, they know day and night.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-18', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 18, 'Chapter 8, Verse 18', 'अव्यक्ताद्व्यक्तयः सर्वाः प्रभवन्त्यहरागमे।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-18', 'en', 'From the unmanifested all the manifested stream forth at the coming of day; at the coming of night they dissolve, even in That called the unmanifested.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-19', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 19, 'Chapter 8, Verse 19', 'भूतग्रामः स एवायं भूत्वा भूत्वा प्रलीयते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-19', 'en', 'This multitude of beings, going forth repeatedly, is dissolved at the coming of night: by ordination, O Pârtha, it streams forth at the coming of day.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-20', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 20, 'Chapter 8, Verse 20', 'परस्तस्मात्तु भावोऽन्योऽव्यक्तोऽव्यक्तात्सनातनः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-20', 'en', 'Therefore verily there existeth, higher than that unmanifested, another unmanifested, eternal, which in the destroying of all beings, is not destroyed.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-21', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 21, 'Chapter 8, Verse 21', 'अव्यक्तोऽक्षर इत्युक्तस्तमाहुः परमां गतिम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-21', 'en', 'That unmanifested, "the Indestructible," It is called; It is named the highest Path. They who reach It return not. That is My supreme abode.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-22', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 22, 'Chapter 8, Verse 22', 'पुरुषः स परः पार्थ भक्त्या लभ्यस्त्वनन्यया।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-22', 'en', 'He, the highest Spirit, O Pârtha, may be reached by unswerving devotion to Him alone, in whom all beings abide, by whom all This is pervaded.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-23', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 23, 'Chapter 8, Verse 23', 'यत्र काले त्वनावृत्तिमावृत्तिं चैव योगिनः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-23', 'en', 'That time wherein going forth Yogîs return not, and also that wherein going forth they return, that time shall I declare to thee, O prince of the Bhâratas.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-24', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 24, 'Chapter 8, Verse 24', 'अग्निर्ज्योतिरहः शुक्लः षण्मासा उत्तरायणम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-24', 'en', 'Fire, light, day-time, the bright fortnight, the six months of the northern path—then, going forth, the men who know the Eternal go to the Eternal.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-25', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 25, 'Chapter 8, Verse 25', 'धूमो रात्रिस्तथा कृष्णः षण्मासा दक्षिणायनम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-25', 'en', 'Smoke, night-time, the dark fortnight also, the six months of the southern path—then the Yogî, obtaining the moonlight, returneth.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-26', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 26, 'Chapter 8, Verse 26', 'शुक्लकृष्णे गती ह्येते जगतः शाश्वते मते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-26', 'en', 'Light and darkness, these are thought to be the world''s everlasting paths; by the one he goeth who returneth not, by the other he who returneth again.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-27', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 27, 'Chapter 8, Verse 27', 'नैते सृती पार्थ जानन्योगी मुह्यति कश्चन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-27', 'en', 'Knowing these paths, O Pârtha, the Yogi is nowise perplexed. Therefore in all times be firm in yoga, O Arjuna.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-8-28', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 8), 28, 'Chapter 8, Verse 28', 'वेदेषु यज्ञेषु तपःसु चैव दानेषु यत्पुण्यफलं प्रदिष्टम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-8-28', 'en', 'The fruit of meritorious deeds, attached in the Vedas to sacrifices, to austerities, and also to almsgiving, the Yogî passeth all these by having known this, and goeth to the supreme and ancient Seat.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-1', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 1, 'Chapter 9, Verse 1', 'इदं तु ते गुह्यतमं प्रवक्ष्याम्यनसूयवे।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-1', 'en', 'To thee, the uncarping, verily shall I declare this profoundest Secret, wisdom with knowledge combined, which, having known, thou shalt be freed from evil.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-2', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 2, 'Chapter 9, Verse 2', 'राजविद्या राजगुह्यं पवित्रमिदमुत्तमम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-2', 'en', 'Kingly Science, kingly Secret, supreme Purifier, this; intuitional, according to righteousness, very easy to perform, imperishable.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-3', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 3, 'Chapter 9, Verse 3', 'अश्रद्दधानाः पुरुषा धर्मस्यास्य परंतप।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-3', 'en', 'Men without faith in this knowledge, O Parantapa, not reaching Me, return to the paths of this world of death.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-4', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 4, 'Chapter 9, Verse 4', 'मया ततमिदं सर्वं जगदव्यक्तमूर्तिना।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-4', 'en', 'By Me all this world is pervaded in My unmanifested aspect; all beings have root in Me, I am not rooted in them.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-5', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 5, 'Chapter 9, Verse 5', 'न च मत्स्थानि भूतानि पश्य मे योगमैश्वरम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-5', 'en', 'Nor have beings root in Me; behold My sovereign Yoga! The support of beings, yet not rooted in beings, My Self their efficient cause.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-6', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 6, 'Chapter 9, Verse 6', 'यथाकाशस्थितो नित्यं वायुः सर्वत्रगो महान्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-6', 'en', 'As the mighty air everywhere moving is rooted in the Ether, so all beings rest rooted in Me—thus know thou.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-7', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 7, 'Chapter 9, Verse 7', 'सर्वभूतानि कौन्तेय प्रकृतिं यान्ति मामिकाम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-7', 'en', 'All beings, O Kaunteya, enter my lower nature at the end of a world-age; at the beginning of a world-age again I emanate them.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-8', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 8, 'Chapter 9, Verse 8', 'प्रकृतिं स्वामवष्टभ्य विसृजामि पुनः पुनः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-8', 'en', 'Hidden in Nature, which is mine own, I emanate again and again all this multitude of beings, helpless, by the force of Nature.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-9', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 9, 'Chapter 9, Verse 9', 'न च मां तानि कर्माणि निबध्नन्ति धनंजय।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-9', 'en', 'Nor do these works bind me, O Dhananjaya, enthroned on high unattached to actions.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-10', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 10, 'Chapter 9, Verse 10', 'मयाध्यक्षेण प्रकृतिः सूयते सचराचरम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-10', 'en', 'Under Me as supervisor, Nature sends forth the moving and unmoving: because of this, O Kaunteya, the universe revolves.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-11', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 11, 'Chapter 9, Verse 11', 'अवजानन्ति मां मूढा मानुषीं तनुमाश्रितम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-11', 'en', 'The foolish disregard Me, when clad in human semblance, ignorant of My supreme nature, the great Lord of beings;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-12', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 12, 'Chapter 9, Verse 12', 'मोघाशा मोघकर्माणो मोघज्ञाना विचेतसः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-12', 'en', 'Empty of hope, empty of deeds, empty of wisdom, senseless, partaking of the deceitful, brutal and demoniacal nature.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-13', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 13, 'Chapter 9, Verse 13', 'महात्मानस्तु मां पार्थ दैवीं प्रकृतिमाश्रिताः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-13', 'en', 'Verily the Mahâtmâs, O Partha, partaking of My divine nature, worship with unwavering mind, having known Me, the imperishable source of beings.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-14', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 14, 'Chapter 9, Verse 14', 'सततं कीर्तयन्तो मां यतन्तश्च दृढव्रताः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-14', 'en', 'Always magnifying Me, strenuous, firm in vows, prostrating themselves before Me, they worship Me with devotion ever harmonised.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-15', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 15, 'Chapter 9, Verse 15', 'ज्ञानयज्ञेन चाप्यन्ये यजन्तो मामुपासते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-15', 'en', 'Others also, sacrificing with the sacrifice of wisdom, worship Me as the One and the Manifold everywhere present.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-16', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 16, 'Chapter 9, Verse 16', 'अहं क्रतुरहं यज्ञः स्वधाहमहमौषधम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-16', 'en', 'I the ablation; I the sacrifice; I the ancestral offering; I the fire-giving herb; the mantram I; I also the butter; I the fire; the burnt-offering I;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-17', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 17, 'Chapter 9, Verse 17', 'पिताहमस्य जगतो माता धाता पितामहः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-17', 'en', 'I the Father of this universe, the Mother, the Supporter, the Grandsire, the Holy one to be known, the Word of Power, and also the Rik, Sâma, and Yajur,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-18', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 18, 'Chapter 9, Verse 18', 'गतिर्भर्ता प्रभुः साक्षी निवासः शरणं सुहृत्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-18', 'en', 'The Path, Husband, Lord, Witness, Abode, Shelter, Lover, Origin, Dissolution, Foundation, house, Seed imperishable.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-19', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 19, 'Chapter 9, Verse 19', 'तपाम्यहमहं वर्षं निगृह्णाम्युत्सृजामि च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-19', 'en', 'I give heat; I hold back and send forth the rain; immortality and also death, being and non-being am I, Arjuna.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-20', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 20, 'Chapter 9, Verse 20', 'त्रैविद्या मां सोमपाः पूतपापा यज्ञैरिष्ट्वा स्वर्गतिं प्रार्थयन्ते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-20', 'en', 'The knowers of the three, the Soma-drinkers, the purified from sin, worshipping Me with sacrifice, pray of Me the way to heaven; they, ascending to the holy world of the Ruler of the Shining Ones, eat in heaven the divine feasts of the Shining Ones.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-21', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 21, 'Chapter 9, Verse 21', 'ते तं भुक्त्वा स्वर्गलोकं विशालं क्षीणे पुण्ये मर्त्यलोकं विशन्ति।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-21', 'en', 'They, having enjoyed the spacious heaven-world, their holiness withered, come back to this world of death. Following the virtues enjoined by the three, desiring desires, they obtain the transitory.', 'besant-1922', true);
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-22', 'en', 'To those men who worship Me alone thinking of no other, to those ever harmonious, I bring full security.', 'besant-1922', false);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-23', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 23, 'Chapter 9, Verse 23', 'येऽप्यन्यदेवता भक्ता यजन्ते श्रद्धयान्विताः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-23', 'en', 'Even the devotees of other Shining Ones, who worship full of faith, they also worship Me, O son of Kuntî, though contrary to the ancient rule.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-24', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 24, 'Chapter 9, Verse 24', 'अहं हि सर्वयज्ञानां भोक्ता च प्रभुरेव च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-24', 'en', 'I am indeed the enjoyer of all sacrifices and also the Lord, but they know Me not in Essence, and hence they fall.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-25', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 25, 'Chapter 9, Verse 25', 'यान्ति देवव्रता देवान्पितॄन्यान्ति पितृव्रताः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-25', 'en', 'They who worship the Shining Ones go to the Shining Ones; to the Ancestors go the Ancestor-worshippers; to the Elements go those who sacrifice to Elementals; but My worshippers come unto Me.', 'besant-1922', true);
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-26', 'en', 'He who offereth to Me with devotion a leaf, a flower, a fruit, water, that I accept from the striving self, offered as it is with devotion.', 'besant-1922', false);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-27', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 27, 'Chapter 9, Verse 27', 'यत्करोषि यदश्नासि यज्जुहोषि ददासि यत्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-27', 'en', 'Whatsoever thou doest, whatsoever thou eatest, whatsoever thou offerest, whatsoever thou givest, whatsoever thou doest of austerity, O Kaunteya, do thou that as an offering unto Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-28', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 28, 'Chapter 9, Verse 28', 'शुभाशुभफलैरेवं मोक्ष्यसे कर्मबन्धनैः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-28', 'en', 'Thus shalt thou be liberated from the bonds of action, yielding good and evil fruits; thyself harmonised by the yoga of renunciation, thou shalt come unto Me when set free.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-29', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 29, 'Chapter 9, Verse 29', 'समोऽहं सर्वभूतेषु न मे द्वेष्योऽस्ति न प्रियः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-29', 'en', 'The same am I to all beings; there is none hateful to Me nor dear. They verily who worship Me with devotion, they are in Me, and I also in them.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-30', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 30, 'Chapter 9, Verse 30', 'अपि चेत्सुदुराचारो भजते मामनन्यभाक्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-30', 'en', 'Even if the most sinful worship Me, with un- divided heart, he too must be accounted righteous, for he hath rightly resolved;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-31', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 31, 'Chapter 9, Verse 31', 'क्षिप्रं भवति धर्मात्मा शश्वच्छान्तिं निगच्छति।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-31', 'en', 'Speedily he becometh dutiful and goeth to eternal peace; O Kaunteya, know thou for certain that My devotee perisheth never.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-32', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 32, 'Chapter 9, Verse 32', 'मां हि पार्थ व्यपाश्रित्य येऽपि स्युः पापयोनयः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-32', 'en', 'They who take refuge with Me, O Partha, though of the womb of sin, women, Vaishyas, even Shûdras, they also tread the highest path.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-33', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 33, 'Chapter 9, Verse 33', 'किं पुनर्ब्राह्मणाः पुण्या भक्ता राजर्षयस्तथा।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-33', 'en', 'How much rather then holy Brâhmanas and devoted royal saints; having obtained this transient joyless world, worship thou Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-9-34', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 9), 34, 'Chapter 9, Verse 34', 'मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-9-34', 'en', 'On Me fix thy mind, be devoted to Me; sacrifice to Me; prostrate thyself before Me; harmonised thus in the Self, thou shalt come unto Me, having Me as thy supreme goal.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-1', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 1, 'Chapter 10, Verse 1', 'भूय एव महाबाहो शृणु मे परमं वचः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-1', 'en', 'Again, O mighty-armed, hear thou My supreme word, that, desiring thy welfare, I will declare to thee who art beloved.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-2', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 2, 'Chapter 10, Verse 2', 'न मे विदुः सुरगणाः प्रभवं न महर्षयः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-2', 'en', 'The multitude of the Shining Ones, or the great Rishis, know not my forthcoming, for I am the beginning of all the Shining Ones and the great Rishis.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-3', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 3, 'Chapter 10, Verse 3', 'यो मामजमनादिं च वेत्ति लोकमहेश्वरम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-3', 'en', 'He who knoweth Me, unborn, beginningless, the great Lord of the world, he among mortals without delusion, is liberated from all sin.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-4', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 4, 'Chapter 10, Verse 4', 'बुद्धिर्ज्ञानमसंमोहः क्षमा सत्यं दमः शमः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-4', 'en', 'Reason, wisdom, non-illusion, forgiveness, truth, self-restraint, calmness, pleasure, pain, existence, non-existence, fear, and also courage', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-5', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 5, 'Chapter 10, Verse 5', 'अहिंसा समता तुष्टिस्तपो दानं यशोऽयशः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-5', 'en', 'Harmlessness, equanimity, content, austerity, almsgiving, fame and obloquy are the various characteristics of beings issuing from Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-6', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 6, 'Chapter 10, Verse 6', 'महर्षयः सप्त पूर्वे चत्वारो मनवस्तथा।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-6', 'en', 'The seven great Rishis, the ancient Four, and also the Manus, were born of My nature, and mind; of them this race was generated.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-7', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 7, 'Chapter 10, Verse 7', 'एतां विभूतिं योगं च मम यो वेत्ति तत्त्वतः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-7', 'en', 'He who knows in essence that sovereignty and yoga of Mine, he is harmonised by unfaltering yoga; there is no doubt thereof.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-8', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 8, 'Chapter 10, Verse 8', 'अहं सर्वस्य प्रभवो मत्तः सर्वं प्रवर्तते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-8', 'en', 'I am the Generator of all; all evolves from Me; understanding thus, the wise adore Me in rapt emotion.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-9', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 9, 'Chapter 10, Verse 9', 'मच्चित्ता मद्गतप्राणा बोधयन्तः परस्परम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-9', 'en', 'Mindful of Me, their life hidden in Me, illumining each other, ever conversing about Me, they are content and joyful.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-10', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 10, 'Chapter 10, Verse 10', 'तेषां सततयुक्तानां भजतां प्रीतिपूर्वकम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-10', 'en', 'To these, ever harmonious, worshipping in love, I give the yoga of discrimination by which they come unto Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-11', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 11, 'Chapter 10, Verse 11', 'तेषामेवानुकम्पार्थमहमज्ञानजं तमः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-11', 'en', 'Out of pure compassion for them, dwelling within their Self, I destroy the ignorance-born darkness by the shining lamp of wisdom.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-12', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 12, 'Chapter 10, Verse 12', 'परं ब्रह्म परं धाम पवित्रं परमं भवान्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-12', 'en', 'Thou art the supreme Eternal, the supreme Abode, the supreme Purity, eternal divine man, primeval Deity, unborn, the Lord!', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-13', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 13, 'Chapter 10, Verse 13', 'आहुस्त्वामृषयः सर्वे देवर्षिर्नारदस्तथा।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-13', 'en', 'All the Rishis have thus acclaimed Thee, as also the divine Rishi, Nârada; so Asita, Devala, and Vyâsa; and now Thou Thyself tellest it me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-14', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 14, 'Chapter 10, Verse 14', 'सर्वमेतदृतं मन्ये यन्मां वदसि केशव।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-14', 'en', 'All this I believe true that Thou sayest to me, O Keshava. Thy manifestation, O Blessed Lord, neither Shining Ones nor Dânavas comprehend.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-15', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 15, 'Chapter 10, Verse 15', 'स्वयमेवात्मनात्मानं वेत्थ त्वं पुरुषोत्तम।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-15', 'en', 'Thyself indeed knowest Thyself by Thyself, O Purushottama; Source of beings, Lord of beings, Shining One of Shining Ones, Ruler of the world!', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-16', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 16, 'Chapter 10, Verse 16', 'वक्तुमर्हस्यशेषेण दिव्या ह्यात्मविभूतयः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-16', 'en', 'Deign to tell without reserve of Thine own divine glories, by which glories Thou remainest, pervading these worlds.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-17', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 17, 'Chapter 10, Verse 17', 'कथं विद्यामहं योगिंस्त्वां सदा परिचिन्तयन्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-17', 'en', 'How may I know thee, O Yogi, by constant meditation? In what, in what aspects art Thou to be thought of by me, O blessed Lord?', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-18', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 18, 'Chapter 10, Verse 18', 'विस्तरेणात्मनो योगं विभूतिं च जनार्दन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-18', 'en', 'In detail tell me again of Thy yoga and glory, O Janardana; for me there is never satiety in hearing thy life-giving words.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-19', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 19, 'Chapter 10, Verse 19', 'हन्त ते कथयिष्यामि दिव्या ह्यात्मविभूतयः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-19', 'en', 'Blessed be thou! I will declare to thee My divine glory by its chief characteristics, O best of the Kurus; there is no end to details of Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-20', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 20, 'Chapter 10, Verse 20', 'अहमात्मा गुडाकेश सर्वभूताशयस्थितः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-20', 'en', 'I, O Gudakesha, am the Self, seated in the heart of all beings; I am the beginning, the middle, and also the end of all beings.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-21', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 21, 'Chapter 10, Verse 21', 'आदित्यानामहं विष्णुर्ज्योतिषां रविरंशुमान्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-21', 'en', 'Of the Adityas I am Vishnu; of radiances the glorious sun; I am Marîchi of the Maruts; of the asterisms the Moon am I.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-22', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 22, 'Chapter 10, Verse 22', 'वेदानां सामवेदोऽस्मि देवानामस्मि वासवः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-22', 'en', 'Of the Vedas I am the Sâma-Veda; I am Vâsava of the Shining Ones; and of the senses I am the mind; I am of living beings the intelligence.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-23', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 23, 'Chapter 10, Verse 23', 'रुद्राणां शंकरश्चास्मि वित्तेशो यक्षरक्षसाम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-23', 'en', 'And of the Rudras Shañkara am I; Vittesha of the Yakshas and Râkshasas; and of the Vasus I am Pâvaka; Meru of high mountains am I.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-24', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 24, 'Chapter 10, Verse 24', 'पुरोधसां च मुख्यं मां विद्धि पार्थ बृहस्पतिम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-24', 'en', 'And know Me, O Pârtha, of household priests the chief, Brihaspati: of generals I am Skanda; of lakes I am the ocean.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-25', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 25, 'Chapter 10, Verse 25', 'महर्षीणां भृगुरहं गिरामस्म्येकमक्षरम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-25', 'en', 'Of the great Rishis Bhṛigu; of speech I am the one syllable; of sacrifices I am the sacrifice of silent repetitions; of immovable things the Himâlaya.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-26', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 26, 'Chapter 10, Verse 26', 'अश्वत्थः सर्ववृक्षाणां देवर्षीणां च नारदः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-26', 'en', 'Asvattha of all tree; and of divine Rishis Nârada; of Gandharvas Chitraratha; of the perfected the Muni Kapila.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-27', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 27, 'Chapter 10, Verse 27', 'उच्चैःश्रवसमश्वानां विद्धि माममृतोद्भवम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-27', 'en', 'Uchchaishravas of horses know me, nectar-born; Airâvata of lordly elephants, and of men the Monarch.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-28', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 28, 'Chapter 10, Verse 28', 'आयुधानामहं वज्रं धेनूनामस्मि कामधुक्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-28', 'en', 'Of weapons I am the thunderbolt; of cows I am Kâmadhuk; I am Kandarpa of the progenitors; of serpents Vâsuki am I.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-29', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 29, 'Chapter 10, Verse 29', 'अनन्तश्चास्मि नागानां वरुणो यादसामहम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-29', 'en', 'And I am Ananta of Nâgas, Varuna of sea-dwellers I; and of ancestors Aryaman; Yama of governors am I.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-30', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 30, 'Chapter 10, Verse 30', 'प्रह्लादश्चास्मि दैत्यानां कालः कलयतामहम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-30', 'en', 'And I am Prahlâda of Daityas; of calculators Time am I; and of wild beasts I the imperial beast; and Vainateya of birds.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-31', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 31, 'Chapter 10, Verse 31', 'पवनः पवतामस्मि रामः शस्त्रभृतामहम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-31', 'en', 'Of purifiers I am the wind; Rama of warriors I; and I am Makara of fishes; of streams the Gangâ am I.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-32', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 32, 'Chapter 10, Verse 32', 'सर्गाणामादिरन्तश्च मध्यं चैवाहमर्जुन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-32', 'en', 'Of creations the beginning and the ending, and also the middle am I, O Arjuna. Of sciences the science concerning the Self; the speech of orators I.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-33', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 33, 'Chapter 10, Verse 33', 'अक्षराणामकारोऽस्मि द्वंद्वः सामासिकस्य च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-33', 'en', 'Of letters the letter A I am, and the duality of a compound; I also everlasting Time; I the Supporter, whose face turns everywhere.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-34', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 34, 'Chapter 10, Verse 34', 'मृत्युः सर्वहरश्चाहमुद्भवश्च भविष्यताम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-34', 'en', 'And all-devouring Death am I, and the origin of all to come; and of feminine qualities, fame, prosperity, speech, memory, intelligence, constancy, forgiveness.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-35', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 35, 'Chapter 10, Verse 35', 'बृहत्साम तथा साम्नां गायत्री छन्दसामहम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-35', 'en', 'Of hymns also Brihatsâman; Gâyatrî of metres am I; of months I am Mârgasîrsha; of seasons the flowery.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-36', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 36, 'Chapter 10, Verse 36', 'द्यूतं छलयतामस्मि तेजस्तेजस्विनामहम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-36', 'en', 'I am the gambling of the cheat, and the splendour of splendid things I; I am victory, I am determination, and the truth of the truthful I.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-37', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 37, 'Chapter 10, Verse 37', 'वृष्णीनां वासुदेवोऽस्मि पाण्डवानां धनंजयः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-37', 'en', 'Of the Vṛishnis Vâsudeva am I; of the Pândavas Dhananjaya; of the Sages also I am Vyâsa; of poets Ushanâ the Bard.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-38', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 38, 'Chapter 10, Verse 38', 'दण्डो दमयतामस्मि नीतिरस्मि जिगीषताम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-38', 'en', 'Of rulers I am the sceptre; of those that seek victory I am statesmanship; and of secrets I am also silence; the knowledge of knowers am I.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-39', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 39, 'Chapter 10, Verse 39', 'यच्चापि सर्वभूतानां बीजं तदहमर्जुन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-39', 'en', 'And whatsoever is the seed of all beings, that am I, O Arjuna; nor is there aught, moving or unmoving, that may exist bereft of Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-40', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 40, 'Chapter 10, Verse 40', 'नान्तोऽस्ति मम दिव्यानां विभूतीनां परंतप।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-40', 'en', 'There is no end of My divine powers, O Parantapa. What has been declared is illustrative of My infinite glory.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-41', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 41, 'Chapter 10, Verse 41', 'यद्यद्विभूतिमत्सत्त्वं श्रीमदूर्जितमेव वा।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-41', 'en', 'Whatsoever is glorious, good, beautiful, and mighty, understand thou that to go forth from a fragment of My splendour.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-10-42', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 10), 42, 'Chapter 10, Verse 42', 'अथ वा बहुनैतेन किं ज्ञातेन तवार्जुन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-10-42', 'en', 'But what is the knowledge of all these details to thee, O Arjuna? Having pervaded this whole universe with one fragment of Myself, I remain.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-1', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 1, 'Chapter 11, Verse 1', 'मदनुग्रहाय परमं गुह्यमध्यात्मसंज्ञितम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-1', 'en', 'This word of the supreme Secret concerning the Self, Thou hast spoken out of compassion; by this my delusion is taken away.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-2', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 2, 'Chapter 11, Verse 2', 'भवाप्ययौ हि भूतानां श्रुतौ विस्तरशो मया।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-2', 'en', 'The production and destruction of beings have been heard by me in detail from Thee, O Lotus-eyed, and also Thy imperishable greatness.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-3', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 3, 'Chapter 11, Verse 3', 'एवमेतद्यथात्थ त्वमात्मानं परमेश्वर।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-3', 'en', 'O supreme Lord, even as Thou describest Thyself, O best of beings, I desire to see Thy Form omnipotent.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-4', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 4, 'Chapter 11, Verse 4', 'मन्यसे यदि तच्छक्यं मया द्रष्टुमिति प्रभो।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-4', 'en', 'If Thou thinkest that by me It can be seen, O Lord, Lord of Yoga, then show me Thine imperishable Self.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-5', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 5, 'Chapter 11, Verse 5', 'पश्य मे पार्थ रूपाणि शतशोऽथ सहस्रशः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-5', 'en', 'Behold, O Pârtha, a Form of Me, a hundredfold, a thousandfold, various in kind, divine, various in colours and shapes.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-6', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 6, 'Chapter 11, Verse 6', 'पश्यादित्यान्वसून्रुद्रानश्विनौ मरुतस्तथा।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-6', 'en', 'Behold the Âdityas, the Vasus, the Rudras, the two Ashvins and also the Maruts; behold many marvels never seen ere this, O Bhârata.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-7', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 7, 'Chapter 11, Verse 7', 'इहैकस्थं जगत्कृत्स्नं पश्याद्य सचराचरम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-7', 'en', 'Here, to-day, behold the whole universe, movable and immovable, standing in one in My body, O Gudâkesha, with aught else thou desirest to see.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-8', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 8, 'Chapter 11, Verse 8', 'न तु मां शक्यसे द्रष्टुमनेनैव स्वचक्षुषा।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-8', 'en', 'But verily thou art not able to behold Me with these thine eyes; the divine eye I give unto thee. Behold My sovereign Yoga.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-9', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 9, 'Chapter 11, Verse 9', 'एवमुक्त्वा ततो राजन्महायोगेश्वरो हरिः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-9', 'en', 'Having thus spoken, O King, the great Lord of Yoga, Hari, showed to Pârtha His supreme Form as Lord.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-10', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 10, 'Chapter 11, Verse 10', 'अनेकवक्त्रनयनमनेकाद्भुतदर्शनम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-10', 'en', 'With many mouths and eyes, with many visions of marvel, with many divine ornaments, with many upraised divine weapons;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-11', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 11, 'Chapter 11, Verse 11', 'दिव्यमाल्याम्बरधरं दिव्यगन्धानुलेपनम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-11', 'en', 'Wearing divine necklaces and vestures, anointed with divine unguents, the God all-marvellous, boundless, with face turned everywhere.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-12', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 12, 'Chapter 11, Verse 12', 'दिवि सूर्यसहस्रस्य भवेद्युगपदुत्थिता।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-12', 'en', 'If the splendour of a thousand suns were to blaze out together in the sky, that might resemble the glory of that Mahâtman.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-13', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 13, 'Chapter 11, Verse 13', 'तत्रैकस्थं जगत्कृत्स्नं प्रविभक्तमनेकधा।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-13', 'en', 'There Pândava beheld the whole universe, divided into manifold parts, standing in one in the body of the Deity of Deities.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-14', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 14, 'Chapter 11, Verse 14', 'ततः स विस्मयाविष्टो हृष्टरोमा धनंजयः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-14', 'en', 'Then he, Dhananjaya, overwhelmed with astonishment, his hair upstanding, bowed down his head to the Shining One, and with joined palms spake.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-15', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 15, 'Chapter 11, Verse 15', 'पश्यामि देवांस्तव देव देहे सर्वांस्तथा भूतविशेषसंघान्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-15', 'en', 'Within Thy Form, O God, the Gods I see, All grades of beings with distinctive marks; Brahma, the Lord, upon His lotus-throne, The Rishis all, and Serpents, the Divine.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-16', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 16, 'Chapter 11, Verse 16', 'अनेकबाहूदरवक्त्रनेत्रं पश्यामि त्वा सर्वतोऽनन्तरूपम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-16', 'en', 'With mouths, eyes, arms, breasts multitudinous, I see Thee everywhere, unbounded Form. Beginning, middle, end, nor source of Thee, Infinite Lord, infinite Form, I find;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-17', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 17, 'Chapter 11, Verse 17', 'किरीटिनं गदिनं चक्रिणं च तेजोराशिं सर्वतो दीप्तिमन्तम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-17', 'en', 'Shining, a mass of splendour everywhere, With discus, mace, tiara, I behold: Blazing as fire, as sun dazzling the gaze, From all sides in the sky, immeasurable.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-18', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 18, 'Chapter 11, Verse 18', 'त्वमक्षरं परमं वेदितव्यं त्वमस्य विश्वस्य परं निधानम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-18', 'en', 'Lofty beyond all thought, unperishing, Thou treasure-house supreme, all-immanent; Eternal Dharma''s changeless Guardian, Thou; As immemorial Man I think of Thee.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-19', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 19, 'Chapter 11, Verse 19', 'अनादिमध्यान्तमनन्तवीर्यमनन्तबाहुं शशिसूर्यनेत्रम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-19', 'en', 'Nor source, nor midst, nor end; infinite force, Unnumbered arms, the sun and moon Thine eyes I see Thy face, as sacrificial fire Blazing, its splendour burneth up the worlds.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-20', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 20, 'Chapter 11, Verse 20', 'द्यावापृथिव्योरिदमन्तरं हि व्याप्तं त्वयैकेन दिशश्च सर्वाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-20', 'en', 'By Thee alone are filled the earth, the heavens, And all the regions that are stretched between; The triple worlds sink down, O mighty One, Before Thine awful manifested Form.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-21', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 21, 'Chapter 11, Verse 21', 'अमी हि त्वा सुरसंघा विशन्ति के चिद्भीताः प्राञ्जलयो गृणन्ति।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-21', 'en', 'To Thee the troops of Suras enter in, Some with joined palms in awe invoking Thee; Banded Maharshis, Siddhas, cry: "All hail"! Chanting Thy praises with resounding songs.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-22', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 22, 'Chapter 11, Verse 22', 'रुद्रादित्या वसवो ये च साध्या विश्वेऽश्विनौ मरुतश्चोष्मपाश्च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-22', 'en', 'Rudras, Vasus, Sâdhyas and Adityas, Vishvas, the Ashvins, Maruts, Ushmapas, Gandharvas, Yakshas, Siddhas, Asuras, In wondering multitudes beholding Thee.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-23', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 23, 'Chapter 11, Verse 23', 'रूपं महत्ते बहुवक्त्रनेत्रं महाबाहो बहुबाहूरुपादम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-23', 'en', 'Thy mighty Form, with many mouths and eyes, Long armed, with thighs and feet innumerate, Vast-bosomed, set with many fearful teeth, The worlds see terror-struck, as also I.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-24', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 24, 'Chapter 11, Verse 24', 'नभःस्पृशं दीप्तमनेकवर्णं व्यात्ताननं दीप्तविशालनेत्रम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-24', 'en', 'Radiant, Thou touchest heaven, rainbow-hued, With opened mouths and shining vast-orbed eyes. My inmost self is quaking, having seen, My strength is withered, Vishnu, and my peace.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-25', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 25, 'Chapter 11, Verse 25', 'दंष्ट्राकरालानि च ते मुखानि दृष्ट्वैव कालानलसंनिभानि।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-25', 'en', 'Like Time''s destroying flames I see Thy teeth, Upstanding, spread within expanded jaws; Nought know I anywhere, no shelter find; Mercy, O God! refuge of all the worlds!', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-26', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 26, 'Chapter 11, Verse 26', 'अमी च त्वां धृतराष्ट्रस्य पुत्राः सर्वे सहैवावनिपालसंघैः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-26', 'en', 'The sons of Dhṛitarâshtra, and with them The multitude of all these kings of earth, Bhîshma, and Drona, Sûta''s royal son, And all the noblest warriors of our hosts,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-27', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 27, 'Chapter 11, Verse 27', 'वक्त्राणि ते त्वरमाणा विशन्ति दंष्ट्राकरालानि भयानकानि।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-27', 'en', 'Into Thy gaping mouths they hurrying rush, Tremendous-toothed and terrible to see; Some caught within the gaps between Thy teeth Are seen, their heads to powder crushed and ground.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-28', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 28, 'Chapter 11, Verse 28', 'यथा नदीनां बहवोऽम्बुवेगाः समुद्रमेवाभिमुखा द्रवन्ति।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-28', 'en', 'As river-floods impetuously rush, Hurling their waters into ocean''s lap, So fling themselves into Thy flaming mouths, In haste, these mighty men, these lords of earth.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-29', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 29, 'Chapter 11, Verse 29', 'यथा प्रदीप्तं ज्वलनं पतंगा विशन्ति नाशाय समृद्धवेगाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-29', 'en', 'As moths with quickened speed will headlong fly Into a flaming light, to fall destroyed, So also these, in haste precipitate, Enter within Thy mouths destroyed to fall.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-30', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 30, 'Chapter 11, Verse 30', 'लेलिह्यसे ग्रसमानः समन्ताल्लोकान्समग्रान्वदनैर्ज्वलद्भिः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-30', 'en', 'On every side, all-swallowing, fiery-tongued, Thou lickest up mankind, devouring all; The glory filleth space: the universe Is burning, Vishnu, with Thy blazing rays.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-31', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 31, 'Chapter 11, Verse 31', 'आख्याहि मे को भवानुग्ररूपो नमोऽस्तु ते देववर प्रसीद।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-31', 'en', 'Reveal Thy Self; what awful Form art Thou? I worship Thee! Have mercy, God supreme! Thine inner Being I am fain to know; This Thy forth-streaming Life bewilders me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-32', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 32, 'Chapter 11, Verse 32', 'कालोऽस्मि लोकक्षयकृत्प्रवृद्धो लोकान्समाहर्तुमिह प्रवृत्तः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-32', 'en', 'Time am I, laying desolate the world, Made manifest on earth to slay mankind! Not one of all these warriors ranged for strife Escapeth death; thou shalt alone survive.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-33', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 33, 'Chapter 11, Verse 33', 'तस्मात्त्वमुत्तिष्ठ यशो लभस्व जित्वा शत्रून्भुङ्क्ष्व राज्यं समृद्धम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-33', 'en', 'Therefore stand up! win for thyself renown, Conquer thy foes, enjoy the wealth filled realm, By Me they are already overcome, Be thou the outward cause, left-handed one.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-34', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 34, 'Chapter 11, Verse 34', 'द्रोणं च भीष्मं च जयद्रथं च कर्णं तथान्यानपि योधवीरान्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-34', 'en', 'Drona and Bhîshma and Jayadratha, Karna, and all the other warriors here, Are slain by Me. Destroy them fearlessly. Fight! thou shalt crush thy rivals in the field.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-35', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 35, 'Chapter 11, Verse 35', 'एतच्छ्रुत्वा वचनं केशवस्य कृताञ्जलिर्वेपमानः किरीटी।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-35', 'en', 'Having heard these words of Keshava, he who weareth a diadem, with joined palms, quaking and prostrating himself, spake again to Krishna, stammering with fear, casting down his face.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-36', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 36, 'Chapter 11, Verse 36', 'स्थाने हृषीकेश तव प्रकीर्त्या जगत्प्रहृष्यत्यनुरज्यते च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-36', 'en', 'Hrishîkesha! in Thy magnificence Rightly the world rejoiceth, hymning Thee; The Râkshasas to every quarter fly In fear; the hosts of Siddhas prostrate fall.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-37', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 37, 'Chapter 11, Verse 37', 'कस्माच्च ते न नमेरन्महात्मन्गरीयसे ब्रह्मणोऽप्यादिकर्त्रे।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-37', 'en', 'How should they otherwise, O loftiest Self! First Cause! Brahmâ Himself less great than Thou. Infinite, God of Gods, home of all worlds, Unperishing, Sat, Asat, That supreme!', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-38', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 38, 'Chapter 11, Verse 38', 'त्वमादिदेवः पुरुषः पुराणस्त्वमस्य विश्वस्य परं निधानम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-38', 'en', 'First of the Gods, most ancient Man Thou art. Supreme receptacle of all that lives; Knower and known, the dwelling-place on high; In Thy vast Form the universe is spread.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-39', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 39, 'Chapter 11, Verse 39', 'वायुर्यमोऽग्निर्वरुणः शशाङ्कः प्रजापतिस्त्वं प्रपितामहश्च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-39', 'en', 'Thou art Vâyu and Yama, Agni, moon, Varuna, Father, Grandsire of all; Hail, hail to Thee! a thousand times all hail! Hail unto Thee! again, again all hail!', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-40', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 40, 'Chapter 11, Verse 40', 'नमः पुरस्तादथ पृष्ठतस्ते नमोऽस्तु ते सर्वत एव सर्व।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-40', 'en', 'Prostrate in front of Thee, prostrate behind; Prostrate on every side to Thee, O All. In power boundless, measureless in strength, Thou holdest all: then Thou Thyself art All.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-41', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 41, 'Chapter 11, Verse 41', 'सखेति मत्वा प्रसभं यदुक्तं हे कृष्ण हे यादव हे सखेति।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-41', 'en', 'If, thinking Thee but friend, importunate, O Krishna! or O Yâdava! O friend! I cried, unknowing of Thy majesty, And careless in the fondness of my love;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-42', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 42, 'Chapter 11, Verse 42', 'यच्चावहासार्थमसत्कृतोऽसि विहारशय्यासनभोजनेषु।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-42', 'en', 'If jesting I irreverence showed to Thee, At play, reposing, sitting or at meals, Alone, O sinless One, or with my friends, Forgive my error, O Thou boundless One.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-43', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 43, 'Chapter 11, Verse 43', 'पितासि लोकस्य चराचरस्य त्वमस्य पूज्यश्च गुरुर्गरीयान्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-43', 'en', 'Father of worlds, of all that moves and stands, Worthier of reverence than the Guru''s self, There is none like to Thee. Who passeth Thee? Pre-eminent Thy power in all the worlds.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-44', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 44, 'Chapter 11, Verse 44', 'तस्मात्प्रणम्य प्रणिधाय कायं प्रसादये त्वामहमीशमीड्यम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-44', 'en', 'Therefore I fall before Thee; with my body I worship as it fitting; bless Thou me. As father with the son, as friend with friend, With the beloved as lover, bear with me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-45', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 45, 'Chapter 11, Verse 45', 'अदृष्टपूर्वं हृषितोऽस्मि दृष्ट्वा भयेन च प्रव्यथितं मनो मे।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-45', 'en', 'I have seen that which none hath seen before, My heart is glad, yet faileth me for fear; Show me, O God, Thine other Form again— Mercy, O God of Gods, home of all worlds—', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-46', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 46, 'Chapter 11, Verse 46', 'किरीटिनं गदिनं चक्रहस्तमिच्छामि त्वां द्रष्टुमहं तथैव।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-46', 'en', 'Diademed, mace and discus in Thy hand. Again I fain would see Thee as before; Put on again Thy four-armed shape, O Lord, O thousand-armed, of forms innumerate.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-47', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 47, 'Chapter 11, Verse 47', 'मया प्रसन्नेन तवार्जुनेदं रूपं परं दर्शितमात्मयोगात्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-47', 'en', 'Arjuna, by My favour thou hast seen, This loftiest Form by yoga''s self revealed! Radiant, all-penetrating, endless, first, That none except thyself hath ever seen.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-48', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 48, 'Chapter 11, Verse 48', 'न वेदयज्ञाध्ययनैर्न दानैर्न च क्रियाभिर्न तपोभिरुग्रैः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-48', 'en', 'Nor sacrifice, nor Vedas, alms, nor works, Nor sharp austerity, nor study deep, Can win the vision of this Form for man, Foremost of Kurus, thou alone hast seen.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-49', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 49, 'Chapter 11, Verse 49', 'मा ते व्यथा मा च विमूढभावो दृष्ट्वा रूपं घोरमीदृङ्ममेदम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-49', 'en', 'Be not bewildered, be thou not afraid, Because thou hast beheld this awful Form; Cast fear away, and let thy heart rejoice; Behold again Mine own familiar shape.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-50', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 50, 'Chapter 11, Verse 50', 'इत्यर्जुनं वासुदेवस्तथोक्त्वा स्वकं रूपं दर्शयामास भूयः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-50', 'en', 'Vâsudeva, having thus spoken to Arjuna, again manifested His own Form, and consoled the terrified one, the Mahâtman again assuming a gentle form.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-51', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 51, 'Chapter 11, Verse 51', 'दृष्ट्वेदं मानुषं रूपं तव सौम्यं जनार्दन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-51', 'en', 'Beholding again Thy gentle human Form, O Janârdana, I am now collected, and am restored to my own nature.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-52', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 52, 'Chapter 11, Verse 52', 'सुदुर्दर्शमिदं रूपं दृष्टवानसि यन्मम।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-52', 'en', 'This Form of Mine beholden by thee is very hard to see. Verily the Shining Ones ever long to behold this form.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-53', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 53, 'Chapter 11, Verse 53', 'नाहं वेदैर्न तपसा न दानेन न चेज्यया।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-53', 'en', 'Nor can I be seen as thou hast seen Me by the Vedas, nor by austerities, nor by alms, or by offerings;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-54', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 54, 'Chapter 11, Verse 54', 'भक्त्या त्वनन्यया शक्य अहमेवंविधोऽर्जुन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-54', 'en', 'But by devotion to Me alone I may thus be perceived, Arjuna, and known and seen in essence, and entered, O Parantapa.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-11-55', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 11), 55, 'Chapter 11, Verse 55', 'मत्कर्मकृन्मत्परमो मद्भक्तः सङ्गवर्जितः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-11-55', 'en', 'He who doeth actions for Me, whose supreme good I am, My devotee, freed from attachment without hatred of any being, he cometh unto Me, O Pândava.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-12-1', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 12), 1, 'Chapter 12, Verse 1', 'एवं सततयुक्ता ये भक्तास्त्वां पर्युपासते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-12-1', 'en', 'Those devotees who ever harmonised worship Thee, and those also who worship the Indestructible, the Unmanifested, whether of these is the more learned in yoga?', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-12-2', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 12), 2, 'Chapter 12, Verse 2', 'मय्यावेश्य मनो ये मां नित्ययुक्ता उपासते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-12-2', 'en', 'They who with mind fixed on Me ever harmonised worship Me, with faith supreme endowed, these, in My opinion, are best in yoga.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-12-3', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 12), 3, 'Chapter 12, Verse 3', 'ये त्वक्षरमनिर्देश्यमव्यक्तं पर्युपासते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-12-3', 'en', 'They who worship the Indestructible, the Ineffable, the unmanifested, Omnipresent, and Unthinkable, the Unchanging, Immutable, Eternal,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-12-4', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 12), 4, 'Chapter 12, Verse 4', 'संनियम्येन्द्रियग्रामं सर्वत्र समबुद्धयः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-12-4', 'en', 'Restraining and subduing the senses, regarding everything equally, in the welfare of all rejoicing, these also come unto Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-12-5', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 12), 5, 'Chapter 12, Verse 5', 'क्लेशोऽधिकतरस्तेषामव्यक्तासक्तचेतसाम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-12-5', 'en', 'The difficulty of those whose minds are set on the Unmanifested is greater; for the path of the Unmanifested is hard for the embodied to reach.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-12-6', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 12), 6, 'Chapter 12, Verse 6', 'ये तु सर्वाणि कर्माणि मयि संन्यस्य मत्पराः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-12-6', 'en', 'Those verily who, renouncing all actions in Me and intent on Me, worship meditating on Me, with whole-hearted yoga,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-12-7', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 12), 7, 'Chapter 12, Verse 7', 'तेषामहं समुद्धर्ता मृत्युसंसारसागरात्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-12-7', 'en', 'These I speedily lift up from the ocean of death and existence, O Pârtha, their minds being fixed on Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-12-8', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 12), 8, 'Chapter 12, Verse 8', 'मय्येव मन आधत्स्व मयि बुद्धिं निवेशय।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-12-8', 'en', 'Place thy mind in me, into Me let thy Reason enter; then without doubt thou shalt abide in Me hereafter.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-12-9', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 12), 9, 'Chapter 12, Verse 9', 'अथ चित्तं समाधातुं न शक्नोषि मयि स्थिरम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-12-9', 'en', 'And if thou art not able firmly to fix thy mind on Me, then by the yoga of practice seek to reach Me, O Dhananjaya.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-12-10', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 12), 10, 'Chapter 12, Verse 10', 'अभ्यासेऽप्यसमर्थोऽसि मत्कर्मपरमो भव।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-12-10', 'en', 'If also thou art not equal to constant practice, be intent on My service; performing actions for My sake, thou shalt attain perfection.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-12-11', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 12), 11, 'Chapter 12, Verse 11', 'अथैतदप्यशक्तोऽसि कर्तुं मद्योगमाश्रितः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-12-11', 'en', 'If even to do this thou hast not strength, then, taking refuge in union with Me, renounce all fruit of action with the self controlled.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-12-12', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 12), 12, 'Chapter 12, Verse 12', 'श्रेयो हि ज्ञानमभ्यासाज्ज्ञानाद्ध्यानं विशिष्यते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-12-12', 'en', 'Better indeed is wisdom than constant-practice; than wisdom, meditation is better; than meditation, renunciation of the fruit of action; on renunciation follows peace.', 'besant-1922', true);
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-12-13', 'en', 'He who beareth no ill-will to any being, friendly and compassionate, without attachment and egoism, balanced in pleasure and pain, and forgiving,', 'besant-1922', false);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-12-14', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 12), 14, 'Chapter 12, Verse 14', 'संतुष्टः सततं योगी यतात्मा दृढनिश्चयः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-12-14', 'en', 'Ever content, harmonious, with the self-controlled, resolute, with mind and Reason dedicated to Me, he, My devotee, is dear to Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-12-15', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 12), 15, 'Chapter 12, Verse 15', 'यस्मान्नोद्विजते लोको लोकान्नोद्विजते च यः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-12-15', 'en', 'He from whom the world doth not shrink away, who doth not shrink away from the world, freed from the anxieties of joy, anger, and fear, he is dear to me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-12-16', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 12), 16, 'Chapter 12, Verse 16', 'अनपेक्षः शुचिर्दक्ष उदासीनो गतव्यथः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-12-16', 'en', 'He who wants nothing, is pure, expert, passionless, untroubled, renouncing every undertaking, he, My devotee, is dear to Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-12-17', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 12), 17, 'Chapter 12, Verse 17', 'यो न हृष्यति न द्वेष्टि न शोचति न काङ्क्षति।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-12-17', 'en', 'He who neither loveth nor hateth, nor grieveth, nor desireth, renouncing good and evil, full of devotion, he is dear to Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-12-18', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 12), 18, 'Chapter 12, Verse 18', 'समः शत्रौ च मित्रे च तथा मानावमानयोः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-12-18', 'en', 'Alike to foe and friend, and also in fame and ignominy, alike in cold and heat, pleasures and pains, destitute of attachment,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-12-19', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 12), 19, 'Chapter 12, Verse 19', 'तुल्यनिन्दास्तुतिर्मौनी संतुष्टो येन केन चित्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-12-19', 'en', 'Taking equally praise and reproach, silent, wholly content with what cometh, homeless, firm in mind, full of devotion, that man is dear to Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-12-20', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 12), 20, 'Chapter 12, Verse 20', 'ये तु धर्म्यामृतमिदं यथोक्तं पर्युपासते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-12-20', 'en', 'They verily who partake of this life-giving wisdom as taught herein, endued with faith, I their supreme Object, devotees, they are surpassingly dear to Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-1', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 1, 'Chapter 13, Verse 1', 'इदं शरीरं कौन्तेय क्षेत्रमित्यभिधीयते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-1', 'en', 'This body, son of Kuntî, is called the Field; that which knoweth it is called the Knower of the Field by the Sages.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-2', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 2, 'Chapter 13, Verse 2', 'क्षेत्रज्ञं चापि मां विद्धि सर्वक्षेत्रेषु भारत।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-2', 'en', 'Understand Me as the Knower of the Field in all Fields, O Bhârata. Wisdom as to the Field and the Knower of the Field, that in My opinion is the wisdom.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-3', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 3, 'Chapter 13, Verse 3', 'तत्क्षेत्रं यच्च यादृक्च यद्विकारि यतश्च यत्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-3', 'en', 'What that Field is and of what nature, how modified, and whence it is, and what He is and what His powers, hear that now briefly from Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-4', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 4, 'Chapter 13, Verse 4', 'ऋषिभिर्बहुधा गीतं छन्दोभिर्विविधैः पृथक्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-4', 'en', 'Rishis have sung in manifold ways, in many various chants, and in decisive Brahma-sûtra verses full of reasonings.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-5', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 5, 'Chapter 13, Verse 5', 'महाभूतान्यहंकारो बुद्धिरव्यक्तमेव च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-5', 'en', 'The great Elements, Individuality, Reason, and also the unmanifested, the ten senses and the one, and the five pastures of the senses;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-6', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 6, 'Chapter 13, Verse 6', 'इच्छा द्वेषः सुखं दुःखं संघातश्चेतना धृतिः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-6', 'en', 'Desire, aversion, pleasure, pain, combination, intelligence, firmness; these, briefly described, constitute the Field and its modifications.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-7', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 7, 'Chapter 13, Verse 7', 'अमानित्वमदम्भित्वमहिंसा क्षान्तिरार्जवम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-7', 'en', 'Humility, unpretentiousness, harmlessness, forgiveness, rectitude, service of the teacher, purity, steadfastness, self-control.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-8', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 8, 'Chapter 13, Verse 8', 'इन्द्रियार्थेषु वैराग्यमनहंकार एव च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-8', 'en', 'Dispassion towards the objects of the senses, and also absence of egoism, insight into the pain and evil of birth, death, old age and sickness,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-9', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 9, 'Chapter 13, Verse 9', 'असक्तिरनभिष्वङ्गः पुत्रदारगृहादिषु।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-9', 'en', 'Unattachment, absence of self-identification with son, wife or home, and constant balance of mind in wished-for and unwished-for events,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-10', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 10, 'Chapter 13, Verse 10', 'मयि चानन्ययोगेन भक्तिरव्यभिचारिणी।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-10', 'en', 'Unflinching devotion to Me by yoga, without other objects, resort to sequestered places, absence of enjoyment in the company of men,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-11', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 11, 'Chapter 13, Verse 11', 'अध्यात्मज्ञाननित्यत्वं तत्त्वज्ञानार्थदर्शनम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-11', 'en', 'Constancy in the wisdom of the Self, understanding of the object of essential wisdom; that is declared to be the Wisdom; all against it is ignorance.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-12', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 12, 'Chapter 13, Verse 12', 'ज्ञेयं यत्तत्प्रवक्ष्यामि यज्ज्ञात्वामृतमश्नुते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-12', 'en', 'I will declare that which ought to be known, that which being known immortality is enjoyed—the beginningless supreme Eternal, called neither being nor non-being.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-13', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 13, 'Chapter 13, Verse 13', 'सर्वतःपाणिपादं तत्सर्वतोक्षिशिरोमुखम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-13', 'en', 'Everywhere That hath hands and feet, everywhere eyes, heads, and mouths; all-hearing, He dwelleth in the world, enveloping all,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-14', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 14, 'Chapter 13, Verse 14', 'सर्वेन्द्रियगुणाभासं सर्वेन्द्रियविवर्जितम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-14', 'en', 'Shining with all sense-faculties without any senses; unattached supporting everything and free from qualities enjoying qualities;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-15', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 15, 'Chapter 13, Verse 15', 'बहिरन्तश्च भूतानामचरं चरमेव च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-15', 'en', 'Without and within all beings, immovable and also movable; by reason of His subtlety imperceptible; at hand and far away is That.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-16', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 16, 'Chapter 13, Verse 16', 'अविभक्तं च भूतेषु विभक्तमिव च स्थितम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-16', 'en', 'Not divided amid beings, and yet seated distributively; that is to be known as the supporter of beings; He devours and He generates.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-17', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 17, 'Chapter 13, Verse 17', 'ज्योतिषामपि तज्ज्योतिस्तमसः परमुच्यते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-17', 'en', 'That, the Light of all lights, is said to be beyond darkness; Wisdom, the Object of Wisdom, by Wisdom to be reached, seated in the hearts of all.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-18', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 18, 'Chapter 13, Verse 18', 'इति क्षेत्रं तथा ज्ञानं ज्ञेयं चोक्तं समासतः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-18', 'en', 'Thus the Field, Wisdom and the Object of Wisdom, have been briefly told. My devotee, thus knowing, enters into My Being.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-19', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 19, 'Chapter 13, Verse 19', 'प्रकृतिं पुरुषं चैव विद्ध्यनादी उभावपि।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-19', 'en', 'Know thou that Matter and Spirit are both without beginning; and know thou also that modifications and qualities are all Matter-born.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-20', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 20, 'Chapter 13, Verse 20', 'कार्यकारणकर्तृत्वे हेतुः प्रकृतिरुच्यते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-20', 'en', 'Matter is called the cause of the generation of causes and effects; Spirit is called the cause of the enjoyment of pleasure and pain.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-21', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 21, 'Chapter 13, Verse 21', 'पुरुषः प्रकृतिस्थो हि भुङ्क्ते प्रकृतिजान्गुणान्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-21', 'en', 'Spirit seated in Matter useth the qualities born of Matter; attachment to the qualities is the cause of his births in good and evil wombs.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-22', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 22, 'Chapter 13, Verse 22', 'उपद्रष्टानुमन्ता च भर्ता भोक्ता महेश्वरः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-22', 'en', 'Supervisor and permitter, supporter, enjoyer, the great Lord, and also the supreme Self; thus is styled in this body the supreme Spirit.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-23', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 23, 'Chapter 13, Verse 23', 'य एवं वेत्ति पुरुषं प्रकृतिं च गुणैः सह।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-23', 'en', 'He who thus knoweth Spirit and Matter with its qualities, in whatsoever condition he may be, he shall not be born again.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-24', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 24, 'Chapter 13, Verse 24', 'ध्यानेनात्मनि पश्यन्ति के चिदात्मानमात्मना।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-24', 'en', 'Some by meditation behold the Self in the self by the Self; others by the Sânkhya Yoga, and others by the Yoga of Action;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-25', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 25, 'Chapter 13, Verse 25', 'अन्ये त्वेवमजानन्तः श्रुत्वान्येभ्य उपासते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-25', 'en', 'Others also, ignorant of this, having heard of it from others, worship; and these also cross beyond death, adhering to what they had heard.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-26', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 26, 'Chapter 13, Verse 26', 'यावत्संजायते किं चित्सत्त्वं स्थावरजङ्गमम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-26', 'en', 'Whatsoever creature is born immobile or mobile, know thou, O best of the Bhâratas, that it is from the union between the Field and the Knower of the Field.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-27', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 27, 'Chapter 13, Verse 27', 'समं सर्वेषु भूतेषु तिष्ठन्तं परमेश्वरम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-27', 'en', 'Seated equally in all beings, the supreme Lord, unperishing within the perishing—he who thus seeth, he seeth.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-28', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 28, 'Chapter 13, Verse 28', 'समं पश्यन्हि सर्वत्र समवस्थितमीश्वरम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-28', 'en', 'Seeing indeed everywhere the same Lord equally dwelling, he doth not destroy the Self, and thus treads the highest Path.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-29', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 29, 'Chapter 13, Verse 29', 'प्रकृत्यैव च कर्माणि क्रियमाणानि सर्वशः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-29', 'en', 'He who seeth that Matter verily performeth all actions, and that the Self is actionless, he seeth.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-30', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 30, 'Chapter 13, Verse 30', 'यदा भूतपृथग्भावमेकस्थमनुपश्यति।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-30', 'en', 'When he perceiveth the diversified existence of beings as rooted in One, and spreading forth from it, then he reacheth the Eternal', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-31', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 31, 'Chapter 13, Verse 31', 'अनादित्वान्निर्गुणत्वात्परमात्मायमव्ययः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-31', 'en', 'Being beginningless and without qualities, the imperishable supreme Self, though seated in the body, O Kaunteya, worketh not nor is affected.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-32', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 32, 'Chapter 13, Verse 32', 'यथा सर्वगतं सौक्ष्म्यादाकाशं नोपलिप्यते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-32', 'en', 'As the omnipresent ether is not affected, by reason of its subtlety, so seated everywhere in the body the Self is not affected.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-33', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 33, 'Chapter 13, Verse 33', 'यथा प्रकाशयत्येकः कृत्स्नं लोकमिमं रविः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-33', 'en', 'As the one sun illumineth the whole earth, so the Lord of the Field illumineth the whole Field, O Bhârata.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-13-34', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 13), 34, 'Chapter 13, Verse 34', 'क्षेत्रक्षेत्रज्ञयोरेवमन्तरं ज्ञानचक्षुषा।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-13-34', 'en', 'They who by the eyes of Wisdom perceive this difference between the Field and the Knower of the Field, and the liberation of beings from Matter they go to the Supreme.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-1', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 1, 'Chapter 14, Verse 1', 'परं भूयः प्रवक्ष्यामि ज्ञानानां ज्ञानमुत्तमम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-1', 'en', 'I will again proclaim that supreme Wisdom, of all wisdom the best, which having known, all the Sages have gone hence to the supreme Perfection.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-2', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 2, 'Chapter 14, Verse 2', 'इदं ज्ञानमुपाश्रित्य मम साधर्म्यमागताः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-2', 'en', 'Having taken refuge in this Wisdom and being assimilated to My own nature, they are not re-born even in the emanation of a universe, nor are disquieted in the dissolution.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-3', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 3, 'Chapter 14, Verse 3', 'मम योनिर्महद्ब्रह्म तस्मिन्गर्भं दधाम्यहम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-3', 'en', 'My womb is the great Eternal; in that I place the germ; thence cometh the birth of all beings, O Bhârata.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-4', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 4, 'Chapter 14, Verse 4', 'सर्वयोनिषु कौन्तेय मूर्तयः संभवन्ति याः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-4', 'en', 'In whatsoever wombs mortals are produced, O Kaunteya, the great Eternal is their womb, I their generating father.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-5', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 5, 'Chapter 14, Verse 5', 'सत्त्वं रजस्तम इति गुणाः प्रकृतिसंभवाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-5', 'en', 'Harmony, Motion, Inertia, such are the qualities, Matter-born; they bind fast in the body, O great-armed one, the indestructible dweller in the body.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-6', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 6, 'Chapter 14, Verse 6', 'तत्र सत्त्वं निर्मलत्वात्प्रकाशकमनामयम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-6', 'en', 'Of these Harmony from its stainlessness, luminous and healthy, bindeth by the attachment to bliss and the attachment to wisdom, O sinless one.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-7', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 7, 'Chapter 14, Verse 7', 'रजो रागात्मकं विद्धि तृष्णासङ्गसमुद्भवम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-7', 'en', 'Motion, the passion nature, know thou, is the source of attachment and thirst for life, O Kaunteya, that bindeth the dweller in the body by the attachment to action.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-8', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 8, 'Chapter 14, Verse 8', 'तमस्त्वज्ञानजं विद्धि मोहनं सर्वदेहिनाम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-8', 'en', 'But Inertia, know thou, born of unwisdom, is the deluder of all dwellers in the body; that bindeth by heedlessness, indolence and sloth, O Bhârata.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-9', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 9, 'Chapter 14, Verse 9', 'सत्त्वं सुखे सञ्जयति रजः कर्मणि भारत।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-9', 'en', 'Harmony attacheth to bliss, Motion to action O Bhârata. Inertia, verily, having shrouded wisdom, attacheth on the contrary to heedlessness.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-10', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 10, 'Chapter 14, Verse 10', 'रजस्तमश्चाभिभूय सत्त्वं भवति भारत।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-10', 'en', 'Now Harmony prevaileth, having overpowered Motion and Inertia, O Bhârata; now Motion, having overpowered Harmony and Inertia; and now Inertia, having overpowered Harmony and Motion.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-11', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 11, 'Chapter 14, Verse 11', 'सर्वद्वारेषु देहेऽस्मिन्प्रकाश उपजायते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-11', 'en', 'When the wisdom-light streameth forth from all the gates of the body, then it may be known that Harmony is increasing.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-12', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 12, 'Chapter 14, Verse 12', 'लोभः प्रवृत्तिरारम्भः कर्मणामशमः स्पृहा।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-12', 'en', 'Greed, outgoing energy, undertaking of actions, restlessness, desire—these are born of the increase of Motion, O best of the Bhâratas.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-13', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 13, 'Chapter 14, Verse 13', 'अप्रकाशोऽप्रवृत्तिश्च प्रमादो मोह एव च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-13', 'en', 'Darkness, stagnation and heedlessness and also delusion—these are born of the increase of Inertia, O joy of the Kurus.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-14', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 14, 'Chapter 14, Verse 14', 'यदा सत्त्वे प्रवृद्धे तु प्रलयं याति देहभृत्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-14', 'en', 'If Harmony verily prevaileth when the embodied goeth to dissolution, then he goeth forth to the spotless worlds of the great Sages.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-15', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 15, 'Chapter 14, Verse 15', 'रजसि प्रलयं गत्वा कर्मसङ्गिषु जायते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-15', 'en', 'Having gone to dissolution in Motion, he is born among those attached to action; if dissolved in Inertia, he is born in the wombs of the senseless.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-16', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 16, 'Chapter 14, Verse 16', 'कर्मणः सुकृतस्याहुः सात्त्विकं निर्मलं फलम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-16', 'en', 'It is said the fruit of a good action is harmonious and spotless; verily the fruit of Motion is pain, and the fruit of Inertia unwisdom.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-17', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 17, 'Chapter 14, Verse 17', 'सत्त्वात्संजायते ज्ञानं रजसो लोभ एव च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-17', 'en', 'From Harmony wisdom is born, and also greed from Motion; heedlessness and delusion are of Inertia and also unwisdom.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-18', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 18, 'Chapter 14, Verse 18', 'ऊर्ध्वं गच्छन्ति सत्त्वस्था मध्ये तिष्ठन्ति राजसाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-18', 'en', 'They rise upwards who are settled in Harmony; the Active dwell in the mid-most place: the Inert go downwards, enveloped in the vilest qualities.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-19', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 19, 'Chapter 14, Verse 19', 'नान्यं गुणेभ्यः कर्तारं यदा द्रष्टानुपश्यति।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-19', 'en', 'When the Seer perceiveth no agent other than the qualities, and knoweth That which is higher than the qualities, he entereth into My Nature.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-20', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 20, 'Chapter 14, Verse 20', 'गुणानेतानतीत्य त्रीन्देही देहसमुद्भवान्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-20', 'en', 'When the dweller in the body hath crossed over these three qualities, whence all bodies have been produced, liberated from birth, death, old age and sorrow, he drinketh the nectar of immortality.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-21', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 21, 'Chapter 14, Verse 21', 'कैर्लिङ्गैस्त्रीन्गुणानेतानतीतो भवति प्रभो।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-21', 'en', 'What are the marks of him who hath crossed over the three qualities, O Lord? How acteth he, and how doth he go beyond these three qualities?', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-22', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 22, 'Chapter 14, Verse 22', 'प्रकाशं च प्रवृत्तिं च मोहमेव च पाण्डव।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-22', 'en', 'He, O Pândava, who hateth not radiance, nor outgoing energy, nor even delusion, when present, nor longeth after them, absent;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-23', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 23, 'Chapter 14, Verse 23', 'उदासीनवदासीनो गुणैर्यो न विचाल्यते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-23', 'en', 'He who, seated as a neutral, is unshaken by the qualities; who, saying, "The qualities revolve," standeth apart immovable.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-24', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 24, 'Chapter 14, Verse 24', 'समदुःखसुखः स्वस्थः समलोष्टाश्मकाञ्चनः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-24', 'en', 'Balanced in pleasure and pain, self-reliant, to whom a lump of earth, a rock and gold are alike, the same to loved and unloved, firm, the same in censure and in praise,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-25', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 25, 'Chapter 14, Verse 25', 'मानावमानयोस्तुल्यस्तुल्यो मित्रारिपक्षयोः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-25', 'en', 'The same in honour and ignominy, the same to friend and foe, abandoning all undertakings—he is said to have crossed over the qualities.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-26', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 26, 'Chapter 14, Verse 26', 'मां च योऽव्यभिचारेण भक्तियोगेन सेवते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-26', 'en', 'And he who serveth Me exclusively by the Yoga of devotion, he, crossing beyond the qualities, he is fit to become the Eternal.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-14-27', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 14), 27, 'Chapter 14, Verse 27', 'ब्रह्मणो हि प्रतिष्ठाहममृतस्याव्ययस्य च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-14-27', 'en', 'For I am the abode of the Eternal, and of the indestructible nectar of immortality, of immemorial righteousness, and of unending bliss.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-15-1', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 15), 1, 'Chapter 15, Verse 1', 'ऊर्ध्वमूलमधःशाखमश्वत्थं प्राहुरव्ययम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-15-1', 'en', 'With roots above, branches below, the Asvattha is said to be indestructible; the leaves of it are hymns; he who knoweth it is a Veda-knower.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-15-2', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 15), 2, 'Chapter 15, Verse 2', 'अधश्चोर्ध्वं प्रसृतास्तस्य शाखा गुणप्रवृद्धा विषयप्रवालाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-15-2', 'en', 'Downwards and upwards spread the branches of it, nourished by the qualities; the objects of the senses its buds; and its roots grow downwards, the bonds of action in the world of men.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-15-3', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 15), 3, 'Chapter 15, Verse 3', 'न रूपमस्येह तथोपलभ्यते नान्तो न चादिर्न च संप्रतिष्ठा।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-15-3', 'en', 'Nor here may be acquired knowledge of its form, nor its end, nor its origin, nor its rooting-place; this strongly rooted Asvattha having been cut down by the unswerving weapon of non-attachment,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-15-4', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 15), 4, 'Chapter 15, Verse 4', 'ततः पदं तत्परिमार्गितव्यं यस्मिन्गता न निवर्तन्ति भूयः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-15-4', 'en', 'That path beyond may be sought, treading which there is no return. I go indeed to that Primal Man, whence the ancient energy forth-streamed.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-15-5', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 15), 5, 'Chapter 15, Verse 5', 'निर्मानमोहा जितसङ्गदोषा अध्यात्मनित्या विनिवृत्तकामाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-15-5', 'en', 'Without pride and delusion, victorious over the vice of attachment, dwelling constantly in the Self, desire pacified, liberated from the pairs of opposites known as pleasure and pain, they tread, undeluded, that indestructible path.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-15-6', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 15), 6, 'Chapter 15, Verse 6', 'न तद्भासयते सूर्यो न शशाङ्को न पावकः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-15-6', 'en', 'Nor doth the sun lighten there, nor moon, nor fire; having gone thither they return not; that is My supreme abode.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-15-7', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 15), 7, 'Chapter 15, Verse 7', 'ममैवांशो जीवलोके जीवभूतः सनातनः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-15-7', 'en', 'A portion of Mine own Self, transformed in the world of life into an immortal Spirit, draweth round itself the senses of which the mind is the sixth, veiled in matter.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-15-8', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 15), 8, 'Chapter 15, Verse 8', 'शरीरं यदवाप्नोति यच्चाप्युत्क्रामतीश्वरः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-15-8', 'en', 'When the Lord acquireth a body and when He abandoneth it, He seizeth these and goeth with them, as the wind takes fragrances from their retreats.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-15-9', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 15), 9, 'Chapter 15, Verse 9', 'श्रोत्रं चक्षुः स्पर्शनं च रसनं घ्राणमेव च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-15-9', 'en', 'Enshrined in the ear, the eye, the touch, the taste and the smell, and in the mind also, He enjoyeth the objects of the senses.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-15-10', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 15), 10, 'Chapter 15, Verse 10', 'उत्क्रामन्तं स्थितं वापि भुञ्जानं वा गुणान्वितम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-15-10', 'en', 'The deluded do not perceive (Him) when He departeth or stayeth or enjoyeth, swayed by the qualities; the wisdom-eyed perceive.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-15-11', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 15), 11, 'Chapter 15, Verse 11', 'यतन्तो योगिनश्चैनं पश्यन्त्यात्मन्यवस्थितम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-15-11', 'en', 'Yogîs also, struggling, perceive Him, established in the Self; but though struggling, the unintelligent perceive Him not, their selves untrained.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-15-12', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 15), 12, 'Chapter 15, Verse 12', 'यदादित्यगतं तेजो जगद्भासयतेऽखिलम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-15-12', 'en', 'That splendour issuing from the sun that enlighteneth the whole world, that which is in the moon and in fire, that splendour know as from Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-15-13', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 15), 13, 'Chapter 15, Verse 13', 'गामाविश्य च भूतानि धारयाम्यहमोजसा।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-15-13', 'en', 'Permeating the soil, I support beings by my vital energy, and having become the delicious Soma I nourish all plants.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-15-14', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 15), 14, 'Chapter 15, Verse 14', 'अहं वैश्वानरो भूत्वा प्राणिनां देहमाश्रितः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-15-14', 'en', 'I, having become the Fire of Life, take possession of the bodies of breathing things, and united with the life-breaths, I digest the four kinds of food.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-15-15', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 15), 15, 'Chapter 15, Verse 15', 'सर्वस्य चाहं हृदि संनिविष्टो मत्तः स्मृतिर्ज्ञानमपोहनं च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-15-15', 'en', 'And I am seated in the hearts of all, and from Me memory and wisdom and their absence. And that which is to be known in all the Vedas am I; and I indeed the Veda-knower and the author of the Vedanta.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-15-16', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 15), 16, 'Chapter 15, Verse 16', 'द्वाविमौ पुरुषौ लोके क्षरश्चाक्षर एव च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-15-16', 'en', 'There are two Energies in this world, the destructible and the indestructible; the destructible is all beings, the unchanging is called the indestructible.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-15-17', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 15), 17, 'Chapter 15, Verse 17', 'उत्तमः पुरुषस्त्वन्यः परमात्मेत्युदाहृतः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-15-17', 'en', 'The highest Energy is verily Another, declared as the Supreme Self, He who, pervading all, sustaineth the three worlds, the indestructible Lord.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-15-18', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 15), 18, 'Chapter 15, Verse 18', 'यस्मात्क्षरमतीतोऽहमक्षरादपि चोत्तमः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-15-18', 'en', 'Since I excel the destructible, and am more excellent also than the indestructible, in the world and in the Veda I am proclaimed the Supreme Spirit.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-15-19', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 15), 19, 'Chapter 15, Verse 19', 'यो मामेवमसंमूढो जानाति पुरुषोत्तमम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-15-19', 'en', 'He who undeluded knoweth Me thus as the Supreme Spirit, he, all-knowing, worshippeth Me with his whole being, O Bhârata.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-15-20', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 15), 20, 'Chapter 15, Verse 20', 'इति गुह्यतमं शास्त्रमिदमुक्तं मयानघ।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-15-20', 'en', 'Thus by Me this most secret teaching hath been told O sinless one. This known, he hath become illuminated and hath finished his work, O Bhârata.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-16-1', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 16), 1, 'Chapter 16, Verse 1', 'अभयं सत्त्वसंशुद्धिर्ज्ञानयोगव्यवस्थितिः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-16-1', 'en', 'Fearlessness, cleanness of life, steadfastness in the Yoga of wisdom, almsgiving, self-restraint and sacrifice and study of the Scriptures, austerity and straightforwardness,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-16-2', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 16), 2, 'Chapter 16, Verse 2', 'अहिंसा सत्यमक्रोधस्त्यागः शान्तिरपैशुनम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-16-2', 'en', 'Harmlessness, truth, absence of wrath, renunciation, peacefulness, absence of crookedness, compassion to living beings, uncovetousness, mildness, modesty, absence of fickleness,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-16-3', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 16), 3, 'Chapter 16, Verse 3', 'तेजः क्षमा धृतिः शौचमद्रोहो नातिमानिता।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-16-3', 'en', 'Vigour, forgiveness, fortitude, purity, absence of envy and pride—these are his who is born with the divine properties, O Bhârata.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-16-4', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 16), 4, 'Chapter 16, Verse 4', 'दम्भो दर्पोऽतिमानश्च क्रोधः पारुष्यमेव च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-16-4', 'en', 'Hypocrisy, arrogance and conceit, wrath and also harshness and unwisdom are his who is born, O Pârtha, with demoniacal properties.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-16-5', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 16), 5, 'Chapter 16, Verse 5', 'दैवी संपद्विमोक्षाय निबन्धायासुरी मता।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-16-5', 'en', 'The divine properties are deemed to be for liberation, the demoniacal for bondage. Grieve not, thou art born with divine properties, O Pândava.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-16-6', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 16), 6, 'Chapter 16, Verse 6', 'द्वौ भूतसर्गौ लोकेऽस्मिन्दैव आसुर एव च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-16-6', 'en', 'Twofold is the animal creation in this world, the divine and the demoniacal: the divine hath been described at length: hear from Me, O Pârtha, the demoniacal.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-16-7', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 16), 7, 'Chapter 16, Verse 7', 'प्रवृत्तिं च निवृत्तिं च जना न विदुरासुराः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-16-7', 'en', 'Demoniacal men know neither right energy nor right abstinence; nor purity, nor even propriety, nor truth is in them.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-16-8', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 16), 8, 'Chapter 16, Verse 8', 'असत्यमप्रतिष्ठं ते जगदाहुरनीश्वरम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-16-8', 'en', '"The universe is without truth, without basis," they say, "without a God; brought about by mutual union, and caused by lust and nothing else."', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-16-9', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 16), 9, 'Chapter 16, Verse 9', 'एतां दृष्टिमवष्टभ्य नष्टात्मानोऽल्पबुद्धयः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-16-9', 'en', 'Holding this view, these ruined selves of small understanding, of fierce deeds, come forth as enemies for the destruction of the world.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-16-10', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 16), 10, 'Chapter 16, Verse 10', 'काममाश्रित्य दुष्पूरं दम्भमानमदान्विताः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-16-10', 'en', 'Surrendering themselves to insatiable desires, possessed with vanity, conceit and arrogance, holding evil ideas through delusion, they engage in action with impure resolves.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-16-11', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 16), 11, 'Chapter 16, Verse 11', 'चिन्तामपरिमेयां च प्रलयान्तामुपाश्रिताः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-16-11', 'en', 'Giving themselves over to unmeasured thought whose end is death, regarding the gratification of desires as the highest, feeling sure that this is all,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-16-12', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 16), 12, 'Chapter 16, Verse 12', 'आशापाशशतैर्बद्धाः कामक्रोधपरायणाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-16-12', 'en', 'Held in bondage by a hundred ties of expectation, given over to lust and anger, they strive to obtain by unlawful means hoards of wealth for sensual enjoyments.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-16-13', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 16), 13, 'Chapter 16, Verse 13', 'इदमद्य मया लब्धमिदं प्राप्स्ये मनोरथम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-16-13', 'en', '"This to-day by me hath been won, that purpose I shall gain; this wealth is mine already, and also this shall be mine in future.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-16-14', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 16), 14, 'Chapter 16, Verse 14', 'असौ मया हतः शत्रुर्हनिष्ये चापरानपि।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-16-14', 'en', '"I have slain this enemy, and others also I shall slay. I am the Lord, I am the enjoyer, I am perfect, powerful, happy;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-16-15', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 16), 15, 'Chapter 16, Verse 15', 'आढ्योऽभिजनवानस्मि कोऽन्योऽस्ति सदृशो मया।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-16-15', 'en', '"I am wealthy, well-born; what other is there that is like unto me? I will sacrifice, I will give alms, I will rejoice." Thus deluded by unwisdom,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-16-16', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 16), 16, 'Chapter 16, Verse 16', 'अनेकचित्तविभ्रान्ता मोहजालसमावृताः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-16-16', 'en', 'Bewildered by numerous thoughts, enmeshed in the web of delusion, addicted to the gratification of desire, they fall downwards into a foul hell.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-16-17', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 16), 17, 'Chapter 16, Verse 17', 'आत्मसंभाविताः स्तब्धा धनमानमदान्विताः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-16-17', 'en', 'Self-glorifying, stubborn, filled with the pride and intoxication of wealth, they perform lip-sacrifices for ostentation, contrary to scriptural ordinance.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-16-18', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 16), 18, 'Chapter 16, Verse 18', 'अहंकारं बलं दर्पं कामं क्रोधं च संश्रिताः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-16-18', 'en', 'Given over to egoism, power, insolence, lust and wrath, these malicious ones hate Me in the bodies of others and in their own.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-16-19', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 16), 19, 'Chapter 16, Verse 19', 'तानहं द्विषतः क्रूरान्संसारेषु नराधमान्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-16-19', 'en', 'These haters, evil, pitiless, vilest among men in the world, I ever throw down into demoniacal wombs.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-16-20', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 16), 20, 'Chapter 16, Verse 20', 'आसुरीं योनिमापन्ना मूढा जन्मनि जन्मनि।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-16-20', 'en', 'Cast into demoniacal wombs, deluded birth after birth, attaining not to Me, O Kaunteya, they sink into the lowest depths.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-16-21', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 16), 21, 'Chapter 16, Verse 21', 'त्रिविधं नरकस्येदं द्वारं नाशनमात्मनः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-16-21', 'en', 'Triple is the gate of this hell, destructive of the self—lust, wrath, and greed; therefore let man renounce these three.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-16-22', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 16), 22, 'Chapter 16, Verse 22', 'एतैर्विमुक्तः कौन्तेय तमोद्वारैस्त्रिभिर्नरः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-16-22', 'en', 'A man liberated from these three gates of darkness, O son of Kunti, accomplisheth his own welfare, and thus reacheth the highest goal.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-16-23', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 16), 23, 'Chapter 16, Verse 23', 'यः शास्त्रविधिमुत्सृज्य वर्तते कामकारतः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-16-23', 'en', 'He who, having cast aside the ordinances of the Scriptures, followeth the promptings of desire, attaineth not to perfection, nor happiness, nor the highest goal.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-16-24', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 16), 24, 'Chapter 16, Verse 24', 'तस्माच्छास्त्रं प्रमाणं ते कार्याकार्यव्यवस्थितौ।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-16-24', 'en', 'Therefore let the Scriptures be thy authority, in determining what ought to be done, or what ought not to be done. Knowing what hath been declared by the ordinances of the Scriptures, thou oughtest to work in this world.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-1', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 1, 'Chapter 17, Verse 1', 'ये शास्त्रविधिमुत्सृज्य यजन्ते श्रद्धयान्विताः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-1', 'en', 'Those that sacrifice full of faith, but casting aside the ordinances of the Scriptures, what is verily their condition, O Krishna? Is it one of Purity, Passion, or Darkness?', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-2', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 2, 'Chapter 17, Verse 2', 'त्रिविधा भवति श्रद्धा देहिनां सा स्वभावजा।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-2', 'en', 'Threefold is by nature the inborn faith of the embodied—pure, passionate, and dark. Hear thou of these.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-3', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 3, 'Chapter 17, Verse 3', 'सत्त्वानुरूपा सर्वस्य श्रद्धा भवति भारत।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-3', 'en', 'The faith of each is shaped to his own nature, O Bhârata. The man consists of his faith; that which his faith is, he is even that.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-4', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 4, 'Chapter 17, Verse 4', 'यजन्ते सात्त्विका देवान्यक्षरक्षांसि राजसाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-4', 'en', 'Pure men worship the Gods; the passionate the gnomes and giants; the others, the dark folk, worship ghosts and troops of nature-spirits.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-5', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 5, 'Chapter 17, Verse 5', 'अशास्त्रविहितं घोरं तप्यन्ते ये तपो जनाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-5', 'en', 'The men who perform severe austerities, unenjoined by the Scriptures, wedded to vanity and egoism, impelled by the force of their desires and passions,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-6', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 6, 'Chapter 17, Verse 6', 'कर्शयन्तः शरीरस्थं भूतग्राममचेतसः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-6', 'en', 'Unintelligent, tormenting the aggregated elements forming the body, and Me also, seated in the inner body, know these demoniacal in their resolves.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-7', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 7, 'Chapter 17, Verse 7', 'आहारस्त्वपि सर्वस्य त्रिविधो भवति प्रियः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-7', 'en', 'The food also which is dear to each is threefold, as also sacrifice, austerity and almsgiving. Hear thou the distinction of these.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-8', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 8, 'Chapter 17, Verse 8', 'आयुःसत्त्वबलारोग्यसुखप्रीतिविवर्धनाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-8', 'en', 'The foods that augment vitality, energy, vigour, health, joy and cheerfulness, delicious, bland, substantial and agreeable, are dear to the pure.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-9', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 9, 'Chapter 17, Verse 9', 'कट्वम्ललवणात्युष्णतीक्ष्णरूक्षविदाहिनः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-9', 'en', 'The passionate desire foods that are bitter, sour, saline, over-hot, pungent, dry and burning and which produce pain, grief and sickness.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-10', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 10, 'Chapter 17, Verse 10', 'यातयामं गतरसं पूति पर्युषितं च यत्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-10', 'en', 'That which is stale and flat, putrid and corrupt, leavings also and unclean, is the food dear to the dark.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-11', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 11, 'Chapter 17, Verse 11', 'अफलाकाङ्क्षिभिर्यज्ञो विधिदृष्टो य इज्यते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-11', 'en', 'The sacrifice which is offered by men without desire for fruit, as enjoined by the ordinances, under the firm belief that sacrifice is a duty, that is pure.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-12', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 12, 'Chapter 17, Verse 12', 'अभिसंधाय तु फलं दम्भार्थमपि चैव यत्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-12', 'en', 'The sacrifice offered with a view verily to fruit, and also indeed for self-glorification, O best of the Bhâratas; know thou that to be of passion.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-13', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 13, 'Chapter 17, Verse 13', 'विधिहीनमसृष्टान्नं मन्त्रहीनमदक्षिणम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-13', 'en', 'The sacrifice contrary to the ordinances, without distributing food, devoid of words of power and without gifts, empty of faith, is said to be of darkness.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-14', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 14, 'Chapter 17, Verse 14', 'देवद्विजगुरुप्राज्ञपूजनं शौचमार्जवम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-14', 'en', 'Worship given to the Gods, to the twice-born, to the teachers and to the wise, purity, straightforwardness, continence and harmlessness, are called the austerity of the body.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-15', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 15, 'Chapter 17, Verse 15', 'अनुद्वेगकरं वाक्यं सत्यं प्रियहितं च यत्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-15', 'en', 'Speech causing no annoyance, truthful, pleasant and beneficial, the practice of the study of the Scriptures, are called the austerity of speech.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-16', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 16, 'Chapter 17, Verse 16', 'मनःप्रसादः सौम्यत्वं मौनमात्मविनिग्रहः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-16', 'en', 'Mental happiness, equilibrium, silence, self-control, purity of nature—these are called the austerity of the mind.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-17', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 17, 'Chapter 17, Verse 17', 'श्रद्धया परया तप्तं तपस्तत्त्रिविधं नरैः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-17', 'en', 'This threefold austerity, performed by men with the utmost faith, without desire for fruit, harmonised, is said to be pure.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-18', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 18, 'Chapter 17, Verse 18', 'सत्कारमानपूजार्थं तपो दम्भेन चैव यत्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-18', 'en', 'The austerity which is practised with the object of gaining respect, honour and worship, and for ostentation, is said to be of passion, unstable and fleeting.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-19', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 19, 'Chapter 17, Verse 19', 'मूढग्राहेणात्मनो यत्पीडया क्रियते तपः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-19', 'en', 'That austerity done under a deluded understanding, with self-torture, or with the object of destroying another, that is declared of darkness.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-20', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 20, 'Chapter 17, Verse 20', 'दातव्यमिति यद्दानं दीयतेऽनुपकारिणे।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-20', 'en', 'That alms given to one who does nothing in return, believing that a gift ought to be made in a fit place and time to a worthy person, that alms is accounted pure.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-21', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 21, 'Chapter 17, Verse 21', 'यत्तु प्रत्युपकारार्थं फलमुद्दिश्य वा पुनः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-21', 'en', 'That given with a view to receiving in return, or looking for fruit again, or grudgingly, that alms is accounted of passion.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-22', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 22, 'Chapter 17, Verse 22', 'अदेशकाले यद्दानमपात्रेभ्यश्च दीयते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-22', 'en', 'That alms given at unfit place and time, and to unworthy persons, disrespectfully and contemptuously, that is declared of darkness.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-23', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 23, 'Chapter 17, Verse 23', 'ॐ तत्सदिति निर्देशो ब्रह्मणस्त्रिविधः स्मृतः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-23', 'en', '"Aum Tat Sat," this has been considered to be the threefold designation of the Eternal. By that were ordained of old Brâhmanas, Vedas and sacrifices.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-24', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 24, 'Chapter 17, Verse 24', 'तस्मादोमित्युदाहृत्य यज्ञदानतपःक्रियाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-24', 'en', 'Therefore with the pronunciation of "Aum" the acts of sacrifice, gift and austerity as laid down in the ordinances are always commenced by the knowers of the Eternal.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-25', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 25, 'Chapter 17, Verse 25', 'तदित्यनभिसंधाय फलं यज्ञतपःक्रियाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-25', 'en', 'With the pronunciation of "Tat" and without aiming at fruit are performed the various acts of sacrifice, austerity and gift, by those desiring liberation.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-26', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 26, 'Chapter 17, Verse 26', 'सद्भावे साधुभावे च सदित्येतत्प्रयुज्यते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-26', 'en', '"Sat" is used in the sense of reality and goodness; likewise, O Pârtha, the word "Sat" is used in the sense of a good work.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-27', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 27, 'Chapter 17, Verse 27', 'यज्ञे तपसि दाने च स्थितिः सदिति चोच्यते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-27', 'en', 'Steadfastness in sacrifice, austerity and gift is also called "Sat", and action for the sake of the Supreme is also named "Sat."', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-17-28', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 17), 28, 'Chapter 17, Verse 28', 'अश्रद्धया हुतं दत्तं तपस्तप्तं कृतं च यत्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-17-28', 'en', 'Whatsoever is wrought without faith, oblation, gift, austerity, or other deed, "Asat" it is called, O Pârtha; it is nought, here or hereafter.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-1', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 1, 'Chapter 18, Verse 1', 'संन्यासस्य महाबाहो तत्त्वमिच्छामि वेदितुम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-1', 'en', 'I desire, O mighty-armed, to know severally the essence of renunciation, O Hrishîkesha, and of relinquishment, O Keshinishûdana.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-2', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 2, 'Chapter 18, Verse 2', 'काम्यानां कर्मणां न्यासं संन्यासं कवयो विदुः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-2', 'en', 'Sages have known as renunciation the renouncing of works with desire; the relinquishing of the fruit of all actions is called relinquishment by the wise.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-3', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 3, 'Chapter 18, Verse 3', 'त्याज्यं दोषवदित्येके कर्म प्राहुर्मनीषिणः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-3', 'en', '"Action should be relinquished as an evil," declare some thoughtful men; "acts of sacrifice, gift and austerity should not be relinquished," say others.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-4', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 4, 'Chapter 18, Verse 4', 'निश्चयं शृणु मे तत्र त्यागे भरतसत्तम।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-4', 'en', 'Hear my conclusions as to that relinquishment, O best of the Bhâratas; since relinquishment, O tiger of men, has been explained as threefold.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-5', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 5, 'Chapter 18, Verse 5', 'यज्ञदानतपःकर्म न त्याज्यं कार्यमेव तत्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-5', 'en', 'Acts of sacrifice, gift and austerity should not be relinquished, but should be performed; sacrifice, gift and also austerity are the purifiers of the intelligent.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-6', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 6, 'Chapter 18, Verse 6', 'एतान्यपि तु कर्माणि सङ्गं त्यक्त्वा फलानि च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-6', 'en', 'But even these actions should be done leaving aside attachment and fruit, O Pârtha; that is my certain and best belief.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-7', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 7, 'Chapter 18, Verse 7', 'नियतस्य तु संन्यासः कर्मणो नोपपद्यते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-7', 'en', 'Verily renunciation of actions that are prescribed is not proper; the relinquishment thereof from delusion is said to be of darkness.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-8', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 8, 'Chapter 18, Verse 8', 'दुःखमित्येव यत्कर्म कायक्लेशभयात्त्यजेत्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-8', 'en', 'He who relinquisheth an action from fear of physical suffering, saying "Painful," thus performing a passionate relinquishment, obtaineth not the fruit of relinquishment.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-9', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 9, 'Chapter 18, Verse 9', 'कार्यमित्येव यत्कर्म नियतं क्रियतेऽर्जुन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-9', 'en', 'He who performeth a prescribed action, saying, "it ought to be done," O Arjuna, relinquishing attachment and also fruit, that relinquishment is regarded as pure.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-10', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 10, 'Chapter 18, Verse 10', 'न द्वेष्ट्यकुशलं कर्म कुशले नानुषज्जते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-10', 'en', 'The relinquisher pervaded by purity, intelligent and with doubts cut away, hateth not unpleasurable action nor is attached to pleasurable.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-11', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 11, 'Chapter 18, Verse 11', 'न हि देहभृता शक्यं त्यक्तुं कर्माण्यशेषतः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-11', 'en', 'Nor indeed can embodied beings completely relinquish action; verily he who relinquisheth the fruit of action, he is said to be a relinquisher.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-12', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 12, 'Chapter 18, Verse 12', 'अनिष्टमिष्टं मिश्रं च त्रिविधं कर्मणः फलम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-12', 'en', 'Good, evil and mixed—threefold is the fruit of action hereafter for the non-relinquisher; but there is none ever for the renouncer.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-13', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 13, 'Chapter 18, Verse 13', 'पञ्चैतानि महाबाहो कारणानि निबोध मे।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-13', 'en', 'These five causes, O mighty-armed, learn of Me as declared in the Sâñkhya system for the accomplishment of all actions:', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-14', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 14, 'Chapter 18, Verse 14', 'अधिष्ठानं तथा कर्ता करणं च पृथग्विधम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-14', 'en', 'The body, the actor, the various organs, the diverse kinds of energies, and the presiding deities also, the fifth.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-15', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 15, 'Chapter 18, Verse 15', 'शरीरवाङ्मनोभिर्यत्कर्म प्रारभते नरः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-15', 'en', 'Whatever action a man performeth by his body, speech and mind, whether right or the reverse, these five are the cause thereof.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-16', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 16, 'Chapter 18, Verse 16', 'तत्रैवं सति कर्तारमात्मानं केवलं तु यः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-16', 'en', 'That being so, he verily who—owing to untrained Reason—looketh on his Self, which is isolated, as the actor, he of perverted intelligence, seeth not.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-17', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 17, 'Chapter 18, Verse 17', 'यस्य नाहंकृतो भावो बुद्धिर्यस्य न लिप्यते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-17', 'en', 'He who is free from the egoistic notion, whose Reason is not affected, though he slay these peoples, he slayeth not, nor is bound.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-18', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 18, 'Chapter 18, Verse 18', 'ज्ञानं ज्ञेयं परिज्ञाता त्रिविधा कर्मचोदना।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-18', 'en', 'Knowledge, the knowable and the knower, the threefold impulse to action; the organ, the action, the actor, the threefold constituents of action.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-19', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 19, 'Chapter 18, Verse 19', 'ज्ञानं कर्म च कर्ता च त्रिधैव गुणभेदतः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-19', 'en', 'Knowledge, action and actor in the category of qualities are also said to be severally threefold, from the difference of qualities; hear thou duly these also.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-20', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 20, 'Chapter 18, Verse 20', 'सर्वभूतेषु येनैकं भावमव्ययमीक्षते।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-20', 'en', 'That by which one indestructible Being is seen in all beings, inseparate in the separated, know thou that knowledge as pure.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-21', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 21, 'Chapter 18, Verse 21', 'पृथक्त्वेन तु यज्ज्ञानं नानाभावान्पृथग्विधान्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-21', 'en', 'But that knowledge which regardeth the several manifold existences in all beings as separate, that knowledge know thou as of passion;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-22', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 22, 'Chapter 18, Verse 22', 'यत्तु कृत्स्नवदेकस्मिन्कार्ये सक्तमहैतुकम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-22', 'en', 'While that which clingeth to each one thing as if it were the whole, without reason, without grasping the reality, narrow, that is declared to be dark.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-23', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 23, 'Chapter 18, Verse 23', 'नियतं सङ्गरहितमरागद्वेषतः कृतम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-23', 'en', 'An action which is ordained, done by one undesirous of fruit, devoid of attachment, without love or hate, that is called pure.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-24', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 24, 'Chapter 18, Verse 24', 'यत्तु कामेप्सुना कर्म साहंकारेण वा पुनः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-24', 'en', 'But that action that is done by one longing for desires, or again with egoism, or with much effort, that is declared to be passionate.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-25', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 25, 'Chapter 18, Verse 25', 'अनुबन्धं क्षयं हिंसामनपेक्ष्य च पौरुषम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-25', 'en', 'The action undertaken from delusion, without regard to capacity and consequences—loss and injury to others—that is declared to be dark.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-26', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 26, 'Chapter 18, Verse 26', 'मुक्तसङ्गोऽनहंवादी धृत्युत्साहसमन्वितः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-26', 'en', 'Liberated from attachment, not egoistic, endued with firmness and confidence, unchanged by success or failure, that actor is called pure.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-27', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 27, 'Chapter 18, Verse 27', 'रागी कर्मफलप्रेप्सुर्लुब्धो हिंसात्मकोऽशुचिः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-27', 'en', 'Impassioned, desiring to obtain the fruit of actions, greedy, harmful, impure, moved by joy and sorrow, such an actor is pronounced passionate.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-28', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 28, 'Chapter 18, Verse 28', 'अयुक्तः प्राकृतः स्तब्धः शठो नैकृतिकोऽलसः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-28', 'en', 'Discordant, vulgar, stubborn, cheating, malicious, indolent, despairful, procrastinating, that actor is called dark.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-29', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 29, 'Chapter 18, Verse 29', 'बुद्धेर्भेदं धृतेश्चैव गुणतस्त्रिविधं शृणु।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-29', 'en', 'The division of Reason and of firmness also, threefold according to the qualities, hear thou related, unreservedly and severally, O Dhananjaya.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-30', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 30, 'Chapter 18, Verse 30', 'प्रवृत्तिं च निवृत्तिं च कार्याकार्ये भयाभये।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-30', 'en', 'That which knoweth energy and abstinence, what ought to be done and what ought not to be done, fear and fearlessness, bondage and liberation, that Reason is pure, O Pârtha.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-31', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 31, 'Chapter 18, Verse 31', 'यया धर्ममधर्मं च कार्यं चाकार्यमेव च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-31', 'en', 'That by which one understandeth away Right and Wrong and also what ought to be done and what ought not to be done, that Reason, O Pârtha, is passionate.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-32', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 32, 'Chapter 18, Verse 32', 'अधर्मं धर्ममिति या मन्यते तमसावृता।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-32', 'en', 'That which, enwrapped in darkness, thinketh wrong to be right and seeth all things subverted, that Reason, O Pârtha, is of darkness.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-33', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 33, 'Chapter 18, Verse 33', 'धृत्या यया धारयते मनःप्राणेन्द्रियक्रियाः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-33', 'en', 'The unwavering firmness by which, through Yoga, one restraineth the activity of the mind, of the life breaths and of the sense-organs, that firmness, O Pârtha, is pure.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-34', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 34, 'Chapter 18, Verse 34', 'यया तु धर्मकामार्थान्धृत्या धारयतेऽर्जुन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-34', 'en', 'But the firmness, O Arjuna, by which, from attachment desirous of fruit, one holdeth fast duty, desire and wealth, that firmness, O Pârtha, is passionate.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-35', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 35, 'Chapter 18, Verse 35', 'यया स्वप्नं भयं शोकं विषादं मदमेव च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-35', 'en', 'That by which one from stupidity doth not abandon sleep, fear, grief, despair, and also vanity, that firmness, O Pârtha, is dark.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-36', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 36, 'Chapter 18, Verse 36', 'सुखं त्विदानीं त्रिविधं शृणु मे भरतर्षभ।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-36', 'en', 'And now the threefold kinds of pleasure hear thou from Me, O bull of the Bhâratas. That in which one by practice rejoiceth, and which putteth an end to pain;', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-37', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 37, 'Chapter 18, Verse 37', 'यत्तदग्रे विषमिव परिणामेऽमृतोपमम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-37', 'en', 'Which at first is as venom but in the end is as nectar; that pleasure is said to be pure, born of the blissful knowledge of the Self.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-38', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 38, 'Chapter 18, Verse 38', 'विषयेन्द्रियसंयोगाद्यत्तदग्रेऽमृतोपमम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-38', 'en', 'That which from the union of the senses with their objects at first is as nectar, but in the end is like venom, that pleasure is accounted passionate.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-39', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 39, 'Chapter 18, Verse 39', 'यदग्रे चानुबन्धे च सुखं मोहनमात्मनः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-39', 'en', 'That pleasure which both at first and afterwards is delusive of the self, arising from sleep, indolence and heedlessness, that is declared dark.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-40', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 40, 'Chapter 18, Verse 40', 'न तदस्ति पृथिव्यां वा दिवि देवेषु वा पुनः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-40', 'en', 'There is not an entity, either on the earth or again in heaven among the Shining Ones, that is liberated from these three qualities, born of Matter.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-41', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 41, 'Chapter 18, Verse 41', 'ब्राह्मणक्षत्रियविशां शूद्राणां च परंतप।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-41', 'en', 'Of Brâhmanas, Kshattriyas, Vaishyas and Shûdras, O Parantapa, the duties have been distributed, according to the qualities born of their own natures.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-42', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 42, 'Chapter 18, Verse 42', 'शमो दमस्तपः शौचं क्षान्तिरार्जवमेव च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-42', 'en', 'Serenity, self-restraint, austerity, purity, forgiveness and also uprightness, wisdom, knowledge, belief in God, are the Brâhmana duty, born of his own nature.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-43', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 43, 'Chapter 18, Verse 43', 'शौर्यं तेजो धृतिर्दाक्ष्यं युद्धे चाप्यपलायनम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-43', 'en', 'Prowess, splendour, firmness, dexterity, and also not flying from battle, generosity, the nature of a ruler, are the Kshattriya duty, born of his own nature.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-44', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 44, 'Chapter 18, Verse 44', 'कृषिगोरक्ष्यवाणिज्यं वैश्यकर्म स्वभावजम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-44', 'en', 'Ploughing, protection of kine, and trade are the Vaishya duty, born of his own nature. Action of the nature of service is the Shûdra duty, born of his own nature.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-45', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 45, 'Chapter 18, Verse 45', 'स्वे स्वे कर्मण्यभिरतः संसिद्धिं लभते नरः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-45', 'en', 'Man reacheth perfection by each being intent on his own duty. Listen thou how perfection is won by him who is intent on his own duty.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-46', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 46, 'Chapter 18, Verse 46', 'यतः प्रवृत्तिर्भूतानां येन सर्वमिदं ततम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-46', 'en', 'He from whom is the emanation of beings, by Whom all This is pervaded, by worshipping Him in his own duty a man winneth perfection.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-47', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 47, 'Chapter 18, Verse 47', 'श्रेयान्स्वधर्मो विगुणः परधर्मात्स्वनुष्ठितात्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-47', 'en', 'Better is one''s own duty though destitute of merits than the well-executed duty of another. He who doeth the duty laid down by his own nature incurreth not sin.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-48', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 48, 'Chapter 18, Verse 48', 'सहजं कर्म कौन्तेय सदोषमपि न त्यजेत्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-48', 'en', 'Congenital duty, O son of Kunti, though defective, ought not to be abandoned. All undertakings indeed are clouded by defects as fire by smoke.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-49', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 49, 'Chapter 18, Verse 49', 'असक्तबुद्धिः सर्वत्र जितात्मा विगतस्पृहः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-49', 'en', 'He whose Reason is everywhere unattached, the self-subdued, dead to desires, he goeth by renunciation to the supreme perfection of freedom from obligation.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-50', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 50, 'Chapter 18, Verse 50', 'सिद्धिं प्राप्तो यथा ब्रह्म तथाप्नोति निबोध मे।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-50', 'en', 'How he who hath attained perfection obtaineth the Eternal, that highest state of wisdom, learn thou from Me only succinctly, O Kaunteya.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-51', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 51, 'Chapter 18, Verse 51', 'बुद्ध्या विशुद्धया युक्तो धृत्यात्मानं नियम्य च।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-51', 'en', 'United to this Reason, purified, controlling the self by firmness, having abandoned sound and the other objects of the senses, having laid aside passion and malice,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-52', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 52, 'Chapter 18, Verse 52', 'विविक्तसेवी लघ्वाशी यतवाक्कायमानसः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-52', 'en', 'Dwelling in solitude, abstemious, speech, body and mind subdued, constantly fixed in meditation and yoga, taking refuge in dispassion,', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-53', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 53, 'Chapter 18, Verse 53', 'अहंकारं बलं दर्पं कामं क्रोधं परिग्रहम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-53', 'en', 'Having cast aside egoism, violence, arrogance, desire, wrath, covetousness, selfless and peaceful—he is fit to become the Eternal.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-54', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 54, 'Chapter 18, Verse 54', 'ब्रह्मभूतः प्रसन्नात्मा न शोचति न काङ्क्षति।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-54', 'en', 'Becoming the Eternal, serene in the Self, he neither grieveth nor desireth; the same to all beings, he obtaineth supreme devotion unto Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-55', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 55, 'Chapter 18, Verse 55', 'भक्त्या मामभिजानाति यावान्यश्चास्मि तत्त्वतः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-55', 'en', 'By devotion he knoweth Me in essence, who and what I am; having thus known Me in essence he forthwith entereth into the Supreme.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-56', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 56, 'Chapter 18, Verse 56', 'सर्वकर्माण्यपि सदा कुर्वाणो मद्व्यपाश्रयः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-56', 'en', 'Though ever performing all actions, taking refuge in Me, by My grace he obtaineth the eternal indestructible abode.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-57', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 57, 'Chapter 18, Verse 57', 'चेतसा सर्वकर्माणि मयि संन्यस्य मत्परः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-57', 'en', 'Renouncing mentally all works in Me, intent on Me, resorting to the yoga of discrimination, have thy thought ever on Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-58', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 58, 'Chapter 18, Verse 58', 'मच्चित्तः सर्वदुर्गाणि मत्प्रसादात्तरिष्यसि।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-58', 'en', 'Thinking on Me, thou shalt overcome all obstacles by My grace: but if from egoism thou wilt not listen, thou shalt be destroyed utterly.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-59', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 59, 'Chapter 18, Verse 59', 'यदहंकारमाश्रित्य न योत्स्य इति मन्यसे।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-59', 'en', 'Entrenched in egoism, thou thinkest, "I will not fight;" to no purpose thy determination; nature will constrain thee.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-60', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 60, 'Chapter 18, Verse 60', 'स्वभावजेन कौन्तेय निबद्धः स्वेन कर्मणा।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-60', 'en', 'O son of Kuntî, bound by thine own duty born of thine own nature, that which from delusion thou desirest not to do, even that helplessly thou shalt perform.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-61', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 61, 'Chapter 18, Verse 61', 'ईश्वरः सर्वभूतानां हृद्देशेऽर्जुन तिष्ठति।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-61', 'en', 'The Lord dwelleth in the hearts of all beings, O Arjuna, by His illusive Power causing all beings to revolve, as though mounted on a potter''s wheel.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-62', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 62, 'Chapter 18, Verse 62', 'तमेव शरणं गच्छ सर्वभावेन भारत।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-62', 'en', 'Flee unto Him for shelter with all thy being, O Bhârata; by His grace thou shalt obtain supreme peace, the everlasting dwelling-place.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-63', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 63, 'Chapter 18, Verse 63', 'इति ते ज्ञानमाख्यातं गुह्याद्गुह्यतरं मया।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-63', 'en', 'Thus hath wisdom, more secret than secrecy itself, been declared unto thee by Me; having reflected on it fully, then act thou as thou listest.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-64', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 64, 'Chapter 18, Verse 64', 'सर्वगुह्यतमं भूयः शृणु मे परमं वचः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-64', 'en', 'Listen thou again to My supreme word, most secret of all; beloved art thou of Me, and steadfast of heart, therefore will I speak for thy benefit.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-65', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 65, 'Chapter 18, Verse 65', 'मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-65', 'en', 'Merge thy mind in Me, be my devotee, sacrifice to Me, prostrate thyself before Me, thou shalt come even to Me. I pledge thee My troth; thou art dear to Me.', 'besant-1922', true);
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-66', 'en', 'Abandoning all duties come unto Me alone for shelter; sorrow not, I will liberate thee from all sins.', 'besant-1922', false);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-67', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 67, 'Chapter 18, Verse 67', 'इदं ते नातपस्काय नाभक्ताय कदा चन।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-67', 'en', 'Never is this to be spoken by thee to anyone who is without asceticism, nor without devotion, nor to one who desireth not to listen, nor yet to him who speaketh evil of Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-68', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 68, 'Chapter 18, Verse 68', 'य इदं परमं गुह्यं मद्भक्तेष्वभिधास्यति।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-68', 'en', 'He who shall declare this supreme secret among My devotees, having shown the highest devotion for Me, without doubt he shall come to Me.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-69', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 69, 'Chapter 18, Verse 69', 'न च तस्मान्मनुष्येषु कश्चिन्मे प्रियकृत्तमः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-69', 'en', 'Nor is there any among men who performeth dearer service to Me than he, nor any other shall be more beloved by Me on earth than he.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-70', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 70, 'Chapter 18, Verse 70', 'अध्येष्यते च य इमं धर्म्यं संवादमावयोः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-70', 'en', 'And he who shall study this sacred dialogue of ours, by him I shall be worshipped with the sacrifice of wisdom. Such is My mind.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-71', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 71, 'Chapter 18, Verse 71', 'श्रद्धावाननसूयश्च शृणुयादपि यो नरः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-71', 'en', 'The man also who, full of faith, merely heareth it unreviling, even he, freed from evil, obtaineth the radiant worlds of the righteous.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-72', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 72, 'Chapter 18, Verse 72', 'कच्चिदेतच्छ्रुतं पार्थ त्वयैकाग्रेण चेतसा।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-72', 'en', 'Hath this been heard, O son of Prithâ, with one-pointed mind? Has thy delusion, caused by unwisdom, been destroyed, O Dhananjaya?', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-73', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 73, 'Chapter 18, Verse 73', 'नष्टो मोहः स्मृतिर्लब्धा त्वत्प्रसादान्मयाच्युत।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-73', 'en', 'Destroyed is my delusion. I have gained knowledge through Thy grace, O Immutable one. I am firm, my doubts have fled away. I will do according to Thy word.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-74', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 74, 'Chapter 18, Verse 74', 'इत्यहं वासुदेवस्य पार्थस्य च महात्मनः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-74', 'en', 'I heard this marvellous dialogue of Vâsudeva, and of the great-souled Partha, causing my hair to stand on end.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-75', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 75, 'Chapter 18, Verse 75', 'व्यासप्रसादाच्छ्रुतवानेतद्गुह्यमहं परम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-75', 'en', 'By the favour of Vyâsa I listened to this secret and supreme yoga from the Lord of Yoga, Krishna Himself, speaking before mine eyes.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-76', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 76, 'Chapter 18, Verse 76', 'राजन्संस्मृत्य संस्मृत्य संवादमिममद्भुतम्।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-76', 'en', 'O King, remembering, remembering this marvellous and holy dialogue between Keshava and Arjuna, I rejoice again and again.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-77', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 77, 'Chapter 18, Verse 77', 'तच्च संस्मृत्य संस्मृत्य रूपमत्यद्भुतं हरेः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-77', 'en', 'Remembering, remembering, also that most marvellous form of Hari, great is my wonder, O King. I rejoice, again and again.', 'besant-1922', true);
insert into verses (id, scripture_id, section_id, number, reference, sanskrit, transliteration, speaker, sort_key, is_featured, source_id, status) values ('gita-18-78', 'bhagavad-gita', (select id from sections where scripture_id = 'bhagavad-gita' and level = 1 and number = 18), 78, 'Chapter 18, Verse 78', 'यत्र योगेश्वरः कृष्णो यत्र पार्थो धनुर्धरः।
insert into translations (verse_id, language, text, source_id, is_primary) values ('gita-18-78', 'en', 'Wherever is Krishna, Yoga''s Lord, wherever is Pârtha, the archer, assured are there prosperity, victory and happiness. So I think.', 'besant-1922', true);
